{
  "name": "JurisControl - Gestor de Prazos Dinâmico",
  "description": "Sistema avançado para advogados gerenciarem prazos processuais com relatórios automáticos por empresa, métricas de produtividade e interface simplificada."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum DeadlineStatus {
  PENDING = 'PENDENTE',
  COMPLETED = 'CONCLUÍDO',
  OVERDUE = 'ATRASADO'
}

export interface Deadline {
  id: string;
  peca: string;
  responsavel: string;
  empresa: string;
  instituicao: string;
  assunto: string;
  data: string;
  hora: string;
  status: DeadlineStatus;
  createdAt: string;
}

export interface ReportStats {
  total: number;
  concluidos: number;
  pendentes: number;
  atrasados: number;
}

import React from 'react';

export const COLORS = {
  primary: '#1e293b', // slate-800
  secondary: '#334155', // slate-700
  accent: '#3b82f6', // blue-500
  success: '#10b981', // emerald-500
  warning: '#f59e0b', // amber-500
  danger: '#ef4444', // red-500
};

export const PECA_OPTIONS = [
  'Parecer Jurídico',
  'Mandado de Segurança',
  'Defesa Prévia',
  'Exceção de Pré-Executividade',
  'Embargos à Execução',
  'Requerimento de Revisão de Créditos',
  'Contranotificação / Manifestação',
  'Contrarrazões a Recurso Administrativo',
  'Recurso Administrativo',
  'Impugnação ao Edital',
  'Ofício',
  'Defesa'
];

export const RESPONSAVEL_OPTIONS = ['EDUARDO', 'DANILO', 'IGOR', 'MARIA'];

export const Icons = {
  Dashboard: () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect width="7" height="9" x="3" y="3" rx="1"/><rect width="7" height="5" x="14" y="3" rx="1"/><rect width="7" height="9" x="14" y="12" rx="1"/><rect width="7" height="5" x="3" y="16" rx="1"/></svg>
  ),
  List: () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="8" x2="21" y1="6" y2="6"/><line x1="8" x2="21" y1="12" y2="12"/><line x1="8" x2="21" y1="18" y2="18"/><line x1="3" x2="3.01" y1="6" y2="6"/><line x1="3" x2="3.01" y1="12" y2="12"/><line x1="3" x2="3.01" y1="18" y2="18"/></svg>
  ),
  Report: () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21.21 15.89A10 10 0 1 1 8 2.83"/><path d="M22 12A10 10 0 0 0 12 2v10z"/></svg>
  ),
  Plus: () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14"/><path d="M12 5v14"/></svg>
  ),
  Trash: () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"/><line x1="10" x2="10" y1="11" y2="17"/><line x1="14" x2="14" y1="11" y2="17"/></svg>
  ),
  Check: () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
  ),
  Clock: () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
  )
};

import { GoogleGenAI } from "@google/genai";

export const getLegalInsights = async (deadlines: any[]) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prompt = `Analise os seguintes prazos processuais de um escritório de advocacia e forneça um breve resumo (3 frases) sobre a carga de trabalho e se há algum risco iminente. Prazos: ${JSON.stringify(deadlines.map(d => ({ peca: d.peca, data: d.data, empresa: d.empresa })))}`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Não foi possível gerar insights automáticos no momento.";
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Deadline, 
  DeadlineStatus 
} from './types';
import { 
  Icons, 
  COLORS, 
  PECA_OPTIONS, 
  RESPONSAVEL_OPTIONS 
} from './constants';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer, 
  PieChart, 
  Pie, 
  Cell 
} from 'recharts';

// --- Components ---

const Sidebar = ({ currentView, setView }: { currentView: string, setView: (v: string) => void }) => (
  <aside className="w-64 bg-slate-900 text-white min-h-screen flex flex-col fixed left-0 top-0">
    <div className="p-6">
      <h1 className="text-xl font-bold flex items-center gap-2 tracking-tight">
        <span className="bg-blue-600 p-1 rounded">JC</span> JurisControl
      </h1>
    </div>
    <nav className="flex-1 px-4 mt-4 space-y-1">
      <button 
        onClick={() => setView('dashboard')}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${currentView === 'dashboard' ? 'bg-blue-600 shadow-lg' : 'hover:bg-slate-800'}`}
      >
        <Icons.Dashboard /> Dashboard
      </button>
      <button 
        onClick={() => setView('deadlines')}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${currentView === 'deadlines' ? 'bg-blue-600 shadow-lg' : 'hover:bg-slate-800'}`}
      >
        <Icons.List /> Controle Geral
      </button>
      <button 
        onClick={() => setView('reports')}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${currentView === 'reports' ? 'bg-blue-600 shadow-lg' : 'hover:bg-slate-800'}`}
      >
        <Icons.Report /> Relatórios p/ Empresa
      </button>
    </nav>
    <div className="p-4 text-xs text-slate-500 text-center border-t border-slate-800">
      JurisControl v1.0.0
    </div>
  </aside>
);

const Modal = ({ isOpen, onClose, title, children }: { isOpen: boolean, onClose: () => void, title: string, children: React.ReactNode }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl w-full max-w-2xl shadow-2xl animate-in fade-in zoom-in duration-200">
        <div className="p-6 border-b flex justify-between items-center">
          <h2 className="text-xl font-semibold text-slate-800">{title}</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full">&times;</button>
        </div>
        <div className="p-6">
          {children}
        </div>
      </div>
    </div>
  );
};

// --- Main App ---

export default function App() {
  const [view, setView] = useState('dashboard');
  const [deadlines, setDeadlines] = useState<Deadline[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);

  // Form State
  const [newDeadline, setNewDeadline] = useState<Partial<Deadline>>({
    peca: PECA_OPTIONS[0],
    responsavel: RESPONSAVEL_OPTIONS[0],
    empresa: '',
    instituicao: '',
    assunto: '',
    data: new Date().toISOString().split('T')[0],
    hora: '09:00',
    status: DeadlineStatus.PENDING
  });

  // Report Filters
  const [selectedCompany, setSelectedCompany] = useState('Todas');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  // Load Initial Data
  useEffect(() => {
    const saved = localStorage.getItem('juris_deadlines');
    if (saved) {
      setDeadlines(JSON.parse(saved));
    } else {
      // Mock Data based on the user screenshot
      const mock: Deadline[] = [
        { id: '1', peca: 'Parecer Jurídico', responsavel: 'EDUARDO', empresa: 'SOUL', instituicao: 'Bom Jesus dos Perdões/SP', assunto: 'Rescisão contratual e violação ao devido processo legal', data: '2025-06-14', hora: '14:00', status: DeadlineStatus.COMPLETED, createdAt: new Date().toISOString() },
        { id: '2', peca: 'Mandado de Segurança', responsavel: 'EDUARDO', empresa: 'SOUL', instituicao: 'Bom Jesus dos Perdões/SP', assunto: 'Rescisão contratual e violação ao devido processo legal', data: '2025-07-17', hora: '10:00', status: DeadlineStatus.PENDING, createdAt: new Date().toISOString() },
        { id: '3', peca: 'Exceção de Pré-Executividade', responsavel: 'DANILO', empresa: 'SOUL', instituicao: 'Dois Córregos/SP', assunto: 'Prazo exíguo para execução e ausência de mobilização', data: '2025-07-17', hora: '15:00', status: DeadlineStatus.PENDING, createdAt: new Date().toISOString() },
      ];
      setDeadlines(mock);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('juris_deadlines', JSON.stringify(deadlines));
  }, [deadlines]);

  const companies = useMemo(() => {
    const list = Array.from(new Set(deadlines.map(d => d.empresa)));
    return ['Todas', ...list];
  }, [deadlines]);

  const handleAddDeadline = (e: React.FormEvent) => {
    e.preventDefault();
    const deadline: Deadline = {
      ...(newDeadline as Deadline),
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString()
    };
    setDeadlines(prev => [...prev, deadline]);
    setIsModalOpen(false);
    // Reset form
    setNewDeadline({
      peca: PECA_OPTIONS[0],
      responsavel: RESPONSAVEL_OPTIONS[0],
      empresa: '',
      instituicao: '',
      assunto: '',
      data: new Date().toISOString().split('T')[0],
      hora: '09:00',
      status: DeadlineStatus.PENDING
    });
  };

  const toggleStatus = (id: string) => {
    setDeadlines(prev => prev.map(d => {
      if (d.id === id) {
        return { 
          ...d, 
          status: d.status === DeadlineStatus.COMPLETED ? DeadlineStatus.PENDING : DeadlineStatus.COMPLETED 
        };
      }
      return d;
    }));
  };

  const deleteDeadline = (id: string) => {
    if (confirm('Deseja realmente excluir este prazo?')) {
      setDeadlines(prev => prev.filter(d => d.id !== id));
    }
  };

  // --- Calculations for Reports ---
  const filteredDeadlines = useMemo(() => {
    return deadlines.filter(d => {
      const matchCompany = selectedCompany === 'Todas' || d.empresa === selectedCompany;
      const matchStart = !dateRange.start || d.data >= dateRange.start;
      const matchEnd = !dateRange.end || d.data <= dateRange.end;
      return matchCompany && matchStart && matchEnd;
    });
  }, [deadlines, selectedCompany, dateRange]);

  const stats = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return {
      total: filteredDeadlines.length,
      concluidos: filteredDeadlines.filter(d => d.status === DeadlineStatus.COMPLETED).length,
      pendentes: filteredDeadlines.filter(d => d.status === DeadlineStatus.PENDING && d.data >= today).length,
      atrasados: filteredDeadlines.filter(d => d.status === DeadlineStatus.PENDING && d.data < today).length,
    };
  }, [filteredDeadlines]);

  const chartData = [
    { name: 'Concluídos', value: stats.concluidos, color: COLORS.success },
    { name: 'Pendentes', value: stats.pendentes, color: COLORS.warning },
    { name: 'Atrasados', value: stats.atrasados, color: COLORS.danger },
  ];

  return (
    <div className="flex bg-slate-50 min-h-screen">
      <Sidebar currentView={view} setView={setView} />

      <main className="ml-64 flex-1 p-8">
        {/* Header */}
        <header className="flex justify-between items-center mb-8">
          <div>
            <h2 className="text-3xl font-bold text-slate-800">
              {view === 'dashboard' && 'Visão Geral'}
              {view === 'deadlines' && 'Controle de Prazos'}
              {view === 'reports' && 'Relatórios Gerenciais'}
            </h2>
            <p className="text-slate-500 mt-1">Bem-vindo ao JurisControl. Gerencie seus prazos com precisão.</p>
          </div>
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-xl font-semibold flex items-center gap-2 shadow-lg transition-all transform hover:scale-105 active:scale-95"
          >
            <Icons.Plus /> Novo Prazo
          </button>
        </header>

        {/* Dashboard View */}
        {view === 'dashboard' && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              {[
                { label: 'Total de Demandas', val: stats.total, color: 'text-slate-800', bg: 'bg-slate-100' },
                { label: 'Prazos Concluídos', val: stats.concluidos, color: 'text-emerald-600', bg: 'bg-emerald-50' },
                { label: 'Prazos Pendentes', val: stats.pendentes, color: 'text-amber-600', bg: 'bg-amber-50' },
                { label: 'Prazos Atrasados', val: stats.atrasados, color: 'text-red-600', bg: 'bg-red-50' },
              ].map((card, idx) => (
                <div key={idx} className={`${card.bg} p-6 rounded-2xl shadow-sm border border-slate-200/60`}>
                  <p className="text-sm font-medium text-slate-500 mb-2">{card.label}</p>
                  <p className={`text-4xl font-bold ${card.color}`}>{card.val}</p>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
                <h3 className="text-lg font-bold mb-6 flex items-center gap-2">
                  Status das Demandas
                </h3>
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie
                        data={chartData.filter(d => d.value > 0)}
                        cx="50%"
                        cy="50%"
                        innerRadius={60}
                        outerRadius={80}
                        paddingAngle={5}
                        dataKey="value"
                      >
                        {chartData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={entry.color} />
                        ))}
                      </Pie>
                      <Tooltip />
                      <Legend />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>

              <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
                <h3 className="text-lg font-bold mb-6">Próximos Vencimentos</h3>
                <div className="space-y-4">
                  {deadlines
                    .filter(d => d.status === DeadlineStatus.PENDING)
                    .sort((a, b) => new Date(a.data).getTime() - new Date(b.data).getTime())
                    .slice(0, 5)
                    .map(d => (
                      <div key={d.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-xl border border-slate-100 hover:border-blue-200 transition-colors">
                        <div>
                          <p className="font-semibold text-slate-800">{d.peca}</p>
                          <p className="text-sm text-slate-500">{d.empresa} • {d.instituicao}</p>
                        </div>
                        <div className="text-right">
                          <p className="font-bold text-blue-600">{new Date(d.data).toLocaleDateString('pt-BR')}</p>
                          <p className="text-xs text-slate-400">{d.hora}</p>
                        </div>
                      </div>
                    ))}
                  {deadlines.filter(d => d.status === DeadlineStatus.PENDING).length === 0 && (
                    <div className="text-center py-12 text-slate-400">
                      Nenhum prazo pendente.
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* List View */}
        {view === 'deadlines' && (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead>
                  <tr className="bg-slate-800 text-white uppercase text-xs font-semibold">
                    <th className="px-6 py-4">Peça</th>
                    <th className="px-6 py-4">Responsável</th>
                    <th className="px-6 py-4">Empresa</th>
                    <th className="px-6 py-4">Instituição</th>
                    <th className="px-6 py-4">Vencimento</th>
                    <th className="px-6 py-4">Status</th>
                    <th className="px-6 py-4 text-center">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {deadlines.map(d => (
                    <tr key={d.id} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-6 py-4">
                        <div className="font-medium text-slate-800">{d.peca}</div>
                        <div className="text-xs text-slate-400 truncate max-w-xs">{d.assunto}</div>
                      </td>
                      <td className="px-6 py-4 text-sm text-slate-600 font-medium">{d.responsavel}</td>
                      <td className="px-6 py-4 text-sm text-slate-600">{d.empresa}</td>
                      <td className="px-6 py-4 text-sm text-slate-500">{d.instituicao}</td>
                      <td className="px-6 py-4 text-sm font-semibold text-slate-700">
                        {new Date(d.data).toLocaleDateString('pt-BR')} <br/>
                        <span className="text-xs font-normal text-slate-400">{d.hora}</span>
                      </td>
                      <td className="px-6 py-4">
                        <span className={`px-3 py-1 rounded-full text-xs font-bold ${
                          d.status === DeadlineStatus.COMPLETED 
                            ? 'bg-emerald-100 text-emerald-700' 
                            : 'bg-amber-100 text-amber-700'
                        }`}>
                          {d.status}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <div className="flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button 
                            onClick={() => toggleStatus(d.id)}
                            className={`p-2 rounded-lg transition-colors ${d.status === DeadlineStatus.COMPLETED ? 'bg-slate-100 text-slate-400' : 'bg-emerald-50 text-emerald-600 hover:bg-emerald-100'}`}
                            title={d.status === DeadlineStatus.COMPLETED ? "Marcar como pendente" : "Concluir"}
                          >
                            <Icons.Check />
                          </button>
                          <button 
                            onClick={() => deleteDeadline(d.id)}
                            className="p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-100 transition-colors"
                            title="Excluir"
                          >
                            <Icons.Trash />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Reports View */}
        {view === 'reports' && (
          <div className="space-y-8">
            {/* Filters */}
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex flex-wrap gap-6 items-end">
              <div className="flex-1 min-w-[200px]">
                <label className="block text-sm font-semibold text-slate-600 mb-2">Empresa</label>
                <select 
                  className="w-full border border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-blue-500 outline-none"
                  value={selectedCompany}
                  onChange={(e) => setSelectedCompany(e.target.value)}
                >
                  {companies.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="flex-1 min-w-[200px]">
                <label className="block text-sm font-semibold text-slate-600 mb-2">Início</label>
                <input 
                  type="date"
                  className="w-full border border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-blue-500 outline-none"
                  value={dateRange.start}
                  onChange={(e) => setDateRange(prev => ({ ...prev, start: e.target.value }))}
                />
              </div>
              <div className="flex-1 min-w-[200px]">
                <label className="block text-sm font-semibold text-slate-600 mb-2">Fim</label>
                <input 
                  type="date"
                  className="w-full border border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-blue-500 outline-none"
                  value={dateRange.end}
                  onChange={(e) => setDateRange(prev => ({ ...prev, end: e.target.value }))}
                />
              </div>
              <button 
                onClick={() => { setSelectedCompany('Todas'); setDateRange({ start: '', end: '' }); }}
                className="px-6 py-3 text-slate-500 hover:text-slate-800 font-medium"
              >
                Limpar Filtros
              </button>
            </div>

            {/* Summary */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-1 bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
                <h3 className="text-lg font-bold mb-6">Métricas do Período</h3>
                <div className="space-y-6">
                  <div>
                    <div className="flex justify-between text-sm mb-2">
                      <span className="text-slate-500">Taxa de Conclusão</span>
                      <span className="font-bold">{stats.total > 0 ? Math.round((stats.concluidos / stats.total) * 100) : 0}%</span>
                    </div>
                    <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
                      <div 
                        className="bg-emerald-500 h-full transition-all duration-1000" 
                        style={{ width: `${stats.total > 0 ? (stats.concluidos / stats.total) * 100 : 0}%` }}
                      />
                    </div>
                  </div>

                  <div className="pt-4 border-t border-slate-50 space-y-4">
                    <div className="flex justify-between items-center">
                      <span className="text-slate-600">Total de Demandas</span>
                      <span className="text-xl font-bold">{stats.total}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-slate-600">Concluídas</span>
                      <span className="text-xl font-bold text-emerald-600">{stats.concluidos}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-slate-600">Pendentes</span>
                      <span className="text-xl font-bold text-amber-600">{stats.pendentes}</span>
                    </div>
                    <div className="flex justify-between items-center">
