                { label: 'Prazos Concluídos', val: stats.concluidos, color: 'text-emerald-600', bg: 'bg-emerald-50' },
                { label: 'Prazos Pendentes', val: stats.pendentes, color: 'text-amber-600', bg: 'bg-amber-50' },
