                <select 
                  className="w-full border border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-blue-500 outline-none"
                  value={selectedCompany}
                  onChange={(e) => setSelectedCompany(e.target.value)}
                >
                  {companies.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="flex-1 min-w-[200px]">
                <label className="block text-sm font-semibold text-slate-600 mb-2">Início</label>
                <input 
                  type="date"
                  className="w-full border border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-blue-500 outline-none"
                  value={dateRange.start}
                  onChange={(e) => setDateRange(prev => ({ ...prev, start: e.target.value }))}
                />
              </div>
              <div className="flex-1 min-w-[200px]">
                <label className="block text-sm font-semibold text-slate-600 mb-2">Fim</label>
                <input 
                  type="date"
                  className="w-full border border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-blue-500 outline-none"
                  value={dateRange.end}
                  onChange={(e) => setDateRange(prev => ({ ...prev, end: e.target.value }))}
                />
              </div>
              <button 
                onClick={() => { setSelectedCompany('Todas'); setDateRange({ start: '', end: '' }); }}
                className="px-6 py-3 text-slate-500 hover:text-slate-800 font-medium"
              >
                Limpar Filtros
              </button>
            </div>

            {/* Summary */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              <div className="lg:col-span-1 bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
                <h3 className="text-lg font-bold mb-6">Métricas do Período</h3>
                <div className="space-y-6">
                  <div>
                    <div className="flex justify-between text-sm mb-2">
                      <span className="text-slate-500">Taxa de Conclusão</span>
                      <span className="font-bold">{stats.total > 0 ? Math.round((stats.concluidos / stats.total) * 100) : 0}%</span>
                    </div>
                    <div className="w-full bg-slate-100 h-3 rounded-full overflow-hidden">
                      <div 
                        className="bg-emerald-500 h-full transition-all duration-1000" 
                        style={{ width: `${stats.total > 0 ? (stats.concluidos / stats.total) * 100 : 0}%` }}
                      />
                    </div>
                  </div>

                  <div className="pt-4 border-t border-slate-50 space-y-4">
                    <div className="flex justify-between items-center">
                      <span className="text-slate-600">Total de Demandas</span>
                      <span className="text-xl font-bold">{stats.total}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-slate-600">Concluídas</span>
                      <span className="text-xl font-bold text-emerald-600">{stats.concluidos}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-slate-600">Pendentes</span>
                      <span className="text-xl font-bold text-amber-600">{stats.pendentes}</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-slate-600">Atrasadas</span>
                      <span className="text-xl font-bold text-red-600">{stats.atrasados}</span>
                    </div>
                  </div>
                </div>
              </div>

              <div className="lg:col-span-2 bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
                <h3 className="text-lg font-bold mb-6">Distribuição de Status</h3>
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={chartData}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                      <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                      <Tooltip cursor={{fill: 'transparent'}} />
                      <Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={60}>
                        {chartData.map((entry, index) => (
                          <Cell key={`cell-${index}`} fill={entry.color} />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </div>
            </div>

            {/* List for Report */}
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
              <div className="p-6 border-b">
