                {RESPONSAVEL_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
              </select>
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-semibold text-slate-600 mb-2">Empresa</label>
