                value={newDeadline.instituicao}
                onChange={(e) => setNewDeadline(prev => ({ ...prev, instituicao: e.target.value }))}
                required
              />
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-semibold text-slate-600 mb-2">Data Vencimento</label>
              <input 
                type="date"
                className="w-full bg-white border border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-blue-500 outline-none shadow-sm"
                value={newDeadline.data}
                onChange={(e) => setNewDeadline(prev => ({ ...prev, data: e.target.value }))}
                required
              />
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-semibold text-slate-600 mb-2">Hora</label>
              <input 
                type="time"
                className="w-full bg-white border border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-blue-500 outline-none shadow-sm"
                value={newDeadline.hora}
                onChange={(e) => setNewDeadline(prev => ({ ...prev, hora: e.target.value }))}
                required
              />
            </div>
            <div className="col-span-2">
              <label className="block text-sm font-semibold text-slate-600 mb-2">Assunto / Descrição</label>
              <textarea 
                className="w-full bg-white border border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-blue-500 outline-none shadow-sm min-h-[100px]"
                placeholder="Detalhes do caso..."
                value={newDeadline.assunto}
                onChange={(e) => setNewDeadline(prev => ({ ...prev, assunto: e.target.value }))}
                required
              />
            </div>
            <div className="col-span-2 flex justify-end gap-4 mt-4">
              <button 
                type="button" 
                onClick={() => setIsModalOpen(false)}
                className="px-6 py-3 text-slate-500 font-semibold hover:bg-slate-100 rounded-xl transition-all"
              >
                Cancelar
              </button>
              <button 
                type="submit"
                className="px-8 py-3 bg-blue-600 text-white font-bold rounded-xl shadow-lg hover:bg-blue-700 transition-all"
