                    <input 
                      type="range" 
                      min="3" 
                      max="15" 
                      step="1"
                      className="flex-1 h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
                      value={settings.greenAlertDays}
                      onChange={(e) => setSettings(prev => ({ ...prev, greenAlertDays: parseInt(e.target.value) }))}
                    />
                    <span className="bg-blue-50 text-blue-600 font-bold px-3 py-1 rounded-lg border border-blue-100">
                      {settings.greenAlertDays} dias
                    </span>
                  </div>
                </div>

                <div className="pt-6 border-t border-slate-100 flex items-center justify-between">
