// --- Main App ---

export default function App() {
  const [view, setView] = useState('dashboard');
  const [deadlines, setDeadlines] = useState<Deadline[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isNotifOpen, setIsNotifOpen] = useState(false);
  const [insights, setInsights] = useState<string>('Analisando prazos com Inteligência Artificial...');
  const [isSyncing, setIsSyncing] = useState(false);

  // Settings State
  const [settings, setSettings] = useState<NotificationSettings>({
    greenAlertDays: 5,
    enableBrowserNotifications: true,
    quietMode: false,
    spreadsheetId: ''
  });

  // Form State
  const [newDeadline, setNewDeadline] = useState<Partial<Deadline>>({
    peca: PECA_OPTIONS[0],
    responsavel: RESPONSAVEL_OPTIONS[0],
    empresa: '',
    instituicao: '',
    assunto: '',
    data: new Date().toISOString().split('T')[0],
    hora: '09:00',
    status: DeadlineStatus.PENDING
  });

  // Report Filters
  const [selectedCompany, setSelectedCompany] = useState('Todas');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  // Load Initial Data
  useEffect(() => {
    const saved = localStorage.getItem('juris_deadlines');
    const savedSettings = localStorage.getItem('juris_settings');
    if (saved) setDeadlines(JSON.parse(saved));
    if (savedSettings) setSettings(JSON.parse(savedSettings));

    if (!saved) {
      const mock: Deadline[] = [
        { id: '1', peca: 'Parecer Jurídico', responsavel: 'EDUARDO', empresa: 'SOUL', instituicao: 'Bom Jesus dos Perdões/SP', assunto: 'Rescisão contratual e violação ao devido processo legal', data: new Date().toISOString().split('T')[0], hora: '14:00', status: DeadlineStatus.COMPLETED, createdAt: new Date().toISOString() },
        { id: '2', peca: 'Mandado de Segurança', responsavel: 'EDUARDO', empresa: 'SOUL', instituicao: 'Bom Jesus dos Perdões/SP', assunto: 'Rescisão contratual e violação ao devido processo legal', data: new Date(Date.now() + 86400000).toISOString().split('T')[0], hora: '10:00', status: DeadlineStatus.PENDING, createdAt: new Date().toISOString() },
        { id: '3', peca: 'Exceção de Pré-Executividade', responsavel: 'DANILO', empresa: 'SOUL', instituicao: 'Dois Córregos/SP', assunto: 'Prazo exíguo para execução e ausência de mobilização', data: new Date(Date.now() + 86400000 * 3).toISOString().split('T')[0], hora: '15:00', status: DeadlineStatus.PENDING, createdAt: new Date().toISOString() },
      ];
      setDeadlines(mock);
    }
  }, []);

  // Parsing helper for Google's specific date format like "Date(2023,9,15)"
  const parseGoogleDate = (dateStr: string) => {
    if (!dateStr) return new Date().toISOString().split('T')[0];
    const match = dateStr.match(/Date\((\d+),(\d+),(\d+)\)/);
    if (match) {
      const year = match[1];
      const month = (parseInt(match[2]) + 1).toString().padStart(2, '0');
      const day = match[3].padStart(2, '0');
      return `${year}-${month}-${day}`;
    }
    const date = new Date(dateStr);
    return isNaN(date.getTime()) ? new Date().toISOString().split('T')[0] : date.toISOString().split('T')[0];
  };

  // Sync with Google Sheets
  const syncWithGoogleSheets = async () => {
    if (!settings.spreadsheetId) {
      alert("Por favor, informe o ID da planilha nas configurações.");
      setView('settings');
      return;
    }

    setIsSyncing(true);
    try {
      const url = `https://docs.google.com/spreadsheets/d/${settings.spreadsheetId}/gviz/tq?tqx=out:json`;
      const response = await fetch(url);
      const text = await response.text();

      const start = text.indexOf('{');
      const end = text.lastIndexOf('}');
      if (start === -1 || end === -1) throw new Error("Formato de resposta inválido");

      const jsonStr = text.substring(start, end + 1);
      const json = JSON.parse(jsonStr);
      const rows = json.table.rows;

      const newDeadlines: Deadline[] = rows
        .filter((row: any) => row.c && row.c[0] && row.c[0].v !== 'PEÇA' && row.c[0].v !== 'Peça') 
        .map((row: any, index: number) => {
          const c = row.c;
          return {
            id: `sheet-${index}-${Date.now()}`,
            peca: c[0]?.v || '',
            responsavel: c[1]?.v || '',
            empresa: c[2]?.v?.toString().toUpperCase() || '',
            instituicao: c[3]?.v || '',
            assunto: c[4]?.v || '',
            data: parseGoogleDate(c[5]?.v),
            hora: c[6]?.v || '09:00',
            status: (c[7]?.v?.toString().toUpperCase() === 'CONCLUÍDO' || c[7]?.v?.toString().toUpperCase() === 'CONCLUIDO') 
              ? DeadlineStatus.COMPLETED 
              : DeadlineStatus.PENDING,
            createdAt: new Date().toISOString()
          };
        });

      if (newDeadlines.length > 0) {
        if (confirm(`Encontrados ${newDeadlines.length} registros. Deseja substituir sua base atual?`)) {
          setDeadlines(newDeadlines);
          setSettings(prev => ({ ...prev, lastSync: new Date().toLocaleString('pt-BR') }));
          alert("Sincronização concluída com sucesso!");
        }
      } else {
        alert("Nenhum dado válido encontrado. Verifique se a planilha segue a ordem correta das colunas.");
      }
    } catch (error) {
      console.error("Sync Error:", error);
      alert("Erro ao sincronizar. Verifique o ID e as permissões da planilha.");
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    if (deadlines.length > 0) {
      const fetchInsights = async () => {
        const text = await getLegalInsights(deadlines);
        setInsights(text || "Sem insights no momento.");
      };
      fetchInsights();
    }
  }, [deadlines]);

  useEffect(() => {
    localStorage.setItem('juris_deadlines', JSON.stringify(deadlines));
  }, [deadlines]);

  useEffect(() => {
    localStorage.setItem('juris_settings', JSON.stringify(settings));
  }, [settings]);

  const alertData = useMemo(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    const tomorrowStr = new Date(Date.now() + 86400000).toISOString().split('T')[0];
    const thresholdDate = new Date(Date.now() + 86400000 * settings.greenAlertDays);

    const pending = deadlines.filter(d => d.status === DeadlineStatus.PENDING);

    const red = pending.filter(d => d.data === todayStr);
    const yellow = pending.filter(d => d.data === tomorrowStr);
    const green = pending.filter(d => {
      const dDate = new Date(d.data);
      return d.data > tomorrowStr && dDate <= thresholdDate;
    });

    return { red, yellow, green };
  }, [deadlines, settings.greenAlertDays]);

  const totalUrgent = alertData.red.length + alertData.yellow.length + alertData.green.length;

  const companies = useMemo(() => {
    const list = Array.from(new Set(deadlines.map(d => d.empresa)));
    return ['Todas', ...list];
  }, [deadlines]);

  const handleAddDeadline = (e: React.FormEvent) => {
    e.preventDefault();
    const deadline: Deadline = {
      ...(newDeadline as Deadline),
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString()
    };
    setDeadlines(prev => [...prev, deadline]);
    setIsModalOpen(false);
    setNewDeadline({
      peca: PECA_OPTIONS[0],
      responsavel: RESPONSAVEL_OPTIONS[0],
      empresa: '',
      instituicao: '',
      assunto: '',
      data: new Date().toISOString().split('T')[0],
      hora: '09:00',
      status: DeadlineStatus.PENDING
    });
  };

  const toggleStatus = (id: string) => {
    setDeadlines(prev => prev.map(d => {
      if (d.id === id) {
        return { 
          ...d, 
          status: d.status === DeadlineStatus.COMPLETED ? DeadlineStatus.PENDING : DeadlineStatus.COMPLETED 
        };
      }
      return d;
    }));
  };

  const deleteDeadline = (id: string) => {
    if (confirm('Deseja realmente excluir este prazo?')) {
      setDeadlines(prev => prev.filter(d => d.id !== id));
    }
  };

  const filteredDeadlines = useMemo(() => {
    return deadlines.filter(d => {
      const matchCompany = selectedCompany === 'Todas' || d.empresa === selectedCompany;
      const matchStart = !dateRange.start || d.data >= dateRange.start;
      const matchEnd = !dateRange.end || d.data <= dateRange.end;
      return matchCompany && matchStart && matchEnd;
    });
  }, [deadlines, selectedCompany, dateRange]);

  const stats = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return {
      total: filteredDeadlines.length,
      concluidos: filteredDeadlines.filter(d => d.status === DeadlineStatus.COMPLETED).length,
      pendentes: filteredDeadlines.filter(d => d.status === DeadlineStatus.PENDING && d.data >= today).length,
      atrasados: filteredDeadlines.filter(d => d.status === DeadlineStatus.PENDING && d.data < today).length,
    };
  }, [filteredDeadlines]);

  const chartData = [
    { name: 'Concluídos', value: stats.concluidos, color: COLORS.success },
    { name: 'Pendentes', value: stats.pendentes, color: COLORS.warning },
    { name: 'Atrasados', value: stats.atrasados, color: COLORS.danger },
  ];

  return (
    <div className="flex bg-slate-50 min-h-screen">
      <Sidebar currentView={view} setView={setView} />

      {/* Notification Drawer */}
      {isNotifOpen && (
        <div className="fixed inset-0 z-50 overflow-hidden">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsNotifOpen(false)} />
          <div className="absolute right-0 top-0 h-full w-96 bg-white shadow-2xl animate-in slide-in-from-right duration-300 flex flex-col">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50">
              <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <Icons.Bell /> Alertas do Sistema
              </h2>
              <button onClick={() => setIsNotifOpen(false)} className="p-2 hover:bg-slate-200 rounded-full">&times;</button>
            </div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6">
              {alertData.red.length > 0 && (
                <section>
                  <h3 className="text-xs font-black text-red-600 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <span className="w-2 h-2 bg-red-600 rounded-full animate-pulse" /> Vencem Hoje
                  </h3>
                  <div className="space-y-3">
                    {alertData.red.map(d => (
                      <div key={d.id} className="p-4 bg-red-50 border border-red-100 rounded-xl">
                        <p className="font-bold text-red-900">{d.peca}</p>
                        <p className="text-xs text-red-700">{d.empresa} • {d.instituicao}</p>
                        <p className="text-[10px] mt-1 font-bold text-red-600">{d.hora}</p>
                      </div>
                    ))}
                  </div>
                </section>
              )}

              {alertData.yellow.length > 0 && (
                <section>
                  <h3 className="text-xs font-black text-amber-600 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <span className="w-2 h-2 bg-amber-600 rounded-full" /> Vencem Amanhã
                  </h3>
                  <div className="space-y-3">
                    {alertData.yellow.map(d => (
                      <div key={d.id} className="p-4 bg-amber-50 border border-amber-100 rounded-xl">
                        <p className="font-bold text-amber-900">{d.peca}</p>
                        <p className="text-xs text-amber-700">{d.empresa} • {d.instituicao}</p>
                      </div>
                    ))}
                  </div>
                </section>
              )}

              {alertData.green.length > 0 && (
                <section>
                  <h3 className="text-xs font-black text-emerald-600 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <span className="w-2 h-2 bg-emerald-600 rounded-full" /> Próximos {settings.greenAlertDays} dias
                  </h3>
                  <div className="space-y-3">
                    {alertData.green.map(d => (
                      <div key={d.id} className="p-4 bg-emerald-50 border border-emerald-100 rounded-xl">
                        <p className="font-bold text-emerald-900">{d.peca}</p>
                        <p className="text-xs text-emerald-700">{d.empresa} • {new Date(d.data).toLocaleDateString('pt-BR')}</p>
                      </div>
                    ))}
                  </div>
                </section>
              )}

              {totalUrgent === 0 && (
                <div className="text-center py-20">
                  <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Icons.Check />
                  </div>
                  <p className="text-slate-500 font-medium">Nenhum alerta pendente.</p>
                  <p className="text-xs text-slate-400 mt-1">Tudo em dia por aqui!</p>
                </div>
              )}
            </div>
            <div className="p-6 border-t bg-slate-50 text-center">
              <button 
                onClick={() => { setView('settings'); setIsNotifOpen(false); }}
                className="text-sm font-bold text-blue-600 hover:underline"
              >
                Configurar Alertas
              </button>
            </div>
          </div>
        </div>
      )}

