              </div>

              <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
                <h3 className="text-lg font-bold mb-6">Próximos Vencimentos</h3>
                <div className="space-y-4">
                  {deadlines
                    .filter(d => d.status === DeadlineStatus.PENDING)
                    .sort((a, b) => new Date(a.data).getTime() - new Date(b.data).getTime())
                    .slice(0, 5)
                    .map(d => (
                      <div key={d.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-xl border border-slate-100 hover:border-blue-200 transition-colors">
                        <div className="flex items-center gap-3">
                          <div className={`w-2 h-2 rounded-full ${
                            new Date(d.data).toISOString().split('T')[0] === new Date().toISOString().split('T')[0] ? 'bg-red-600' : 
                            new Date(d.data).toISOString().split('T')[0] === new Date(Date.now() + 86400000).toISOString().split('T')[0] ? 'bg-amber-600' : 'bg-emerald-600'
                          }`} />
                          <div>
                            <p className="font-semibold text-slate-800">{d.peca}</p>
                            <p className="text-sm text-slate-500">{d.empresa}</p>
                          </div>
                        </div>
                        <div className="text-right">
                          <p className="font-bold text-blue-600">{new Date(d.data).toLocaleDateString('pt-BR')}</p>
                          <p className="text-xs text-slate-400">{d.hora}</p>
                        </div>
                      </div>
                    ))}
                  {deadlines.filter(d => d.status === DeadlineStatus.PENDING).length === 0 && (
                    <div className="text-center py-12 text-slate-400">
                      Nenhum prazo pendente.
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* List View */}
        {view === 'deadlines' && (
          <div className="space-y-6">
             {settings.spreadsheetId && (
              <div className="bg-blue-50 border border-blue-100 p-4 rounded-xl flex items-center justify-between">
                <div className="flex items-center gap-3 text-blue-800 text-sm">
                  <Icons.Sync />
                  <span>Última sincronização com a planilha: <strong>{settings.lastSync || 'Nunca'}</strong></span>
                </div>
                <button onClick={syncWithGoogleSheets} className="text-blue-600 font-bold text-sm hover:underline">Sincronizar agora</button>
              </div>
            )}

            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="bg-slate-800 text-white uppercase text-xs font-semibold">
                      <th className="px-6 py-4">Peça</th>
                      <th className="px-6 py-4">Responsável</th>
                      <th className="px-6 py-4">Empresa</th>
                      <th className="px-6 py-4">Instituição</th>
                      <th className="px-6 py-4">Vencimento</th>
                      <th className="px-6 py-4">Status</th>
                      <th className="px-6 py-4 text-center">Ações</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {deadlines.map(d => {
                      const isToday = d.data === new Date().toISOString().split('T')[0];
                      return (
                        <tr key={d.id} className={`hover:bg-slate-50 transition-colors group ${isToday && d.status === DeadlineStatus.PENDING ? 'bg-red-50/50' : ''}`}>
                          <td className="px-6 py-4">
                            <div className="font-medium text-slate-800">{d.peca}</div>
                            <div className="text-xs text-slate-400 truncate max-w-xs">{d.assunto}</div>
                          </td>
                          <td className="px-6 py-4 text-sm text-slate-600 font-medium">{d.responsavel}</td>
                          <td className="px-6 py-4 text-sm text-slate-600">{d.empresa}</td>
                          <td className="px-6 py-4 text-sm text-slate-500">{d.instituicao}</td>
                          <td className="px-6 py-4 text-sm font-semibold text-slate-700">
                            <span className={isToday && d.status === DeadlineStatus.PENDING ? 'text-red-600' : ''}>
                              {new Date(d.data).toLocaleDateString('pt-BR')}
                            </span>
                            <br/>
                            <span className="text-xs font-normal text-slate-400">{d.hora}</span>
                          </td>
                          <td className="px-6 py-4">
                            <span className={`px-3 py-1 rounded-full text-xs font-bold ${
                              d.status === DeadlineStatus.COMPLETED 
                                ? 'bg-emerald-100 text-emerald-700' 
                                : 'bg-amber-100 text-amber-700'
                            }`}>
                              {d.status}
                            </span>
                          </td>
                          <td className="px-6 py-4 text-right">
                            <div className="flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                              <button 
                                onClick={() => toggleStatus(d.id)}
                                className={`p-2 rounded-lg transition-colors ${d.status === DeadlineStatus.COMPLETED ? 'bg-slate-100 text-slate-400' : 'bg-emerald-50 text-emerald-600 hover:bg-emerald-100'}`}
                                title={d.status === DeadlineStatus.COMPLETED ? "Marcar como pendente" : "Concluir"}
                              >
                                <Icons.Check />
                              </button>
                              <button 
                                onClick={() => deleteDeadline(d.id)}
                                className="p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-100 transition-colors"
                                title="Excluir"
                              >
                                <Icons.Trash />
                              </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {/* Reports View */}
        {view === 'reports' && (
          <div className="space-y-8">
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 items-end">
                <div className="space-y-2">
                  <label className="block text-sm font-semibold text-slate-600">Empresa</label>
