        className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${currentView === 'reports' ? 'bg-blue-600 shadow-lg' : 'hover:bg-slate-800'}`}
      >
        <Icons.Report /> Relatórios
      </button>
      <div className="pt-4 pb-2 px-4">
        <p className="text-[10px] uppercase font-bold text-slate-500 tracking-widest">Ajustes</p>
      </div>
      <button 
        onClick={() => setView('settings')}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${currentView === 'settings' ? 'bg-blue-600 shadow-lg' : 'hover:bg-slate-800'}`}
      >
        <Icons.Settings /> Configurações
      </button>
    </nav>
    <div className="p-4 text-xs text-slate-500 text-center border-t border-slate-800">
      JurisControl v1.0.0
    </div>
  </aside>
);

const Modal = ({ isOpen, onClose, title, children }: { isOpen: boolean, onClose: () => void, title: string, children?: React.ReactNode }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl w-full max-w-2xl shadow-2xl animate-in fade-in zoom-in duration-200 overflow-hidden">
        <div className="p-6 border-b flex justify-between items-center bg-slate-50">
          <h2 className="text-xl font-semibold text-slate-800">{title}</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-full transition-colors">&times;</button>
        </div>
        <div className="p-6 max-h-[85vh] overflow-y-auto">
          {children}
        </div>
      </div>
    </div>
  );
};

// --- Main App ---

export default function App() {
  const [view, setView] = useState('dashboard');
  const [deadlines, setDeadlines] = useState<Deadline[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isNotifOpen, setIsNotifOpen] = useState(false);
  const [insights, setInsights] = useState<string>('Analisando prazos com Inteligência Artificial...');
  const [isSyncing, setIsSyncing] = useState(false);

  // AI Form State
  const [aiInputText, setAiInputText] = useState('');
  const [isAiProcessing, setIsAiProcessing] = useState(false);
  const [showAiInput, setShowAiInput] = useState(false);

  // Settings State
  const [settings, setSettings] = useState<NotificationSettings>({
    greenAlertDays: 5,
    enableBrowserNotifications: true,
    quietMode: false,
    spreadsheetId: ''
  });

  // Form State
  const [newDeadline, setNewDeadline] = useState<Partial<Deadline>>({
    peca: PECA_OPTIONS[0],
    responsavel: RESPONSAVEL_OPTIONS[0],
    empresa: '',
    instituicao: '',
    assunto: '',
    data: new Date().toISOString().split('T')[0],
    hora: '09:00',
    status: DeadlineStatus.PENDING
  });

  // Report Filters
  const [selectedCompany, setSelectedCompany] = useState('Todas');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  // Load Initial Data
  useEffect(() => {
    const saved = localStorage.getItem('juris_deadlines');
    const savedSettings = localStorage.getItem('juris_settings');
    if (saved) setDeadlines(JSON.parse(saved));
    if (savedSettings) setSettings(JSON.parse(savedSettings));

    if (!saved) {
      const mock: Deadline[] = [
        { id: '1', peca: 'Parecer Jurídico', responsavel: 'EDUARDO', empresa: 'SOUL', instituicao: 'Bom Jesus dos Perdões/SP', assunto: 'Rescisão contratual e violação ao devido processo legal', data: new Date().toISOString().split('T')[0], hora: '14:00', status: DeadlineStatus.COMPLETED, createdAt: new Date().toISOString() },
        { id: '2', peca: 'Mandado de Segurança', responsavel: 'EDUARDO', empresa: 'SOUL', instituicao: 'Bom Jesus dos Perdões/SP', assunto: 'Rescisão contratual e violação ao devido processo legal', data: new Date(Date.now() + 86400000).toISOString().split('T')[0], hora: '10:00', status: DeadlineStatus.PENDING, createdAt: new Date().toISOString() },
        { id: '3', peca: 'Exceção de Pré-Executividade', responsavel: 'DANILO', empresa: 'SOUL', instituicao: 'Dois Córregos/SP', assunto: 'Prazo exíguo para execução e ausência de mobilização', data: new Date(Date.now() + 86400000 * 3).toISOString().split('T')[0], hora: '15:00', status: DeadlineStatus.PENDING, createdAt: new Date().toISOString() },
      ];
      setDeadlines(mock);
    }
  }, []);

  // AI Extraction Logic
  const handleAiExtract = async () => {
    if (!aiInputText.trim()) return;
    setIsAiProcessing(true);
    const extractedData = await extractDeadlineFromText(aiInputText);
    if (extractedData) {
      setNewDeadline(prev => ({
        ...prev,
        ...extractedData,
        // Garante que a peça extraída esteja entre as opções ou mantém a atual
        peca: PECA_OPTIONS.includes(extractedData.peca) ? extractedData.peca : prev.peca
      }));
      setShowAiInput(false);
      setAiInputText('');
    } else {
      alert("Não foi possível extrair os dados. Tente um texto mais claro.");
    }
    setIsAiProcessing(false);
  };

  // Parsing helper for Google's specific date format
  const parseGoogleDate = (dateStr: string) => {
    if (!dateStr) return new Date().toISOString().split('T')[0];
    const match = dateStr.match(/Date\((\d+),(\d+),(\d+)\)/);
    if (match) {
      const year = match[1];
      const month = (parseInt(match[2]) + 1).toString().padStart(2, '0');
      const day = match[3].padStart(2, '0');
      return `${year}-${month}-${day}`;
    }
    const date = new Date(dateStr);
    return isNaN(date.getTime()) ? new Date().toISOString().split('T')[0] : date.toISOString().split('T')[0];
  };

  // Sync with Google Sheets
  const syncWithGoogleSheets = async () => {
    if (!settings.spreadsheetId) {
      alert("Por favor, informe o ID da planilha nas configurações.");
      setView('settings');
      return;
    }

    setIsSyncing(true);
    try {
      const url = `https://docs.google.com/spreadsheets/d/${settings.spreadsheetId}/gviz/tq?tqx=out:json`;
      const response = await fetch(url);
      const text = await response.text();

      const start = text.indexOf('{');
      const end = text.lastIndexOf('}');
      if (start === -1 || end === -1) throw new Error("Formato de resposta inválido");

      const jsonStr = text.substring(start, end + 1);
      const json = JSON.parse(jsonStr);
      const rows = json.table.rows;

      const newDeadlines: Deadline[] = rows
        .filter((row: any) => row.c && row.c[0] && row.c[0].v !== 'PEÇA' && row.c[0].v !== 'Peça') 
        .map((row: any, index: number) => {
          const c = row.c;
          return {
            id: `sheet-${index}-${Date.now()}`,
            peca: c[0]?.v || '',
            responsavel: c[1]?.v || '',
            empresa: c[2]?.v?.toString().toUpperCase() || '',
            instituicao: c[3]?.v || '',
            assunto: c[4]?.v || '',
            data: parseGoogleDate(c[5]?.v),
            hora: c[6]?.v || '09:00',
            status: (c[7]?.v?.toString().toUpperCase() === 'CONCLUÍDO' || c[7]?.v?.toString().toUpperCase() === 'CONCLUIDO') 
              ? DeadlineStatus.COMPLETED 
              : DeadlineStatus.PENDING,
            createdAt: new Date().toISOString()
          };
        });

      if (newDeadlines.length > 0) {
        if (confirm(`Encontrados ${newDeadlines.length} registros. Deseja substituir sua base atual?`)) {
          setDeadlines(newDeadlines);
          setSettings(prev => ({ ...prev, lastSync: new Date().toLocaleString('pt-BR') }));
          alert("Sincronização concluída com sucesso!");
        }
      } else {
        alert("Nenhum dado válido encontrado.");
      }
    } catch (error) {
      console.error("Sync Error:", error);
      alert("Erro ao sincronizar. Verifique o ID e as permissões da planilha.");
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    if (deadlines.length > 0) {
      const fetchInsights = async () => {
        const text = await getLegalInsights(deadlines);
        setInsights(text || "Sem insights no momento.");
      };
      fetchInsights();
    }
  }, [deadlines]);

  useEffect(() => {
    localStorage.setItem('juris_deadlines', JSON.stringify(deadlines));
  }, [deadlines]);

  useEffect(() => {
    localStorage.setItem('juris_settings', JSON.stringify(settings));
  }, [settings]);

  const alertData = useMemo(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    const tomorrowStr = new Date(Date.now() + 86400000).toISOString().split('T')[0];
    const thresholdDate = new Date(Date.now() + 86400000 * settings.greenAlertDays);

    const pending = deadlines.filter(d => d.status === DeadlineStatus.PENDING);

    const red = pending.filter(d => d.data === todayStr);
    const yellow = pending.filter(d => d.data === tomorrowStr);
    const green = pending.filter(d => {
      const dDate = new Date(d.data);
      return d.data > tomorrowStr && dDate <= thresholdDate;
    });

    return { red, yellow, green };
  }, [deadlines, settings.greenAlertDays]);

  const totalUrgent = alertData.red.length + alertData.yellow.length + alertData.green.length;

  const companies = useMemo(() => {
    const list = Array.from(new Set(deadlines.map(d => d.empresa)));
    return ['Todas', ...list];
  }, [deadlines]);

  const handleAddDeadline = (e: React.FormEvent) => {
    e.preventDefault();
    const deadline: Deadline = {
      ...(newDeadline as Deadline),
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString()
    };
    setDeadlines(prev => [...prev, deadline]);
    setIsModalOpen(false);
    setNewDeadline({
      peca: PECA_OPTIONS[0],
      responsavel: RESPONSAVEL_OPTIONS[0],
      empresa: '',
      instituicao: '',
      assunto: '',
      data: new Date().toISOString().split('T')[0],
      hora: '09:00',
      status: DeadlineStatus.PENDING
    });
  };

  const toggleStatus = (id: string) => {
    setDeadlines(prev => prev.map(d => {
      if (d.id === id) {
        return { 
          ...d, 
          status: d.status === DeadlineStatus.COMPLETED ? DeadlineStatus.PENDING : DeadlineStatus.COMPLETED 
        };
      }
      return d;
    }));
  };

  const deleteDeadline = (id: string) => {
    if (confirm('Deseja realmente excluir este prazo?')) {
      setDeadlines(prev => prev.filter(d => d.id !== id));
    }
  };

  const filteredDeadlines = useMemo(() => {
    return deadlines.filter(d => {
      const matchCompany = selectedCompany === 'Todas' || d.empresa === selectedCompany;
      const matchStart = !dateRange.start || d.data >= dateRange.start;
      const matchEnd = !dateRange.end || d.data <= dateRange.end;
      return matchCompany && matchStart && matchEnd;
    });
  }, [deadlines, selectedCompany, dateRange]);

  const stats = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return {
      total: filteredDeadlines.length,
      concluidos: filteredDeadlines.filter(d => d.status === DeadlineStatus.COMPLETED).length,
      pendentes: filteredDeadlines.filter(d => d.status === DeadlineStatus.PENDING && d.data >= today).length,
      atrasados: filteredDeadlines.filter(d => d.status === DeadlineStatus.PENDING && d.data < today).length,
    };
  }, [filteredDeadlines]);

  const chartData = [
    { name: 'Concluídos', value: stats.concluidos, color: COLORS.success },
    { name: 'Pendentes', value: stats.pendentes, color: COLORS.warning },
    { name: 'Atrasados', value: stats.atrasados, color: COLORS.danger },
  ];

  return (
    <div className="flex bg-slate-50 min-h-screen">
      <Sidebar currentView={view} setView={setView} />

      {/* Notification Drawer */}
      {isNotifOpen && (
        <div className="fixed inset-0 z-50 overflow-hidden">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsNotifOpen(false)} />
          <div className="absolute right-0 top-0 h-full w-96 bg-white shadow-2xl animate-in slide-in-from-right duration-300 flex flex-col">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50">
              <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <Icons.Bell /> Alertas do Sistema
              </h2>
              <button onClick={() => setIsNotifOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-colors">&times;</button>
            </div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6">
              {alertData.red.length > 0 && (
                <section>
                  <h3 className="text-xs font-black text-red-600 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <span className="w-2 h-2 bg-red-600 rounded-full animate-pulse" /> Vencem Hoje
                  </h3>
                  <div className="space-y-3">
                    {alertData.red.map(d => (
                      <div key={d.id} className="p-4 bg-red-50 border border-red-100 rounded-xl">
                        <p className="font-bold text-red-900">{d.peca}</p>
                        <p className="text-xs text-red-700">{d.empresa} • {d.instituicao}</p>
                        <p className="text-[10px] mt-1 font-bold text-red-600">{d.hora}</p>
                      </div>
                    ))}
                  </div>
                </section>
              )}

              {alertData.yellow.length > 0 && (
                <section>
                  <h3 className="text-xs font-black text-amber-600 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <span className="w-2 h-2 bg-amber-600 rounded-full" /> Vencem Amanhã
                  </h3>
                  <div className="space-y-3">
                    {alertData.yellow.map(d => (
                      <div key={d.id} className="p-4 bg-amber-50 border border-amber-100 rounded-xl">
                        <p className="font-bold text-amber-900">{d.peca}</p>
                        <p className="text-xs text-amber-700">{d.empresa} • {d.instituicao}</p>
                      </div>
                    ))}
                  </div>
                </section>
              )}

              {alertData.green.length > 0 && (
                <section>
                  <h3 className="text-xs font-black text-emerald-600 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <span className="w-2 h-2 bg-emerald-600 rounded-full" /> Próximos {settings.greenAlertDays} dias
                  </h3>
                  <div className="space-y-3">
                    {alertData.green.map(d => (
                      <div key={d.id} className="p-4 bg-emerald-50 border border-emerald-100 rounded-xl">
                        <p className="font-bold text-emerald-900">{d.peca}</p>
                        <p className="text-xs text-emerald-700">{d.empresa} • {new Date(d.data).toLocaleDateString('pt-BR')}</p>
                      </div>
                    ))}
                  </div>
                </section>
              )}

              {totalUrgent === 0 && (
                <div className="text-center py-20">
                  <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Icons.Check />
                  </div>
                  <p className="text-slate-500 font-medium">Nenhum alerta pendente.</p>
                  <p className="text-xs text-slate-400 mt-1">Tudo em dia por aqui!</p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      <main className="ml-64 flex-1 p-8">
        <div className="flex justify-between items-start mb-8">
          <div>
            <h2 className="text-3xl font-bold text-slate-800">
              {view === 'dashboard' && 'Visão Geral'}
              {view === 'deadlines' && 'Controle de Prazos'}
              {view === 'reports' && 'Relatórios'}
              {view === 'settings' && 'Configurações'}
            </h2>
            <p className="text-slate-500 mt-1">JurisControl v1.0 • Gestão Estratégica</p>
          </div>
          <div className="flex items-center gap-4">
            {(view === 'deadlines' || view === 'dashboard') && (
              <button 
                onClick={syncWithGoogleSheets}
                disabled={isSyncing}
                className={`p-3 bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition-all shadow-sm flex items-center gap-2 font-semibold text-sm ${isSyncing ? 'opacity-50 cursor-not-allowed' : ''}`}
              >
                <span className={isSyncing ? 'animate-spin' : ''}><Icons.Sync /></span>
                {isSyncing ? 'Sincronizando...' : 'Sincronizar Planilha'}
              </button>
            )}
            <button 
              onClick={() => setIsNotifOpen(true)}
              className="relative p-3 bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition-all shadow-sm"
            >
              <Icons.Bell />
              {totalUrgent > 0 && (
                <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-600 text-white text-[10px] font-bold flex items-center justify-center rounded-full animate-bounce shadow-md">
                  {totalUrgent}
                </span>
              )}
            </button>
            <button 
              onClick={() => { setShowAiInput(false); setIsModalOpen(true); }}
              className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-xl font-semibold flex items-center gap-2 shadow-lg transition-all transform hover:scale-105 active:scale-95"
            >
              <Icons.Plus /> Novo Prazo
            </button>
          </div>
        </div>

        {/* Views */}
        {view === 'dashboard' && (
          <div className="space-y-8">
            {/* Insights IA */}
            <div className="bg-white p-6 rounded-2xl border border-blue-100 shadow-sm bg-gradient-to-r from-blue-50/50 to-indigo-50/50">
              <h3 className="text-sm font-bold text-blue-800 flex items-center gap-2 mb-2">
                <Icons.Sparkles /> Panorama Estratégico IA
              </h3>
              <p className="text-slate-700 leading-relaxed italic text-sm">"{insights}"</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              {[
                { label: 'Total', val: stats.total, color: 'text-slate-800', bg: 'bg-slate-100' },
                { label: 'Concluídos', val: stats.concluidos, color: 'text-emerald-600', bg: 'bg-emerald-50' },
                { label: 'Pendentes', val: stats.pendentes, color: 'text-amber-600', bg: 'bg-amber-50' },
                { label: 'Atrasados', val: stats.atrasados, color: 'text-red-600', bg: 'bg-red-50' },
              ].map((card, idx) => (
                <div key={idx} className={`${card.bg} p-6 rounded-2xl shadow-sm border border-slate-200/60`}>
                  <p className="text-sm font-medium text-slate-500 mb-2">{card.label}</p>
                  <p className={`text-4xl font-bold ${card.color}`}>{card.val}</p>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
                <h3 className="text-lg font-bold mb-6">Status das Demandas</h3>
                <div className="h-64">
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={chartData.filter(d => d.value > 0)} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                        {chartData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                      </Pie>
                      <Tooltip />
                      <Legend />
                    </PieChart>
                  </ResponsiveContainer>
                </div>
              </div>
              <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
                <h3 className="text-lg font-bold mb-6">Próximos Vencimentos</h3>
                <div className="space-y-4">
                  {deadlines.filter(d => d.status === DeadlineStatus.PENDING).sort((a, b) => new Date(a.data).getTime() - new Date(b.data).getTime()).slice(0, 5).map(d => (
                    <div key={d.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-xl border border-slate-100">
                      <div className="flex items-center gap-3">
                        <div className={`w-2 h-2 rounded-full ${d.data === new Date().toISOString().split('T')[0] ? 'bg-red-600' : 'bg-emerald-600'}`} />
                        <div>
                          <p className="font-semibold text-slate-800">{d.peca}</p>
                          <p className="text-xs text-slate-500">{d.empresa}</p>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className="font-bold text-blue-600">{new Date(d.data).toLocaleDateString('pt-BR')}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}

        {view === 'deadlines' && (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-800 text-white uppercase text-xs font-semibold">
                  <th className="px-6 py-4">Peça / Empresa</th>
                  <th className="px-6 py-4">Responsável</th>
                  <th className="px-6 py-4">Vencimento</th>
                  <th className="px-6 py-4">Status</th>
                  <th className="px-6 py-4 text-center">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {deadlines.map(d => (
                  <tr key={d.id} className="hover:bg-slate-50 transition-colors group">
                    <td className="px-6 py-4">
                      <div className="font-medium text-slate-800">{d.peca}</div>
                      <div className="text-xs text-slate-400">{d.empresa} • {d.instituicao}</div>
                    </td>
                    <td className="px-6 py-4 text-sm font-medium">{d.responsavel}</td>
                    <td className="px-6 py-4 text-sm font-semibold">
                      {new Date(d.data).toLocaleDateString('pt-BR')} <br/>
                      <span className="text-xs font-normal text-slate-400">{d.hora}</span>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-3 py-1 rounded-full text-xs font-bold ${d.status === DeadlineStatus.COMPLETED ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>
                        {d.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => toggleStatus(d.id)} className="p-2 bg-emerald-50 text-emerald-600 rounded-lg hover:bg-emerald-100"><Icons.Check /></button>
                        <button onClick={() => deleteDeadline(d.id)} className="p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-100"><Icons.Trash /></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {view === 'reports' && (
          <div className="space-y-8">
            <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 flex gap-4">
              <div className="flex-1">
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Empresa</label>
                <select className="w-full bg-white border border-slate-200 rounded-xl p-3" value={selectedCompany} onChange={(e) => setSelectedCompany(e.target.value)}>
                  {companies.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="flex-1">
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Início</label>
                <input type="date" className="w-full bg-white border border-slate-200 rounded-xl p-3" value={dateRange.start} onChange={(e) => setDateRange(prev => ({ ...prev, start: e.target.value }))} />
              </div>
              <div className="flex-1">
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Fim</label>
                <input type="date" className="w-full bg-white border border-slate-200 rounded-xl p-3" value={dateRange.end} onChange={(e) => setDateRange(prev => ({ ...prev, end: e.target.value }))} />
              </div>
            </div>
            {/* Gráficos simplificados aqui seriam similares ao dashboard mas filtrados */}
            <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
               <h3 className="font-bold mb-4">Demandas Filtradas ({filteredDeadlines.length})</h3>
               <div className="space-y-2">
                 {filteredDeadlines.map(d => (
                   <div key={d.id} className="flex justify-between p-3 bg-slate-50 rounded-lg text-sm">
                     <span>{d.peca} - {d.empresa}</span>
                     <span className="font-bold">{new Date(d.data).toLocaleDateString('pt-BR')}</span>
                   </div>
                 ))}
               </div>
            </div>
          </div>
        )}

        {view === 'settings' && (
          <div className="max-w-4xl space-y-8">
            <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200">
              <h3 className="text-lg font-bold mb-6 flex items-center gap-2"><Icons.Table /> Integração Google Sheets</h3>
              <input type="text" className="w-full bg-white border border-slate-200 rounded-xl p-3 mb-4" placeholder="ID da Planilha" value={settings.spreadsheetId} onChange={(e) => setSettings(prev => ({ ...prev, spreadsheetId: e.target.value }))} />
              <button onClick={syncWithGoogleSheets} className="bg-blue-600 text-white px-6 py-2 rounded-lg font-bold">Sincronizar</button>
            </div>
          </div>
        )}

        {/* Create Modal with AI */}
        <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Novo Prazo Processual">
          <div className="mb-6">
            <button 
              onClick={() => setShowAiInput(!showAiInput)}
              className="flex items-center gap-2 text-sm font-bold text-blue-600 bg-blue-50 px-4 py-2 rounded-lg hover:bg-blue-100 transition-all"
            >
              <Icons.Sparkles /> {showAiInput ? 'Ocultar Assistente IA' : 'Preencher com IA (E-mail/Texto)'}
            </button>

            {showAiInput && (
              <div className="mt-4 p-4 border border-blue-200 bg-blue-50/30 rounded-xl animate-in fade-in slide-in-from-top-2">
                <p className="text-xs text-slate-500 mb-3 flex items-center gap-2">
                  <Icons.Mail /> Cole o corpo do e-mail ou a solicitação abaixo:
                </p>
                <textarea 
                  className="w-full bg-white border border-slate-200 rounded-xl p-4 text-sm min-h-[120px] shadow-inner focus:ring-2 focus:ring-blue-500 outline-none"
                  placeholder="Ex: Prezado, favor elaborar Parecer Jurídico para a empresa SOUL sobre o contrato X até dia 20/10..."
                  value={aiInputText}
                  onChange={(e) => setAiInputText(e.target.value)}
                />
                <div className="flex justify-end mt-3">
                  <button 
                    onClick={handleAiExtract}
                    disabled={isAiProcessing || !aiInputText.trim()}
                    className="bg-blue-600 text-white px-6 py-2 rounded-lg text-sm font-bold shadow-md hover:bg-blue-700 disabled:opacity-50 flex items-center gap-2"
                  >
                    {isAiProcessing ? <span className="animate-spin text-lg">◌</span> : <Icons.Sparkles />}
                    {isAiProcessing ? 'Extraindo...' : 'Processar Texto'}
                  </button>
                </div>
              </div>
            )}
          </div>

          <form onSubmit={handleAddDeadline} className="grid grid-cols-2 gap-6">
            <div className="col-span-1">
              <label className="block text-sm font-semibold text-slate-600 mb-2">Peça</label>
              <select className="w-full bg-white border border-slate-200 rounded-xl p-3" value={newDeadline.peca} onChange={(e) => setNewDeadline(prev => ({ ...prev, peca: e.target.value }))} required>
                {PECA_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
              </select>
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-semibold text-slate-600 mb-2">Responsável</label>
              <select className="w-full bg-white border border-slate-200 rounded-xl p-3" value={newDeadline.responsavel} onChange={(e) => setNewDeadline(prev => ({ ...prev, responsavel: e.target.value }))} required>
                {RESPONSAVEL_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
              </select>
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-semibold text-slate-600 mb-2">Empresa</label>
              <input className="w-full bg-white border border-slate-200 rounded-xl p-3" placeholder="CLIENTE" value={newDeadline.empresa} onChange={(e) => setNewDeadline(prev => ({ ...prev, empresa: e.target.value.toUpperCase() }))} required />
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-semibold text-slate-600 mb-2">Instituição</label>
              <input className="w-full bg-white border border-slate-200 rounded-xl p-3" placeholder="Foro / Órgão" value={newDeadline.instituicao} onChange={(e) => setNewDeadline(prev => ({ ...prev, instituicao: e.target.value }))} required />
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-semibold text-slate-600 mb-2">Data Vencimento</label>
              <input type="date" className="w-full bg-white border border-slate-200 rounded-xl p-3" value={newDeadline.data} onChange={(e) => setNewDeadline(prev => ({ ...prev, data: e.target.value }))} required />
            </div>
            <div className="col-span-1">
              <label className="block text-sm font-semibold text-slate-600 mb-2">Hora</label>
              <input type="time" className="w-full bg-white border border-slate-200 rounded-xl p-3" value={newDeadline.hora} onChange={(e) => setNewDeadline(prev => ({ ...prev, hora: e.target.value }))} required />
            </div>
            <div className="col-span-2">
              <label className="block text-sm font-semibold text-slate-600 mb-2">Assunto / Descrição</label>
              <textarea className="w-full bg-white border border-slate-200 rounded-xl p-3 min-h-[80px]" value={newDeadline.assunto} onChange={(e) => setNewDeadline(prev => ({ ...prev, assunto: e.target.value }))} required />
            </div>
            <div className="col-span-2 flex justify-end gap-4 mt-4">
              <button type="button" onClick={() => setIsModalOpen(false)} className="px-6 py-3 text-slate-500 font-semibold hover:bg-slate-100 rounded-xl">Cancelar</button>
              <button type="submit" className="px-8 py-3 bg-blue-600 text-white font-bold rounded-xl shadow-lg hover:bg-blue-700">Salvar Prazo</button>
            </div>
          </form>
        </Modal>
      </main>
    </div>
  );
}

export enum DeadlineStatus {
  PENDING = 'PENDENTE',
  COMPLETED = 'CONCLUÍDO',
  OVERDUE = 'ATRASADO'
}

export interface Deadline {
  id: string;
  peca: string;
  responsavel: string;
  empresa: string;
  instituicao: string;
  assunto: string;
  data: string;
  hora: string;
  status: DeadlineStatus;
  createdAt: string;
}

export interface NotificationSettings {
  greenAlertDays: number;
  enableBrowserNotifications: boolean;
  quietMode: boolean;
  spreadsheetId?: string; // ID da planilha do Google
  lastSync?: string;      // Data da última sincronização
  responsaveis: string[]; // Lista dinâmica de responsáveis
}

export interface ReportStats {
  total: number;
  concluidos: number;
  pendentes: number;
  atrasados: number;
}

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Deadline, 
  DeadlineStatus,
  NotificationSettings
} from './types';
import { 
  Icons, 
  COLORS, 
  PECA_OPTIONS, 
  RESPONSAVEL_OPTIONS 
} from './constants';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer, 
  PieChart, 
  Pie, 
  Cell 
} from 'recharts';
import { getLegalInsights, extractDeadlineFromText } from './services/geminiService';

// --- Components ---

const Sidebar = ({ currentView, setView }: { currentView: string, setView: (v: string) => void }) => (
  <aside className="w-64 bg-slate-900 text-white min-h-screen flex flex-col fixed left-0 top-0 z-40">
    <div className="p-6">
      <h1 className="text-xl font-bold flex items-center gap-2 tracking-tight">
        <span className="bg-blue-600 p-1 rounded">JC</span> JurisControl
      </h1>
    </div>
    <nav className="flex-1 px-4 mt-4 space-y-1">
      <button 
        onClick={() => setView('dashboard')}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${currentView === 'dashboard' ? 'bg-blue-600 shadow-lg' : 'hover:bg-slate-800'}`}
      >
        <Icons.Dashboard /> Dashboard
      </button>
      <button 
        onClick={() => setView('deadlines')}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${currentView === 'deadlines' ? 'bg-blue-600 shadow-lg' : 'hover:bg-slate-800'}`}
      >
        <Icons.List /> Controle Geral
      </button>
      <button 
        onClick={() => setView('reports')}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${currentView === 'reports' ? 'bg-blue-600 shadow-lg' : 'hover:bg-slate-800'}`}
      >
        <Icons.Report /> Relatórios
      </button>
      <div className="pt-4 pb-2 px-4">
        <p className="text-[10px] uppercase font-bold text-slate-500 tracking-widest">Ajustes</p>
      </div>
      <button 
        onClick={() => setView('settings')}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${currentView === 'settings' ? 'bg-blue-600 shadow-lg' : 'hover:bg-slate-800'}`}
      >
        <Icons.Settings /> Configurações
      </button>
    </nav>
    <div className="p-4 text-xs text-slate-500 text-center border-t border-slate-800">
      JurisControl v1.0.0
    </div>
  </aside>
);

const Modal = ({ isOpen, onClose, title, children }: { isOpen: boolean, onClose: () => void, title: string, children?: React.ReactNode }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl w-full max-w-2xl shadow-2xl animate-in fade-in zoom-in duration-200 overflow-hidden">
        <div className="p-6 border-b flex justify-between items-center bg-slate-50">
          <h2 className="text-xl font-semibold text-slate-800">{title}</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-full transition-colors">&times;</button>
        </div>
        <div className="p-6 max-h-[85vh] overflow-y-auto">
          {children}
        </div>
      </div>
    </div>
  );
};

// --- Main App ---

export default function App() {
  const [view, setView] = useState('dashboard');
  const [deadlines, setDeadlines] = useState<Deadline[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isNotifOpen, setIsNotifOpen] = useState(false);
  const [insights, setInsights] = useState<string>('Analisando prazos com Inteligência Artificial...');
  const [isSyncing, setIsSyncing] = useState(false);

  // AI Form State
  const [aiInputText, setAiInputText] = useState('');
  const [isAiProcessing, setIsAiProcessing] = useState(false);
  const [showAiInput, setShowAiInput] = useState(false);

  // Settings State
  const [settings, setSettings] = useState<NotificationSettings>({
    greenAlertDays: 5,
    enableBrowserNotifications: true,
    quietMode: false,
    spreadsheetId: '',
    responsaveis: RESPONSAVEL_OPTIONS
  });

  const [newRespName, setNewRespName] = useState('');

  // Form State
  const [newDeadline, setNewDeadline] = useState<Partial<Deadline>>({
    peca: PECA_OPTIONS[0],
    responsavel: settings.responsaveis[0],
    empresa: '',
    instituicao: '',
    assunto: '',
    data: new Date().toISOString().split('T')[0],
    hora: '09:00',
    status: DeadlineStatus.PENDING
  });

  // Report Filters
  const [selectedCompany, setSelectedCompany] = useState('Todas');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  // Load Initial Data
  useEffect(() => {
    const saved = localStorage.getItem('juris_deadlines');
    const savedSettings = localStorage.getItem('juris_settings');
    if (saved) setDeadlines(JSON.parse(saved));
    if (savedSettings) {
      const parsed = JSON.parse(savedSettings);
      // Migração para garantir que 'responsaveis' exista
      if (!parsed.responsaveis) parsed.responsaveis = RESPONSAVEL_OPTIONS;
      setSettings(parsed);
    }

    if (!saved) {
      const mock: Deadline[] = [
        { id: '1', peca: 'Parecer Jurídico', responsavel: 'EDUARDO', empresa: 'SOUL', instituicao: 'Bom Jesus dos Perdões/SP', assunto: 'Rescisão contratual e violação ao devido processo legal', data: new Date().toISOString().split('T')[0], hora: '14:00', status: DeadlineStatus.COMPLETED, createdAt: new Date().toISOString() },
        { id: '2', peca: 'Mandado de Segurança', responsavel: 'EDUARDO', empresa: 'SOUL', instituicao: 'Bom Jesus dos Perdões/SP', assunto: 'Rescisão contratual e violação ao devido processo legal', data: new Date(Date.now() + 86400000).toISOString().split('T')[0], hora: '10:00', status: DeadlineStatus.PENDING, createdAt: new Date().toISOString() },
        { id: '3', peca: 'Exceção de Pré-Executividade', responsavel: 'DANILO', empresa: 'SOUL', instituicao: 'Dois Córregos/SP', assunto: 'Prazo exíguo para execução e ausência de mobilização', data: new Date(Date.now() + 86400000 * 3).toISOString().split('T')[0], hora: '15:00', status: DeadlineStatus.PENDING, createdAt: new Date().toISOString() },
      ];
      setDeadlines(mock);
    }
  }, []);

  // Update form default when responsibles change
  useEffect(() => {
    if (settings.responsaveis.length > 0 && !newDeadline.responsavel) {
      setNewDeadline(prev => ({ ...prev, responsavel: settings.responsaveis[0] }));
    }
  }, [settings.responsaveis]);

  // AI Extraction Logic
  const handleAiExtract = async () => {
    if (!aiInputText.trim()) return;
    setIsAiProcessing(true);
    const extractedData = await extractDeadlineFromText(aiInputText);
    if (extractedData) {
      setNewDeadline(prev => ({
        ...prev,
        ...extractedData,
        peca: PECA_OPTIONS.includes(extractedData.peca) ? extractedData.peca : prev.peca
      }));
      setShowAiInput(false);
      setAiInputText('');
    } else {
      alert("Não foi possível extrair os dados. Tente um texto mais claro.");
    }
    setIsAiProcessing(false);
  };

  // Parsing helper for Google's specific date format
  const parseGoogleDate = (dateStr: string) => {
    if (!dateStr) return new Date().toISOString().split('T')[0];
    const match = dateStr.match(/Date\((\d+),(\d+),(\d+)\)/);
    if (match) {
      const year = match[1];
      const month = (parseInt(match[2]) + 1).toString().padStart(2, '0');
      const day = match[3].padStart(2, '0');
      return `${year}-${month}-${day}`;
    }
    const date = new Date(dateStr);
    return isNaN(date.getTime()) ? new Date().toISOString().split('T')[0] : date.toISOString().split('T')[0];
  };

  // Sync with Google Sheets
  const syncWithGoogleSheets = async () => {
    if (!settings.spreadsheetId) {
      alert("Por favor, informe o ID da planilha nas configurações.");
      setView('settings');
      return;
    }

    setIsSyncing(true);
    try {
      const url = `https://docs.google.com/spreadsheets/d/${settings.spreadsheetId}/gviz/tq?tqx=out:json`;
      const response = await fetch(url);
      const text = await response.text();

      const start = text.indexOf('{');
      const end = text.lastIndexOf('}');
      if (start === -1 || end === -1) throw new Error("Formato de resposta inválido");

      const jsonStr = text.substring(start, end + 1);
      const json = JSON.parse(jsonStr);
      const rows = json.table.rows;

      const newDeadlines: Deadline[] = rows
        .filter((row: any) => row.c && row.c[0] && row.c[0].v !== 'PEÇA' && row.c[0].v !== 'Peça') 
        .map((row: any, index: number) => {
          const c = row.c;
          return {
            id: `sheet-${index}-${Date.now()}`,
            peca: c[0]?.v || '',
            responsavel: c[1]?.v || '',
            empresa: c[2]?.v?.toString().toUpperCase() || '',
            instituicao: c[3]?.v || '',
            assunto: c[4]?.v || '',
            data: parseGoogleDate(c[5]?.v),
            hora: c[6]?.v || '09:00',
            status: (c[7]?.v?.toString().toUpperCase() === 'CONCLUÍDO' || c[7]?.v?.toString().toUpperCase() === 'CONCLUIDO') 
              ? DeadlineStatus.COMPLETED 
              : DeadlineStatus.PENDING,
            createdAt: new Date().toISOString()
          };
        });

      if (newDeadlines.length > 0) {
        if (confirm(`Encontrados ${newDeadlines.length} registros. Deseja substituir sua base atual?`)) {
          setDeadlines(newDeadlines);
          setSettings(prev => ({ ...prev, lastSync: new Date().toLocaleString('pt-BR') }));
          alert("Sincronização concluída com sucesso!");
        }
      } else {
        alert("Nenhum dado válido encontrado.");
      }
    } catch (error) {
      console.error("Sync Error:", error);
      alert("Erro ao sincronizar. Verifique o ID e as permissões da planilha.");
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    if (deadlines.length > 0) {
      const fetchInsights = async () => {
        const text = await getLegalInsights(deadlines);
        setInsights(text || "Sem insights no momento.");
      };
      fetchInsights();
    }
  }, [deadlines]);

  useEffect(() => {
    localStorage.setItem('juris_deadlines', JSON.stringify(deadlines));
  }, [deadlines]);

  useEffect(() => {
    localStorage.setItem('juris_settings', JSON.stringify(settings));
  }, [settings]);

  const alertData = useMemo(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    const tomorrowStr = new Date(Date.now() + 86400000).toISOString().split('T')[0];
    const thresholdDate = new Date(Date.now() + 86400000 * settings.greenAlertDays);

    const pending = deadlines.filter(d => d.status === DeadlineStatus.PENDING);

    const red = pending.filter(d => d.data === todayStr);
    const yellow = pending.filter(d => d.data === tomorrowStr);
    const green = pending.filter(d => {
      const dDate = new Date(d.data);
      return d.data > tomorrowStr && dDate <= thresholdDate;
    });

    return { red, yellow, green };
  }, [deadlines, settings.greenAlertDays]);

  const totalUrgent = alertData.red.length + alertData.yellow.length + alertData.green.length;

  const companies = useMemo(() => {
    const list = Array.from(new Set(deadlines.map(d => d.empresa)));
    return ['Todas', ...list];
  }, [deadlines]);

  const handleAddDeadline = (e: React.FormEvent) => {
    e.preventDefault();
    const deadline: Deadline = {
      ...(newDeadline as Deadline),
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString()
    };
    setDeadlines(prev => [...prev, deadline]);
    setIsModalOpen(false);
    setNewDeadline({
      peca: PECA_OPTIONS[0],
      responsavel: settings.responsaveis[0],
      empresa: '',
      instituicao: '',
      assunto: '',
      data: new Date().toISOString().split('T')[0],
      hora: '09:00',
      status: DeadlineStatus.PENDING
    });
  };

  const toggleStatus = (id: string) => {
    setDeadlines(prev => prev.map(d => {
      if (d.id === id) {
        return { 
          ...d, 
          status: d.status === DeadlineStatus.COMPLETED ? DeadlineStatus.PENDING : DeadlineStatus.COMPLETED 
        };
      }
      return d;
    }));
  };

  const deleteDeadline = (id: string) => {
    if (confirm('Deseja realmente excluir este prazo?')) {
      setDeadlines(prev => prev.filter(d => d.id !== id));
    }
  };

  const handleAddResponsavel = () => {
    if (!newRespName.trim()) return;
    const name = newRespName.trim().toUpperCase();
    if (settings.responsaveis.includes(name)) {
      alert("Este responsável já está cadastrado.");
      return;
    }
    setSettings(prev => ({
      ...prev,
      responsaveis: [...prev.responsaveis, name]
    }));
    setNewRespName('');
  };

  const handleRemoveResponsavel = (name: string) => {
    if (confirm(`Remover "${name}" da lista de responsáveis?`)) {
      setSettings(prev => ({
        ...prev,
        responsaveis: prev.responsaveis.filter(r => r !== name)
      }));
    }
  };

  const filteredDeadlines = useMemo(() => {
    return deadlines.filter(d => {
      const matchCompany = selectedCompany === 'Todas' || d.empresa === selectedCompany;
      const matchStart = !dateRange.start || d.data >= dateRange.start;
      const matchEnd = !dateRange.end || d.data <= dateRange.end;
      return matchCompany && matchStart && matchEnd;
    });
  }, [deadlines, selectedCompany, dateRange]);

  const stats = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return {
      total: filteredDeadlines.length,
      concluidos: filteredDeadlines.filter(d => d.status === DeadlineStatus.COMPLETED).length,
      pendentes: filteredDeadlines.filter(d => d.status === DeadlineStatus.PENDING && d.data >= today).length,
      atrasados: filteredDeadlines.filter(d => d.status === DeadlineStatus.PENDING && d.data < today).length,
    };
  }, [filteredDeadlines]);

  const chartData = [
    { name: 'Concluídos', value: stats.concluidos, color: COLORS.success },
    { name: 'Pendentes', value: stats.pendentes, color: COLORS.warning },
    { name: 'Atrasados', value: stats.atrasados, color: COLORS.danger },
  ];

  return (
    <div className="flex bg-slate-50 min-h-screen">
      <Sidebar currentView={view} setView={setView} />

      {/* Notification Drawer */}
      {isNotifOpen && (
        <div className="fixed inset-0 z-50 overflow-hidden">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsNotifOpen(false)} />
          <div className="absolute right-0 top-0 h-full w-96 bg-white shadow-2xl animate-in slide-in-from-right duration-300 flex flex-col">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50">
              <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                <Icons.Bell /> Alertas do Sistema
              </h2>
              <button onClick={() => setIsNotifOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-colors">&times;</button>
            </div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6">
              {alertData.red.length > 0 && (
                <section>
                  <h3 className="text-xs font-black text-red-600 uppercase tracking-widest mb-3 flex items-center gap-2">
                    <span className="w-2 h-2 bg-red-600 rounded-full animate-pulse" /> Vencem Hoje
                  </h3>
                  <div className="space-y-3">
                    {alertData.red.map(d => (
                      <div key={d.id} className="p-4 bg-red-50 border border-red-100 rounded-xl">
                        <p className="font-bold text-red-900">{d.peca}</p>
                        <p className="text-xs text-red-700">{d.empresa} • {d.instituicao}</p>
