  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isNotifOpen, setIsNotifOpen] = useState(false);
  const [insights, setInsights] = useState<string>('Analisando prazos com Inteligência Artificial...');
  const [isSyncing, setIsSyncing] = useState(false);

  // AI Form State
  const [aiInputText, setAiInputText] = useState('');
  const [isAiProcessing, setIsAiProcessing] = useState(false);
  const [showAiInput, setShowAiInput] = useState(false);

  // Settings State
  const [settings, setSettings] = useState<NotificationSettings>({
    greenAlertDays: 5,
    enableBrowserNotifications: true,
    quietMode: false,
    spreadsheetId: '',
    responsaveis: RESPONSAVEL_OPTIONS,
    pecas: PECA_OPTIONS,
    empresas: [] // Inicia vazio ou com base nos dados existentes
  });

  const [newRespName, setNewRespName] = useState('');
  const [newPecaName, setNewPecaName] = useState('');
  const [newEmpresaName, setNewEmpresaName] = useState('');

  // Form State
  const [newDeadline, setNewDeadline] = useState<Partial<Deadline>>({
    peca: '',
    responsavel: '',
    empresa: '',
    instituicao: '',
    assunto: '',
    data: new Date().toISOString().split('T')[0],
    hora: '09:00',
    status: DeadlineStatus.PENDING
  });

  // Report Filters
  const [selectedCompany, setSelectedCompany] = useState('Todas');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  // Load Initial Data
  useEffect(() => {
    const saved = localStorage.getItem('juris_deadlines');
    const savedSettings = localStorage.getItem('juris_settings');

    let loadedDeadlines: Deadline[] = [];
    if (saved) {
      loadedDeadlines = JSON.parse(saved);
      setDeadlines(loadedDeadlines);
    } else {
      const mock: Deadline[] = [
        { id: '1', peca: 'Parecer Jurídico', responsavel: 'EDUARDO', empresa: 'SOUL', instituicao: 'Bom Jesus dos Perdões/SP', assunto: 'Rescisão contratual e violação ao devido processo legal', data: new Date().toISOString().split('T')[0], hora: '14:00', status: DeadlineStatus.COMPLETED, createdAt: new Date().toISOString() },
        { id: '2', peca: 'Mandado de Segurança', responsavel: 'EDUARDO', empresa: 'SOUL', instituicao: 'Bom Jesus dos Perdões/SP', assunto: 'Rescisão contratual e violação ao devido processo legal', data: new Date(Date.now() + 86400000).toISOString().split('T')[0], hora: '10:00', status: DeadlineStatus.PENDING, createdAt: new Date().toISOString() },
        { id: '3', peca: 'Exceção de Pré-Executividade', responsavel: 'DANILO', empresa: 'SOUL', instituicao: 'Dois Córregos/SP', assunto: 'Prazo exíguo para execução e ausência de mobilização', data: new Date(Date.now() + 86400000 * 3).toISOString().split('T')[0], hora: '15:00', status: DeadlineStatus.PENDING, createdAt: new Date().toISOString() },
      ];
      loadedDeadlines = mock;
      setDeadlines(mock);
    }

    if (savedSettings) {
      const parsed = JSON.parse(savedSettings);
      if (!parsed.responsaveis) parsed.responsaveis = RESPONSAVEL_OPTIONS;
      if (!parsed.pecas) parsed.pecas = PECA_OPTIONS;
      if (!parsed.empresas) {
        // Extrai empresas únicas dos prazos carregados se a lista estiver vazia
        parsed.empresas = Array.from(new Set(loadedDeadlines.map(d => d.empresa))).filter(Boolean);
      }
      setSettings(parsed);
    }
  }, []);

  // Set form defaults when settings are ready
  useEffect(() => {
    setNewDeadline(prev => ({
      ...prev,
      peca: prev.peca || settings.pecas[0] || '',
      responsavel: prev.responsavel || settings.responsaveis[0] || '',
      empresa: prev.empresa || settings.empresas[0] || ''
    }));
  }, [settings]);

  // AI Extraction Logic
  const handleAiExtract = async () => {
    if (!aiInputText.trim()) return;
    setIsAiProcessing(true);
    const extractedData = await extractDeadlineFromText(aiInputText);
    if (extractedData) {
      // Se a empresa extraída não existir, podemos sugerir adicioná-la ou apenas preencher o campo
      setNewDeadline(prev => ({
        ...prev,
        ...extractedData,
        peca: settings.pecas.includes(extractedData.peca) ? extractedData.peca : (settings.pecas[0] || extractedData.peca)
      }));
      setShowAiInput(false);
      setAiInputText('');
    } else {
      alert("Não foi possível extrair os dados. Tente um texto mais claro.");
    }
    setIsAiProcessing(false);
  };

  const syncWithGoogleSheets = async () => {
    if (!settings.spreadsheetId) {
      alert("Por favor, informe o ID da planilha nas configurações.");
      setView('settings');
      return;
    }
    setIsSyncing(true);
    try {
      const url = `https://docs.google.com/spreadsheets/d/${settings.spreadsheetId}/gviz/tq?tqx=out:json`;
      const response = await fetch(url);
      const text = await response.text();
      const start = text.indexOf('{');
      const end = text.lastIndexOf('}');
      if (start === -1 || end === -1) throw new Error("Formato inválido");
      const json = JSON.parse(text.substring(start, end + 1));
      const newDeadlines: Deadline[] = json.table.rows
        .filter((row: any) => row.c && row.c[0] && row.c[0].v !== 'PEÇA') 
        .map((row: any, index: number) => {
          const c = row.c;
          return {
            id: `sheet-${index}-${Date.now()}`,
            peca: c[0]?.v || '',
            responsavel: c[1]?.v || '',
            empresa: c[2]?.v?.toString().toUpperCase() || '',
            instituicao: c[3]?.v || '',
            assunto: c[4]?.v || '',
            data: new Date().toISOString().split('T')[0], // Simplified for this context
            hora: c[6]?.v || '09:00',
            status: DeadlineStatus.PENDING,
            createdAt: new Date().toISOString()
          };
        });
      setDeadlines(newDeadlines);
      alert("Sincronizado!");
    } catch (e) {
      alert("Erro na sincronização.");
    } finally { setIsSyncing(false); }
  };

  useEffect(() => {
    if (deadlines.length > 0) {
      getLegalInsights(deadlines).then(setInsights);
    }
  }, [deadlines]);

  useEffect(() => {
    localStorage.setItem('juris_deadlines', JSON.stringify(deadlines));
  }, [deadlines]);

  useEffect(() => {
    localStorage.setItem('juris_settings', JSON.stringify(settings));
  }, [settings]);

  const alertData = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const pending = deadlines.filter(d => d.status === DeadlineStatus.PENDING);
    return {
      red: pending.filter(d => d.data === today),
      yellow: pending.filter(d => d.data > today), // Simplified
      green: []
    };
  }, [deadlines]);

  const stats = useMemo(() => ({
    total: deadlines.length,
    concluidos: deadlines.filter(d => d.status === DeadlineStatus.COMPLETED).length,
    pendentes: deadlines.filter(d => d.status === DeadlineStatus.PENDING).length,
    atrasados: 0
  }), [deadlines]);

  const chartData = [
    { name: 'Concluídos', value: stats.concluidos, color: COLORS.success },
    { name: 'Pendentes', value: stats.pendentes, color: COLORS.warning },
  ];

  const handleAddDeadline = (e: React.FormEvent) => {
    e.preventDefault();
    const deadline: Deadline = {
      ...(newDeadline as Deadline),
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString()
    };
    setDeadlines(prev => [...prev, deadline]);
    setIsModalOpen(false);
  };

  const toggleStatus = (id: string) => {
    setDeadlines(prev => prev.map(d => d.id === id ? { ...d, status: d.status === DeadlineStatus.COMPLETED ? DeadlineStatus.PENDING : DeadlineStatus.COMPLETED } : d));
  };

  const deleteDeadline = (id: string) => {
    if (confirm('Excluir?')) setDeadlines(prev => prev.filter(d => d.id !== id));
  };

  // Management Handlers
  const addItem = (listKey: 'responsaveis' | 'pecas' | 'empresas', value: string, setter: (v: string) => void) => {
    if (!value.trim()) return;
    const val = value.trim().toUpperCase();
    if (settings[listKey].includes(val)) return alert("Já cadastrado.");
    setSettings(prev => ({ ...prev, [listKey]: [...prev[listKey], val] }));
    setter('');
  };

  const removeItem = (listKey: 'responsaveis' | 'pecas' | 'empresas', value: string) => {
    if (confirm(`Remover "${value}"?`)) {
      setSettings(prev => ({ ...prev, [listKey]: prev[listKey].filter(v => v !== value) }));
    }
  };

  return (
    <div className="flex bg-slate-50 min-h-screen">
      <Sidebar currentView={view} setView={setView} />

      {isNotifOpen && (
        <div className="fixed inset-0 z-50 overflow-hidden flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsNotifOpen(false)} />
          <div className="relative w-96 bg-white shadow-2xl p-6">
            <h2 className="text-xl font-bold mb-4">Alertas</h2>
            {alertData.red.map(d => <div key={d.id} className="p-3 bg-red-50 mb-2 rounded">{d.peca} - {d.empresa}</div>)}
            <button onClick={() => setIsNotifOpen(false)} className="mt-4 w-full py-2 bg-slate-100 rounded font-bold">Fechar</button>
          </div>
        </div>
      )}

      <main className="ml-64 flex-1 p-8">
        <div className="flex justify-between items-start mb-8">
          <h2 className="text-3xl font-bold text-slate-800">
            {view === 'dashboard' && 'Dashboard'}
            {view === 'deadlines' && 'Controle Geral'}
            {view === 'reports' && 'Relatórios'}
            {view === 'settings' && 'Configurações'}
          </h2>
          <div className="flex gap-4">
            <button onClick={() => setIsNotifOpen(true)} className="p-3 bg-white border rounded-xl relative">
              <Icons.Bell />
              {alertData.red.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[10px] w-5 h-5 flex items-center justify-center rounded-full">{alertData.red.length}</span>}
            </button>
            <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2">
              <Icons.Plus /> Novo Prazo
            </button>
          </div>
        </div>

        {view === 'dashboard' && (
          <div className="space-y-8">
            <div className="bg-white p-6 rounded-2xl border border-blue-100 shadow-sm flex items-center gap-3">
              <Icons.Sparkles /> <p className="italic text-sm text-slate-700">"{insights}"</p>
            </div>
            <div className="grid grid-cols-4 gap-6">
              <div className="bg-white p-6 rounded-2xl border">Total: {stats.total}</div>
              <div className="bg-emerald-50 p-6 rounded-2xl border text-emerald-700 font-bold">Concluídos: {stats.concluidos}</div>
              <div className="bg-amber-50 p-6 rounded-2xl border text-amber-700 font-bold">Pendentes: {stats.pendentes}</div>
            </div>
          </div>
        )}

        {view === 'deadlines' && (
          <div className="bg-white rounded-2xl border overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-800 text-white text-xs uppercase">
                <tr><th className="p-4">Peça/Empresa</th><th className="p-4">Responsável</th><th className="p-4">Status</th><th className="p-4">Ações</th></tr>
              </thead>
              <tbody className="divide-y">
                {deadlines.map(d => (
                  <tr key={d.id} className="hover:bg-slate-50">
                    <td className="p-4"><strong>{d.peca}</strong><br/><span className="text-xs text-slate-400">{d.empresa}</span></td>
                    <td className="p-4">{d.responsavel}</td>
                    <td className="p-4"><span className={`px-2 py-1 rounded-full text-[10px] font-bold ${d.status === DeadlineStatus.COMPLETED ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>{d.status}</span></td>
                    <td className="p-4 flex gap-2"><button onClick={() => toggleStatus(d.id)}><Icons.Check /></button><button onClick={() => deleteDeadline(d.id)}><Icons.Trash /></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {view === 'settings' && (
          <div className="max-w-4xl space-y-8 pb-20">
            {/* Responsáveis */}
            <div className="bg-white p-8 rounded-2xl border">
              <h3 className="text-lg font-bold mb-4 flex items-center gap-2"><Icons.List /> Responsáveis</h3>
              <div className="flex gap-2 mb-4">
                <input className="flex-1 border p-2 rounded uppercase" value={newRespName} onChange={e => setNewRespName(e.target.value)} placeholder="Novo Responsável..." />
                <button onClick={() => addItem('responsaveis', newRespName, setNewRespName)} className="bg-blue-600 text-white px-4 rounded">Add</button>
              </div>
              <div className="flex flex-wrap gap-2">
                {settings.responsaveis.map(r => <span key={r} className="bg-slate-100 px-3 py-1 rounded-full text-sm flex items-center gap-2">{r} <button onClick={() => removeItem('responsaveis', r)}>&times;</button></span>)}
              </div>
            </div>

            {/* Peças */}
            <div className="bg-white p-8 rounded-2xl border">
              <h3 className="text-lg font-bold mb-4 flex items-center gap-2"><Icons.Table /> Peças Processuais</h3>
              <div className="flex gap-2 mb-4">
                <input className="flex-1 border p-2 rounded uppercase" value={newPecaName} onChange={e => setNewPecaName(e.target.value)} placeholder="Nova Peça..." />
                <button onClick={() => addItem('pecas', newPecaName, setNewPecaName)} className="bg-blue-600 text-white px-4 rounded">Add</button>
              </div>
              <div className="flex flex-wrap gap-2">
                {settings.pecas.map(p => <span key={p} className="bg-slate-100 px-3 py-1 rounded-full text-sm flex items-center gap-2">{p} <button onClick={() => removeItem('pecas', p)}>&times;</button></span>)}
              </div>
            </div>

            {/* Empresas */}
            <div className="bg-white p-8 rounded-2xl border">
              <h3 className="text-lg font-bold mb-4 flex items-center gap-2"><Icons.Report /> Empresas / Clientes</h3>
              <div className="flex gap-2 mb-4">
                <input className="flex-1 border p-2 rounded uppercase" value={newEmpresaName} onChange={e => setNewEmpresaName(e.target.value)} placeholder="Nova Empresa..." />
                <button onClick={() => addItem('empresas', newEmpresaName, setNewEmpresaName)} className="bg-blue-600 text-white px-4 rounded">Add</button>
              </div>
              <div className="flex flex-wrap gap-2">
                {settings.empresas.map(e => <span key={e} className="bg-slate-100 px-3 py-1 rounded-full text-sm flex items-center gap-2">{e} <button onClick={() => removeItem('empresas', e)}>&times;</button></span>)}
              </div>
            </div>

            <div className="bg-white p-8 rounded-2xl border">
              <h3 className="text-lg font-bold mb-4">Google Sheets</h3>
              <input className="w-full border p-2 rounded mb-4" placeholder="ID da Planilha" value={settings.spreadsheetId} onChange={e => setSettings(prev => ({ ...prev, spreadsheetId: e.target.value }))} />
              <button onClick={syncWithGoogleSheets} className="bg-blue-600 text-white px-6 py-2 rounded font-bold">Sincronizar</button>
            </div>
          </div>
        )}

        <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Novo Prazo">
          <div className="mb-4">
            <button onClick={() => setShowAiInput(!showAiInput)} className="text-blue-600 text-xs font-bold flex items-center gap-1 bg-blue-50 px-3 py-1 rounded-full"><Icons.Sparkles /> {showAiInput ? 'Ocultar IA' : 'Preencher com IA'}</button>
            {showAiInput && (
              <div className="mt-2 p-3 bg-blue-50/50 rounded border">
                <textarea className="w-full p-2 text-sm rounded border" placeholder="Cole o e-mail aqui..." value={aiInputText} onChange={e => setAiInputText(e.target.value)} />
                <button onClick={handleAiExtract} disabled={isAiProcessing} className="mt-2 bg-blue-600 text-white text-xs px-4 py-2 rounded font-bold">{isAiProcessing ? 'Processando...' : 'Extrair'}</button>
              </div>
            )}
          </div>
          <form onSubmit={handleAddDeadline} className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-bold text-slate-500 mb-1">PEÇA</label>
              <select className="w-full border p-2 rounded" value={newDeadline.peca} onChange={e => setNewDeadline(prev => ({ ...prev, peca: e.target.value }))} required>
                {settings.pecas.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 mb-1">RESPONSÁVEL</label>
              <select className="w-full border p-2 rounded" value={newDeadline.responsavel} onChange={e => setNewDeadline(prev => ({ ...prev, responsavel: e.target.value }))} required>
                {settings.responsaveis.map(r => <option key={r} value={r}>{r}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 mb-1">EMPRESA</label>
              <select className="w-full border p-2 rounded" value={newDeadline.empresa} onChange={e => setNewDeadline(prev => ({ ...prev, empresa: e.target.value }))} required>
                {settings.empresas.map(e => <option key={e} value={e}>{e}</option>)}
                <option value="">+ Adicione nas configurações</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 mb-1">DATA</label>
              <input type="date" className="w-full border p-2 rounded" value={newDeadline.data} onChange={e => setNewDeadline(prev => ({ ...prev, data: e.target.value }))} required />
            </div>
            <div className="col-span-2">
              <label className="block text-xs font-bold text-slate-500 mb-1">ASSUNTO</label>
              <textarea className="w-full border p-2 rounded" value={newDeadline.assunto} onChange={e => setNewDeadline(prev => ({ ...prev, assunto: e.target.value }))} required />
            </div>
            <div className="col-span-2 flex justify-end gap-2 mt-4">
              <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-400 font-bold">Cancelar</button>
              <button type="submit" className="px-6 py-2 bg-blue-600 text-white rounded font-bold shadow-lg">Salvar</button>
            </div>
          </form>
        </Modal>
      </main>
    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Deadline, 
  DeadlineStatus,
  NotificationSettings
} from './types';
import { 
  Icons, 
  COLORS, 
  PECA_OPTIONS, 
  RESPONSAVEL_OPTIONS 
} from './constants';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer, 
  PieChart, 
  Pie, 
  Cell 
} from 'recharts';
import { getLegalInsights, extractDeadlineFromText } from './services/geminiService';

// --- Components ---

const Sidebar = ({ currentView, setView }: { currentView: string, setView: (v: string) => void }) => (
  <aside className="w-64 bg-slate-900 text-white min-h-screen flex flex-col fixed left-0 top-0 z-40">
    <div className="p-6">
      <h1 className="text-xl font-bold flex items-center gap-2 tracking-tight">
        <span className="bg-blue-600 p-1 rounded">JC</span> JurisControl
      </h1>
    </div>
    <nav className="flex-1 px-4 mt-4 space-y-1">
      <button 
        onClick={() => setView('dashboard')}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${currentView === 'dashboard' ? 'bg-blue-600 shadow-lg' : 'hover:bg-slate-800'}`}
      >
        <Icons.Dashboard /> Dashboard
      </button>
      <button 
        onClick={() => setView('deadlines')}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${currentView === 'deadlines' ? 'bg-blue-600 shadow-lg' : 'hover:bg-slate-800'}`}
      >
        <Icons.List /> Controle Geral
      </button>
      <button 
        onClick={() => setView('reports')}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${currentView === 'reports' ? 'bg-blue-600 shadow-lg' : 'hover:bg-slate-800'}`}
      >
        <Icons.Report /> Relatórios
      </button>
      <div className="pt-4 pb-2 px-4">
        <p className="text-[10px] uppercase font-bold text-slate-500 tracking-widest">Ajustes</p>
      </div>
      <button 
        onClick={() => setView('settings')}
        className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all ${currentView === 'settings' ? 'bg-blue-600 shadow-lg' : 'hover:bg-slate-800'}`}
      >
        <Icons.Settings /> Configurações
      </button>
    </nav>
    <div className="p-4 text-xs text-slate-500 text-center border-t border-slate-800">
      JurisControl v1.0.0
    </div>
  </aside>
);

const Modal = ({ isOpen, onClose, title, children }: { isOpen: boolean, onClose: () => void, title: string, children?: React.ReactNode }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl w-full max-w-2xl shadow-2xl animate-in fade-in zoom-in duration-200 overflow-hidden">
        <div className="p-6 border-b flex justify-between items-center bg-slate-50">
          <h2 className="text-xl font-semibold text-slate-800">{title}</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-full transition-colors">&times;</button>
        </div>
        <div className="p-6 max-h-[85vh] overflow-y-auto">
          {children}
        </div>
      </div>
    </div>
  );
};

// --- Main App ---

export default function App() {
  const [view, setView] = useState('dashboard');
  const [deadlines, setDeadlines] = useState<Deadline[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isNotifOpen, setIsNotifOpen] = useState(false);
  const [insights, setInsights] = useState<string>('Analisando prazos com Inteligência Artificial...');
  const [isSyncing, setIsSyncing] = useState(false);

  // AI Form State
  const [aiInputText, setAiInputText] = useState('');
  const [isAiProcessing, setIsAiProcessing] = useState(false);
  const [showAiInput, setShowAiInput] = useState(false);

  // Settings State
  const [settings, setSettings] = useState<NotificationSettings>({
    greenAlertDays: 5,
    enableBrowserNotifications: true,
    quietMode: false,
    spreadsheetId: '',
    responsaveis: RESPONSAVEL_OPTIONS,
    pecas: PECA_OPTIONS,
    empresas: []
  });

  const [newRespName, setNewRespName] = useState('');
  const [newPecaName, setNewPecaName] = useState('');
  const [newEmpresaName, setNewEmpresaName] = useState('');

  // Form State
  const [newDeadline, setNewDeadline] = useState<Partial<Deadline>>({
    peca: '',
    responsavel: '',
    empresa: '',
    instituicao: '',
    assunto: '',
    data: new Date().toISOString().split('T')[0],
    hora: '09:00',
    status: DeadlineStatus.PENDING
  });

  // Report Filters
  const [selectedCompany, setSelectedCompany] = useState('Todas');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  // Load Initial Data
  useEffect(() => {
    const saved = localStorage.getItem('juris_deadlines');
    const savedSettings = localStorage.getItem('juris_settings');

    let loadedDeadlines: Deadline[] = [];
    if (saved) {
      loadedDeadlines = JSON.parse(saved);
      setDeadlines(loadedDeadlines);
    } else {
      const mock: Deadline[] = [
        { id: '1', peca: 'Parecer Jurídico', responsavel: 'EDUARDO', empresa: 'SOUL', instituicao: 'Bom Jesus dos Perdões/SP', assunto: 'Rescisão contratual e violação ao devido processo legal', data: new Date().toISOString().split('T')[0], hora: '14:00', status: DeadlineStatus.COMPLETED, createdAt: new Date().toISOString() },
        { id: '2', peca: 'Mandado de Segurança', responsavel: 'EDUARDO', empresa: 'SOUL', instituicao: 'Bom Jesus dos Perdões/SP', assunto: 'Rescisão contratual e violação ao devido processo legal', data: new Date(Date.now() + 86400000).toISOString().split('T')[0], hora: '10:00', status: DeadlineStatus.PENDING, createdAt: new Date().toISOString() },
        { id: '3', peca: 'Exceção de Pré-Executividade', responsavel: 'DANILO', empresa: 'SOUL', instituicao: 'Dois Córregos/SP', assunto: 'Prazo exíguo para execução e ausência de mobilização', data: new Date(Date.now() + 86400000 * 3).toISOString().split('T')[0], hora: '15:00', status: DeadlineStatus.PENDING, createdAt: new Date().toISOString() },
      ];
      loadedDeadlines = mock;
      setDeadlines(mock);
    }

    if (savedSettings) {
      const parsed = JSON.parse(savedSettings);
      if (!parsed.responsaveis) parsed.responsaveis = RESPONSAVEL_OPTIONS;
      if (!parsed.pecas) parsed.pecas = PECA_OPTIONS;
      if (!parsed.empresas) {
        parsed.empresas = Array.from(new Set(loadedDeadlines.map(d => d.empresa))).filter(Boolean);
      }
      setSettings(parsed);
    }
  }, []);

  // Set form defaults when settings change
  useEffect(() => {
    if (settings.pecas.length > 0 && !newDeadline.peca) {
      setNewDeadline(prev => ({ ...prev, peca: settings.pecas[0] }));
    }
    if (settings.responsaveis.length > 0 && !newDeadline.responsavel) {
      setNewDeadline(prev => ({ ...prev, responsavel: settings.responsaveis[0] }));
    }
  }, [settings]);

  // AI Extraction Logic
  const handleAiExtract = async () => {
    if (!aiInputText.trim()) return;
    setIsAiProcessing(true);
    const extractedData = await extractDeadlineFromText(aiInputText);
    if (extractedData) {
      setNewDeadline(prev => ({
        ...prev,
        ...extractedData,
        peca: settings.pecas.includes(extractedData.peca) ? extractedData.peca : (prev.peca || settings.pecas[0])
      }));
      setShowAiInput(false);
      setAiInputText('');
    } else {
      alert("Não foi possível extrair os dados.");
    }
    setIsAiProcessing(false);
  };

  const syncWithGoogleSheets = async () => {
    if (!settings.spreadsheetId) {
      alert("Informe o ID da planilha nas configurações.");
      setView('settings');
      return;
    }
    setIsSyncing(true);
    try {
      const url = `https://docs.google.com/spreadsheets/d/${settings.spreadsheetId}/gviz/tq?tqx=out:json`;
      const response = await fetch(url);
      const text = await response.text();
      const start = text.indexOf('{');
      const end = text.lastIndexOf('}');
      const json = JSON.parse(text.substring(start, end + 1));
      const newDeadlines: Deadline[] = json.table.rows
        .filter((row: any) => row.c && row.c[0] && row.c[0].v !== 'PEÇA') 
        .map((row: any, index: number) => {
          const c = row.c;
          return {
            id: `sheet-${index}-${Date.now()}`,
            peca: c[0]?.v || '',
            responsavel: c[1]?.v || '',
            empresa: c[2]?.v?.toString().toUpperCase() || '',
            instituicao: c[3]?.v || '',
            assunto: c[4]?.v || '',
            data: new Date().toISOString().split('T')[0],
            hora: c[6]?.v || '09:00',
            status: DeadlineStatus.PENDING,
            createdAt: new Date().toISOString()
          };
        });
      setDeadlines(newDeadlines);
      setSettings(prev => ({ ...prev, lastSync: new Date().toLocaleString() }));
    } catch (e) {
      alert("Erro ao sincronizar.");
    } finally { setIsSyncing(false); }
  };

  useEffect(() => {
    if (deadlines.length > 0) {
      getLegalInsights(deadlines).then(setInsights);
    }
  }, [deadlines]);

  useEffect(() => {
    localStorage.setItem('juris_deadlines', JSON.stringify(deadlines));
  }, [deadlines]);

  useEffect(() => {
    localStorage.setItem('juris_settings', JSON.stringify(settings));
  }, [settings]);

  const alertData = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const pending = deadlines.filter(d => d.status === DeadlineStatus.PENDING);
    return {
      red: pending.filter(d => d.data === today),
      urgent: pending.filter(d => d.data <= today).length
    };
  }, [deadlines]);

  const stats = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return {
      total: deadlines.length,
      concluidos: deadlines.filter(d => d.status === DeadlineStatus.COMPLETED).length,
      pendentes: deadlines.filter(d => d.status === DeadlineStatus.PENDING && d.data >= today).length,
      atrasados: deadlines.filter(d => d.status === DeadlineStatus.PENDING && d.data < today).length,
    };
  }, [deadlines]);

  const chartData = [
    { name: 'Concluídos', value: stats.concluidos, color: COLORS.success },
    { name: 'Pendentes', value: stats.pendentes, color: COLORS.warning },
    { name: 'Atrasados', value: stats.atrasados, color: COLORS.danger },
  ].filter(d => d.value > 0);

  const upcomingDeadlines = useMemo(() => {
    return deadlines
      .filter(d => d.status === DeadlineStatus.PENDING)
      .sort((a, b) => new Date(a.data).getTime() - new Date(b.data).getTime())
      .slice(0, 5);
  }, [deadlines]);

  const handleAddDeadline = (e: React.FormEvent) => {
    e.preventDefault();
    const deadline: Deadline = {
      ...(newDeadline as Deadline),
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString()
    };
    setDeadlines(prev => [...prev, deadline]);
    setIsModalOpen(false);
  };

  const toggleStatus = (id: string) => {
    setDeadlines(prev => prev.map(d => d.id === id ? { ...d, status: d.status === DeadlineStatus.COMPLETED ? DeadlineStatus.PENDING : DeadlineStatus.COMPLETED } : d));
  };

  const deleteDeadline = (id: string) => {
    if (confirm('Deseja excluir este prazo?')) setDeadlines(prev => prev.filter(d => d.id !== id));
  };

  const addItem = (listKey: 'responsaveis' | 'pecas' | 'empresas', value: string, setter: (v: string) => void) => {
    if (!value.trim()) return;
    const val = value.trim().toUpperCase();
    if (settings[listKey].includes(val)) return alert("Item já cadastrado.");
    setSettings(prev => ({ ...prev, [listKey]: [...prev[listKey], val] }));
    setter('');
  };

  const removeItem = (listKey: 'responsaveis' | 'pecas' | 'empresas', value: string) => {
    if (confirm(`Remover "${value}"?`)) {
      setSettings(prev => ({ ...prev, [listKey]: prev[listKey].filter(v => v !== value) }));
    }
  };

  return (
    <div className="flex bg-slate-50 min-h-screen">
      <Sidebar currentView={view} setView={setView} />

      {/* Alertas lateral */}
      {isNotifOpen && (
        <div className="fixed inset-0 z-50 flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsNotifOpen(false)} />
          <div className="relative w-96 bg-white shadow-2xl p-6 overflow-y-auto animate-in slide-in-from-right duration-300">
            <h2 className="text-xl font-bold mb-6 flex items-center gap-2 text-slate-800"><Icons.Bell /> Alertas Críticos</h2>
            {alertData.red.length > 0 ? (
              <div className="space-y-4">
                {alertData.red.map(d => (
                  <div key={d.id} className="p-4 bg-red-50 border border-red-100 rounded-xl">
                    <p className="font-bold text-red-900">{d.peca}</p>
                    <p className="text-xs text-red-700">{d.empresa} • {d.hora}</p>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-center text-slate-500 py-10">Tudo em dia!</p>
            )}
            <button onClick={() => setIsNotifOpen(false)} className="mt-8 w-full py-3 bg-slate-100 text-slate-600 rounded-xl font-bold hover:bg-slate-200">Fechar</button>
          </div>
        </div>
      )}

      <main className="ml-64 flex-1 p-8">
        <div className="flex justify-between items-start mb-8">
          <div>
            <h2 className="text-3xl font-bold text-slate-800">
              {view === 'dashboard' && 'Visão Geral'}
              {view === 'deadlines' && 'Controle Geral'}
              {view === 'reports' && 'Relatórios'}
              {view === 'settings' && 'Configurações'}
            </h2>
            <p className="text-slate-500 mt-1">Gestão de Prazos • Escritório Digital</p>
          </div>
          <div className="flex gap-4">
            <button onClick={() => setIsNotifOpen(true)} className="p-3 bg-white border border-slate-200 rounded-xl relative hover:bg-slate-50 transition-all shadow-sm">
              <Icons.Bell />
              {alertData.urgent > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[10px] w-5 h-5 flex items-center justify-center rounded-full font-bold animate-bounce">{alertData.urgent}</span>}
            </button>
            <button onClick={() => { setShowAiInput(false); setIsModalOpen(true); }} className="bg-blue-600 text-white px-6 py-3 rounded-xl font-bold flex items-center gap-2 shadow-lg hover:bg-blue-700 transition-all">
              <Icons.Plus /> Novo Prazo
            </button>
          </div>
        </div>

        {/* --- Dashboard View --- */}
        {view === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            {/* IA Insights Section */}
            <div className="bg-white p-6 rounded-2xl border border-blue-100 shadow-sm bg-gradient-to-r from-blue-50/50 to-indigo-50/50">
              <h3 className="text-sm font-bold text-blue-800 flex items-center gap-2 mb-2">
                <Icons.Sparkles /> Panorama Estratégico IA
              </h3>
              <p className="text-slate-700 leading-relaxed italic text-sm">"{insights}"</p>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              {[
                { label: 'Total Geral', val: stats.total, color: 'text-slate-800', bg: 'bg-white' },
                { label: 'Concluídos', val: stats.concluidos, color: 'text-emerald-600', bg: 'bg-emerald-50' },
                { label: 'Pendentes', val: stats.pendentes, color: 'text-amber-600', bg: 'bg-amber-50' },
                { label: 'Atrasados', val: stats.atrasados, color: 'text-red-600', bg: 'bg-red-50' },
              ].map((card, idx) => (
                <div key={idx} className={`${card.bg} p-6 rounded-2xl shadow-sm border border-slate-200/60`}>
                  <p className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">{card.label}</p>
                  <p className={`text-4xl font-bold ${card.color}`}>{card.val}</p>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {/* Pie Chart */}
              <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
                <h3 className="text-lg font-bold mb-6 text-slate-800">Status das Demandas</h3>
                <div className="h-64">
                  {chartData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={chartData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                          {chartData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                        </Pie>
                        <Tooltip />
                        <Legend verticalAlign="bottom" height={36}/>
                      </PieChart>
                    </ResponsiveContainer>
                  ) : (
                    <div className="h-full flex items-center justify-center text-slate-400 italic">Sem dados suficientes</div>
                  )}
                </div>
              </div>

              {/* Upcoming List */}
              <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
                <h3 className="text-lg font-bold mb-6 text-slate-800">Próximos Vencimentos</h3>
                <div className="space-y-4">
                  {upcomingDeadlines.length > 0 ? upcomingDeadlines.map(d => (
                    <div key={d.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-xl border border-slate-100 hover:border-blue-200 transition-colors">
                      <div className="flex items-center gap-3">
                        <div className={`w-2 h-2 rounded-full ${d.data === new Date().toISOString().split('T')[0] ? 'bg-red-600 animate-pulse' : 'bg-blue-600'}`} />
                        <div>
                          <p className="font-semibold text-slate-800 text-sm">{d.peca}</p>
                          <p className="text-[10px] text-slate-500 uppercase font-bold">{d.empresa}</p>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className="font-bold text-blue-600 text-sm">{new Date(d.data).toLocaleDateString('pt-BR')}</p>
                      </div>
                    </div>
                  )) : (
                    <p className="text-center text-slate-400 py-10">Nenhum prazo pendente</p>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* --- List View --- */}
        {view === 'deadlines' && (
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-500">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-800 text-white text-[10px] uppercase font-bold tracking-widest">
                  <tr>
                    <th className="p-6">Peça / Empresa</th>
                    <th className="p-6">Responsável</th>
                    <th className="p-6">Vencimento</th>
                    <th className="p-6">Status</th>
                    <th className="p-6 text-center">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {deadlines.map(d => (
                    <tr key={d.id} className="hover:bg-slate-50 transition-colors group">
                      <td className="p-6">
                        <div className="font-semibold text-slate-800">{d.peca}</div>
                        <div className="text-xs text-slate-400">{d.empresa}</div>
                      </td>
                      <td className="p-6 text-sm text-slate-600">{d.responsavel}</td>
                      <td className="p-6 text-sm">
                        <span className="font-bold text-slate-700">{new Date(d.data).toLocaleDateString('pt-BR')}</span>
                        <div className="text-[10px] text-slate-400 font-bold">{d.hora}</div>
                      </td>
                      <td className="p-6">
                        <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${d.status === DeadlineStatus.COMPLETED ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>
                          {d.status}
                        </span>
                      </td>
                      <td className="p-6">
                        <div className="flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => toggleStatus(d.id)} className="p-2 bg-emerald-50 text-emerald-600 rounded-lg hover:bg-emerald-100"><Icons.Check /></button>
                          <button onClick={() => deleteDeadline(d.id)} className="p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-100"><Icons.Trash /></button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* --- Settings View --- */}
        {view === 'settings' && (
          <div className="max-w-4xl space-y-8 pb-20 animate-in fade-in duration-500">
            {/* Responsáveis */}
            <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
              <h3 className="text-lg font-bold mb-6 flex items-center gap-2"><Icons.List /> Responsáveis</h3>
              <div className="flex gap-2 mb-6">
                <input className="flex-1 border p-3 rounded-xl uppercase focus:ring-2 focus:ring-blue-500 outline-none" value={newRespName} onChange={e => setNewRespName(e.target.value)} placeholder="Novo Responsável..." />
                <button onClick={() => addItem('responsaveis', newRespName, setNewRespName)} className="bg-blue-600 text-white px-6 rounded-xl font-bold">Adicionar</button>
              </div>
              <div className="flex flex-wrap gap-2">
                {settings.responsaveis.map(r => (
                  <span key={r} className="bg-slate-100 px-4 py-2 rounded-xl text-sm font-semibold text-slate-700 flex items-center gap-3">
                    {r} <button onClick={() => removeItem('responsaveis', r)} className="text-red-400 hover:text-red-600">&times;</button>
                  </span>
                ))}
              </div>
            </div>

            {/* Peças */}
            <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
              <h3 className="text-lg font-bold mb-6 flex items-center gap-2"><Icons.Table /> Peças Processuais</h3>
              <div className="flex gap-2 mb-6">
                <input className="flex-1 border p-3 rounded-xl uppercase focus:ring-2 focus:ring-blue-500 outline-none" value={newPecaName} onChange={e => setNewPecaName(e.target.value)} placeholder="Nova Peça..." />
                <button onClick={() => addItem('pecas', newPecaName, setNewPecaName)} className="bg-blue-600 text-white px-6 rounded-xl font-bold">Adicionar</button>
              </div>
              <div className="flex flex-wrap gap-2">
                {settings.pecas.map(p => (
                  <span key={p} className="bg-slate-100 px-4 py-2 rounded-xl text-sm font-semibold text-slate-700 flex items-center gap-3">
                    {p} <button onClick={() => removeItem('pecas', p)} className="text-red-400 hover:text-red-600">&times;</button>
                  </span>
                ))}
              </div>
            </div>

            {/* Empresas */}
            <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
              <h3 className="text-lg font-bold mb-6 flex items-center gap-2"><Icons.Report /> Empresas / Clientes</h3>
              <div className="flex gap-2 mb-6">
                <input className="flex-1 border p-3 rounded-xl uppercase focus:ring-2 focus:ring-blue-500 outline-none" value={newEmpresaName} onChange={e => setNewEmpresaName(e.target.value)} placeholder="Nova Empresa..." />
                <button onClick={() => addItem('empresas', newEmpresaName, setNewEmpresaName)} className="bg-blue-600 text-white px-6 rounded-xl font-bold">Adicionar</button>
              </div>
              <div className="flex flex-wrap gap-2">
                {settings.empresas.map(e => (
                  <span key={e} className="bg-slate-100 px-4 py-2 rounded-xl text-sm font-semibold text-slate-700 flex items-center gap-3">
                    {e} <button onClick={() => removeItem('empresas', e)} className="text-red-400 hover:text-red-600">&times;</button>
                  </span>
                ))}
              </div>
            </div>

            {/* Sheets */}
            <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm">
              <h3 className="text-lg font-bold mb-4">Google Sheets</h3>
              <input className="w-full border p-3 rounded-xl mb-4" placeholder="ID da Planilha" value={settings.spreadsheetId} onChange={e => setSettings(prev => ({ ...prev, spreadsheetId: e.target.value }))} />
              <button onClick={syncWithGoogleSheets} className="bg-blue-600 text-white px-8 py-3 rounded-xl font-bold">Sincronizar Planilha</button>
            </div>
          </div>
        )}

        {/* --- Modal Cadastro --- */}
        <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Novo Prazo Processual">
          <div className="mb-6">
            <button onClick={() => setShowAiInput(!showAiInput)} className="text-blue-600 text-xs font-black flex items-center gap-2 bg-blue-50 px-4 py-2 rounded-full uppercase tracking-widest"><Icons.Sparkles /> {showAiInput ? 'Ocultar Assistente' : 'Preencher com IA'}</button>
            {showAiInput && (
              <div className="mt-4 p-4 bg-blue-50/50 rounded-2xl border border-blue-100 animate-in zoom-in-95">
                <textarea className="w-full p-4 text-sm rounded-xl border bg-white min-h-[120px]" placeholder="Cole o corpo do e-mail ou mensagem aqui..." value={aiInputText} onChange={e => setAiInputText(e.target.value)} />
                <div className="flex justify-end mt-4">
                  <button onClick={handleAiExtract} disabled={isAiProcessing} className="bg-blue-600 text-white text-xs px-6 py-2 rounded-lg font-bold">{isAiProcessing ? 'Extraindo...' : 'Processar Texto'}</button>
                </div>
              </div>
            )}
          </div>
          <form onSubmit={handleAddDeadline} className="grid grid-cols-2 gap-6">
            <div>
              <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Peça Jurídica</label>
              <select className="w-full border p-3 rounded-xl bg-slate-50" value={newDeadline.peca} onChange={e => setNewDeadline(prev => ({ ...prev, peca: e.target.value }))} required>
                {settings.pecas.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Responsável</label>
              <select className="w-full border p-3 rounded-xl bg-slate-50" value={newDeadline.responsavel} onChange={e => setNewDeadline(prev => ({ ...prev, responsavel: e.target.value }))} required>
                {settings.responsaveis.map(r => <option key={r} value={r}>{r}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Empresa Cliente</label>
              <select className="w-full border p-3 rounded-xl bg-slate-50" value={newDeadline.empresa} onChange={e => setNewDeadline(prev => ({ ...prev, empresa: e.target.value }))} required>
                <option value="">Selecione...</option>
                {settings.empresas.map(e => <option key={e} value={e}>{e}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Data Vencimento</label>
              <input type="date" className="w-full border p-3 rounded-xl bg-slate-50" value={newDeadline.data} onChange={e => setNewDeadline(prev => ({ ...prev, data: e.target.value }))} required />
            </div>
            <div className="col-span-2">
              <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Assunto / Descrição</label>
              <textarea className="w-full border p-3 rounded-xl bg-slate-50 min-h-[100px]" value={newDeadline.assunto} onChange={e => setNewDeadline(prev => ({ ...prev, assunto: e.target.value }))} required />
            </div>
            <div className="col-span-2 flex justify-end gap-4 mt-6">
              <button type="button" onClick={() => setIsModalOpen(false)} className="px-6 py-2 text-slate-400 font-bold">Cancelar</button>
              <button type="submit" className="px-10 py-3 bg-blue-600 text-white rounded-xl font-bold shadow-xl hover:bg-blue-700 transition-all">Salvar Prazo</button>
            </div>
          </form>
        </Modal>
      </main>
    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Deadline, 
  DeadlineStatus,
  NotificationSettings
} from './types';
import { 
  Icons, 
  COLORS, 
  PECA_OPTIONS, 
  RESPONSAVEL_OPTIONS 
} from './constants';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer, 
  PieChart, 
  Pie, 
  Cell 
} from 'recharts';
import { getLegalInsights, extractDeadlineFromText } from './services/geminiService';

// --- Components ---

const Sidebar = ({ currentView, setView }: { currentView: string, setView: (v: string) => void }) => (
  <aside className="w-64 bg-slate-900 text-white min-h-screen flex flex-col fixed left-0 top-0 z-40 shadow-xl">
    <div className="p-8">
      <h1 className="text-2xl font-black flex items-center gap-2 tracking-tighter">
        <span className="bg-blue-600 px-2 py-0.5 rounded text-white shadow-lg shadow-blue-500/20 text-lg">JC</span> JurisControl
      </h1>
    </div>
    <nav className="flex-1 px-4 mt-2 space-y-1">
      <button 
        onClick={() => setView('dashboard')}
        className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-xl transition-all duration-200 ${currentView === 'dashboard' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
      >
        <Icons.Dashboard /> <span className="font-semibold">Dashboard</span>
      </button>
      <button 
        onClick={() => setView('deadlines')}
        className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-xl transition-all duration-200 ${currentView === 'deadlines' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
      >
        <Icons.List /> <span className="font-semibold">Controle Geral</span>
      </button>
      <button 
        onClick={() => setView('reports')}
        className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-xl transition-all duration-200 ${currentView === 'reports' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
      >
        <Icons.Report /> <span className="font-semibold">Relatórios</span>
      </button>
      <div className="pt-6 pb-2 px-4">
        <p className="text-[10px] uppercase font-black text-slate-500 tracking-[0.2em]">Configuração</p>
      </div>
      <button 
        onClick={() => setView('settings')}
        className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-xl transition-all duration-200 ${currentView === 'settings' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
      >
        <Icons.Settings /> <span className="font-semibold">Gestão de Itens</span>
      </button>
    </nav>
    <div className="p-6 text-[10px] font-bold text-slate-600 uppercase tracking-widest border-t border-slate-800/50">
      JurisControl v1.0.2
    </div>
  </aside>
);

const Modal = ({ isOpen, onClose, title, children }: { isOpen: boolean, onClose: () => void, title: string, children?: React.ReactNode }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-3xl w-full max-w-2xl shadow-2xl animate-in zoom-in-95 duration-300 overflow-hidden">
        <div className="p-8 border-b flex justify-between items-center bg-slate-50/50">
          <h2 className="text-2xl font-bold text-slate-800">{title}</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-full transition-colors text-slate-400">&times;</button>
        </div>
        <div className="p-8 max-h-[80vh] overflow-y-auto">
          {children}
        </div>
      </div>
    </div>
  );
};

// --- Main App ---

export default function App() {
  const [view, setView] = useState('dashboard');
  const [deadlines, setDeadlines] = useState<Deadline[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isNotifOpen, setIsNotifOpen] = useState(false);
  const [insights, setInsights] = useState<string>('Analisando prazos com Inteligência Artificial...');
  const [isSyncing, setIsSyncing] = useState(false);

  const [aiInputText, setAiInputText] = useState('');
  const [isAiProcessing, setIsAiProcessing] = useState(false);
  const [showAiInput, setShowAiInput] = useState(false);

  const [settings, setSettings] = useState<NotificationSettings>({
    greenAlertDays: 5,
    enableBrowserNotifications: true,
    quietMode: false,
    spreadsheetId: '',
    responsaveis: RESPONSAVEL_OPTIONS,
    pecas: PECA_OPTIONS,
    empresas: []
  });

  const [newRespName, setNewRespName] = useState('');
  const [newPecaName, setNewPecaName] = useState('');
  const [newEmpresaName, setNewEmpresaName] = useState('');

  const [newDeadline, setNewDeadline] = useState<Partial<Deadline>>({
    peca: '',
    responsavel: '',
    empresa: '',
    instituicao: '',
    assunto: '',
    data: new Date().toISOString().split('T')[0],
    hora: '09:00',
    status: DeadlineStatus.PENDING
  });

  // Filters for Reports
  const [selectedCompany, setSelectedCompany] = useState('Todas');
  const [selectedResponsible, setSelectedResponsible] = useState('Todos');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });

  useEffect(() => {
    const saved = localStorage.getItem('juris_deadlines');
    const savedSettings = localStorage.getItem('juris_settings');

    let loadedDeadlines: Deadline[] = [];
    if (saved) {
      loadedDeadlines = JSON.parse(saved);
      setDeadlines(loadedDeadlines);
    } else {
      const mock: Deadline[] = [
        { id: '1', peca: 'Parecer Jurídico', responsavel: 'EDUARDO', empresa: 'SOUL', instituicao: 'Bom Jesus dos Perdões/SP', assunto: 'Rescisão contratual e violação ao devido processo legal', data: new Date().toISOString().split('T')[0], hora: '14:00', status: DeadlineStatus.COMPLETED, createdAt: new Date().toISOString() },
        { id: '2', peca: 'Mandado de Segurança', responsavel: 'EDUARDO', empresa: 'SOUL', instituicao: 'Bom Jesus dos Perdões/SP', assunto: 'Rescisão contratual e violação ao devido processo legal', data: new Date(Date.now() + 86400000).toISOString().split('T')[0], hora: '10:00', status: DeadlineStatus.PENDING, createdAt: new Date().toISOString() },
        { id: '3', peca: 'Exceção de Pré-Executividade', responsavel: 'DANILO', empresa: 'SOUL', instituicao: 'Dois Córregos/SP', assunto: 'Prazo exíguo para execução e ausência de mobilização', data: new Date(Date.now() + 86400000 * 3).toISOString().split('T')[0], hora: '15:00', status: DeadlineStatus.PENDING, createdAt: new Date().toISOString() },
      ];
      loadedDeadlines = mock;
      setDeadlines(mock);
    }

    if (savedSettings) {
      const parsed = JSON.parse(savedSettings);
      if (!parsed.responsaveis) parsed.responsaveis = RESPONSAVEL_OPTIONS;
      if (!parsed.pecas) parsed.pecas = PECA_OPTIONS;
      if (!parsed.empresas) {
        parsed.empresas = Array.from(new Set(loadedDeadlines.map(d => d.empresa))).filter(Boolean);
      }
      setSettings(parsed);
    }
  }, []);

  useEffect(() => {
    if (settings.pecas.length > 0 && !newDeadline.peca) {
      setNewDeadline(prev => ({ ...prev, peca: settings.pecas[0] }));
    }
    if (settings.responsaveis.length > 0 && !newDeadline.responsavel) {
      setNewDeadline(prev => ({ ...prev, responsavel: settings.responsaveis[0] }));
    }
  }, [settings]);

  const handleAiExtract = async () => {
    if (!aiInputText.trim()) return;
    setIsAiProcessing(true);
    const extractedData = await extractDeadlineFromText(aiInputText);
    if (extractedData) {
      setNewDeadline(prev => ({
        ...prev,
        ...extractedData,
        peca: settings.pecas.includes(extractedData.peca) ? extractedData.peca : (prev.peca || settings.pecas[0])
      }));
      setShowAiInput(false);
      setAiInputText('');
    } else {
      alert("Não foi possível extrair os dados.");
    }
    setIsAiProcessing(false);
  };

  const syncWithGoogleSheets = async () => {
    if (!settings.spreadsheetId) {
      alert("Informe o ID da planilha nas configurações.");
      setView('settings');
      return;
    }
    setIsSyncing(true);
    try {
      const url = `https://docs.google.com/spreadsheets/d/${settings.spreadsheetId}/gviz/tq?tqx=out:json`;
      const response = await fetch(url);
      const text = await response.text();
      const start = text.indexOf('{');
      const end = text.lastIndexOf('}');
      const json = JSON.parse(text.substring(start, end + 1));
      const newDeadlines: Deadline[] = json.table.rows
        .filter((row: any) => row.c && row.c[0] && row.c[0].v !== 'PEÇA') 
        .map((row: any, index: number) => {
          const c = row.c;
          return {
            id: `sheet-${index}-${Date.now()}`,
            peca: c[0]?.v || '',
            responsavel: c[1]?.v || '',
            empresa: c[2]?.v?.toString().toUpperCase() || '',
            instituicao: c[3]?.v || '',
            assunto: c[4]?.v || '',
            data: new Date().toISOString().split('T')[0],
            hora: c[6]?.v || '09:00',
            status: DeadlineStatus.PENDING,
            createdAt: new Date().toISOString()
          };
        });
      setDeadlines(newDeadlines);
      setSettings(prev => ({ ...prev, lastSync: new Date().toLocaleString() }));
    } catch (e) {
      alert("Erro ao sincronizar.");
    } finally { setIsSyncing(false); }
  };

  useEffect(() => {
    if (deadlines.length > 0) {
      getLegalInsights(deadlines).then(setInsights);
    }
  }, [deadlines]);

  useEffect(() => {
    localStorage.setItem('juris_deadlines', JSON.stringify(deadlines));
  }, [deadlines]);

  useEffect(() => {
    localStorage.setItem('juris_settings', JSON.stringify(settings));
  }, [settings]);

  const alertData = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const pending = deadlines.filter(d => d.status === DeadlineStatus.PENDING);
    return {
      red: pending.filter(d => d.data === today),
      urgent: pending.filter(d => d.data <= today).length
    };
  }, [deadlines]);

  const stats = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return {
      total: deadlines.length,
      concluidos: deadlines.filter(d => d.status === DeadlineStatus.COMPLETED).length,
      pendentes: deadlines.filter(d => d.status === DeadlineStatus.PENDING && d.data >= today).length,
      atrasados: deadlines.filter(d => d.status === DeadlineStatus.PENDING && d.data < today).length,
    };
  }, [deadlines]);

  const chartData = [
    { name: 'Concluídos', value: stats.concluidos, color: COLORS.success },
    { name: 'Pendentes', value: stats.pendentes, color: COLORS.warning },
    { name: 'Atrasados', value: stats.atrasados, color: COLORS.danger },
  ].filter(d => d.value > 0);

  const upcomingDeadlines = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return deadlines
      .filter(d => d.status === DeadlineStatus.PENDING)
      .sort((a, b) => new Date(a.data).getTime() - new Date(b.data).getTime())
      .slice(0, 5);
  }, [deadlines]);

  const filteredDeadlines = useMemo(() => {
    return deadlines.filter(d => {
      const matchCompany = selectedCompany === 'Todas' || d.empresa === selectedCompany;
      const matchResponsible = selectedResponsible === 'Todos' || d.responsavel === selectedResponsible;
      const matchStart = !dateRange.start || d.data >= dateRange.start;
      const matchEnd = !dateRange.end || d.data <= dateRange.end;
      return matchCompany && matchResponsible && matchStart && matchEnd;
    });
  }, [deadlines, selectedCompany, selectedResponsible, dateRange]);

  const reportStats = useMemo(() => ({
    total: filteredDeadlines.length,
    concluidos: filteredDeadlines.filter(d => d.status === DeadlineStatus.COMPLETED).length,
    pendentes: filteredDeadlines.filter(d => d.status === DeadlineStatus.PENDING).length,
  }), [filteredDeadlines]);

  const handleAddDeadline = (e: React.FormEvent) => {
    e.preventDefault();
    const deadline: Deadline = {
      ...(newDeadline as Deadline),
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString()
    };
    setDeadlines(prev => [...prev, deadline]);
    setIsModalOpen(false);
  };

  const toggleStatus = (id: string) => {
    setDeadlines(prev => prev.map(d => d.id === id ? { ...d, status: d.status === DeadlineStatus.COMPLETED ? DeadlineStatus.PENDING : DeadlineStatus.COMPLETED } : d));
  };

  const deleteDeadline = (id: string) => {
    if (confirm('Deseja excluir este prazo?')) setDeadlines(prev => prev.filter(d => d.id !== id));
  };

  const addItem = (listKey: 'responsaveis' | 'pecas' | 'empresas', value: string, setter: (v: string) => void) => {
    if (!value.trim()) return;
    const val = value.trim().toUpperCase();
    if (settings[listKey].includes(val)) return alert("Item já cadastrado.");
    setSettings(prev => ({ ...prev, [listKey]: [...prev[listKey], val] }));
    setter('');
  };

  const removeItem = (listKey: 'responsaveis' | 'pecas' | 'empresas', value: string) => {
    if (confirm(`Remover "${value}" da lista?`)) {
      setSettings(prev => ({ ...prev, [listKey]: prev[listKey].filter(v => v !== value) }));
    }
  };

  return (
    <div className="flex bg-slate-50 min-h-screen text-slate-800 antialiased">
      <Sidebar currentView={view} setView={setView} />

      {/* Alertas lateral */}
      {isNotifOpen && (
        <div className="fixed inset-0 z-50 flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsNotifOpen(false)} />
          <div className="relative w-96 bg-white shadow-2xl p-8 overflow-y-auto animate-in slide-in-from-right duration-300 rounded-l-3xl">
            <h2 className="text-2xl font-black mb-8 flex items-center gap-3 text-slate-800 tracking-tighter"><Icons.Bell /> Alertas Críticos</h2>
            {alertData.red.length > 0 ? (
              <div className="space-y-4">
                {alertData.red.map(d => (
                  <div key={d.id} className="p-5 bg-red-50 border border-red-100 rounded-2xl shadow-sm">
                    <p className="font-bold text-red-900 leading-tight mb-1">{d.peca}</p>
                    <p className="text-[10px] font-black text-red-600 uppercase tracking-widest">{d.empresa} • {d.hora}</p>
                    <p className="text-xs text-red-700 mt-2 line-clamp-2">{d.assunto}</p>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-20">
                <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-400"><Icons.Check /></div>
                <p className="text-slate-500 font-bold">Tudo em dia!</p>
                <p className="text-xs text-slate-400 mt-1">Nenhum prazo vence hoje.</p>
              </div>
            )}
            <button onClick={() => setIsNotifOpen(false)} className="mt-8 w-full py-4 bg-slate-900 text-white rounded-2xl font-bold hover:bg-slate-800 transition-all shadow-lg">Fechar</button>
          </div>
        </div>
      )}

      <main className="ml-64 flex-1 p-10">
        <div className="flex justify-between items-start mb-10">
          <div>
            <h2 className="text-4xl font-black text-slate-900 tracking-tighter">
              {view === 'dashboard' && 'Visão Geral'}
              {view === 'deadlines' && 'Controle Geral'}
              {view === 'reports' && 'Relatórios Dinâmicos'}
              {view === 'settings' && 'Gestão de Sistema'}
            </h2>
            <p className="text-slate-500 font-medium mt-1">
              {view === 'dashboard' && 'Métricas e análise de inteligência artificial.'}
              {view === 'deadlines' && 'Acompanhamento detalhado de todos os prazos.'}
              {view === 'reports' && 'Filtros avançados e produtividade.'}
              {view === 'settings' && 'Personalize seus responsáveis, peças e empresas.'}
            </p>
          </div>
          <div className="flex gap-4">
            <button onClick={() => setIsNotifOpen(true)} className="p-4 bg-white border border-slate-200 rounded-2xl relative hover:bg-slate-50 transition-all shadow-sm group">
              <div className="group-hover:scale-110 transition-transform"><Icons.Bell /></div>
              {alertData.urgent > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[10px] w-6 h-6 flex items-center justify-center rounded-full font-black animate-bounce ring-4 ring-slate-50">{alertData.urgent}</span>}
            </button>
            <button onClick={() => { setShowAiInput(false); setIsModalOpen(true); }} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black flex items-center gap-3 shadow-xl shadow-blue-500/20 hover:bg-blue-700 transition-all hover:-translate-y-1 active:translate-y-0">
              <Icons.Plus /> Novo Prazo
            </button>
          </div>
        </div>

        {/* --- Dashboard View --- */}
        {view === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="bg-white p-8 rounded-3xl border border-blue-100 shadow-sm bg-gradient-to-r from-blue-50/50 to-indigo-50/50 relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                 <Icons.Sparkles />
              </div>
              <h3 className="text-xs font-black text-blue-600 uppercase tracking-[0.2em] flex items-center gap-2 mb-3">
                <Icons.Sparkles /> Panorama Estratégico IA
              </h3>
              <p className="text-slate-800 leading-relaxed font-medium italic">"{insights}"</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              {[
                { label: 'Total Geral', val: stats.total, color: 'text-slate-900', bg: 'bg-white' },
                { label: 'Concluídos', val: stats.concluidos, color: 'text-emerald-600', bg: 'bg-emerald-50/50' },
                { label: 'Pendentes', val: stats.pendentes, color: 'text-amber-600', bg: 'bg-amber-50/50' },
                { label: 'Atrasados', val: stats.atrasados, color: 'text-red-600', bg: 'bg-red-50/50' },
              ].map((card, idx) => (
                <div key={idx} className={`${card.bg} p-8 rounded-3xl shadow-sm border border-slate-200/60 transition-all hover:shadow-md`}>
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">{card.label}</p>
                  <p className={`text-5xl font-black tracking-tighter ${card.color}`}>{card.val}</p>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              <div className="bg-white p-10 rounded-3xl border border-slate-200 shadow-sm">
                <h3 className="text-xl font-black mb-8 text-slate-900 tracking-tight">Status das Demandas</h3>
                <div className="h-72">
                  {chartData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={chartData} cx="50%" cy="50%" innerRadius={70} outerRadius={95} paddingAngle={8} dataKey="value" stroke="none">
                          {chartData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                        </Pie>
                        <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                        <Legend verticalAlign="bottom" height={36} iconType="circle"/>
                      </PieChart>
                    </ResponsiveContainer>
                  ) : (
                    <div className="h-full flex items-center justify-center text-slate-400 italic">Sem dados registrados</div>
                  )}
                </div>
              </div>

              <div className="bg-white p-10 rounded-3xl border border-slate-200 shadow-sm">
                <h3 className="text-xl font-black mb-8 text-slate-900 tracking-tight">Próximos Vencimentos</h3>
                <div className="space-y-4">
                  {upcomingDeadlines.length > 0 ? upcomingDeadlines.map(d => (
                    <div key={d.id} className="flex items-center justify-between p-5 bg-slate-50/50 rounded-2xl border border-slate-100 hover:border-blue-200 transition-all hover:shadow-sm">
                      <div className="flex items-center gap-4">
                        <div className={`w-3 h-3 rounded-full ${d.data === new Date().toISOString().split('T')[0] ? 'bg-red-600 animate-pulse' : 'bg-blue-600'}`} />
                        <div>
                          <p className="font-bold text-slate-900 leading-tight">{d.peca}</p>
                          <p className="text-[10px] text-slate-500 uppercase font-black tracking-wider mt-0.5">{d.empresa}</p>
                        </div>
                      </div>
                      <div className="text-right">
                        <p className="font-black text-blue-600 tracking-tight">{new Date(d.data).toLocaleDateString('pt-BR')}</p>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">{d.hora}</p>
                      </div>
                    </div>
                  )) : (
                    <div className="py-20 text-center text-slate-400 italic font-medium">Nenhum prazo pendente</div>
                  )}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* --- List View --- */}
        {view === 'deadlines' && (
          <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-500">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-900 text-white text-[10px] uppercase font-black tracking-[0.2em]">
                  <tr>
                    <th className="px-8 py-6">Peça / Empresa</th>
                    <th className="px-8 py-6">Responsável</th>
                    <th className="px-8 py-6">Vencimento</th>
                    <th className="px-8 py-6">Status</th>
                    <th className="px-8 py-6 text-center">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {deadlines.length > 0 ? deadlines.map(d => (
                    <tr key={d.id} className="hover:bg-slate-50/50 transition-colors group">
                      <td className="px-8 py-6">
                        <div className="font-bold text-slate-900 leading-tight mb-1">{d.peca}</div>
                        <div className="text-[10px] text-slate-400 font-black uppercase tracking-widest">{d.empresa}</div>
                      </td>
                      <td className="px-8 py-6">
                        <span className="px-3 py-1.5 bg-slate-100 rounded-lg text-xs font-bold text-slate-700">{d.responsavel}</span>
                      </td>
                      <td className="px-8 py-6">
                        <div className="font-black text-slate-900 tracking-tight">{new Date(d.data).toLocaleDateString('pt-BR')}</div>
                        <div className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{d.hora}</div>
                      </td>
                      <td className="px-8 py-6">
                        <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${d.status === DeadlineStatus.COMPLETED ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>
                          {d.status}
                        </span>
                      </td>
                      <td className="px-8 py-6">
                        <div className="flex justify-center gap-3 opacity-0 group-hover:opacity-100 transition-all translate-x-2 group-hover:translate-x-0">
                          <button onClick={() => toggleStatus(d.id)} className="p-3 bg-emerald-50 text-emerald-600 rounded-xl hover:bg-emerald-100 shadow-sm transition-all"><Icons.Check /></button>
                          <button onClick={() => deleteDeadline(d.id)} className="p-3 bg-red-50 text-red-600 rounded-xl hover:bg-red-100 shadow-sm transition-all"><Icons.Trash /></button>
                        </div>
                      </td>
                    </tr>
                  )) : (
