            </div>
            <a href="https://ai.google.dev/" target="_blank" rel="noreferrer" className="text-xs font-black text-amber-700 uppercase tracking-widest hover:underline">Obter Chave</a>
          </div>
        )}

        <div className="flex justify-between items-start mb-10">
          <div>
            <h2 className="text-4xl font-black text-slate-900 tracking-tighter">
