export enum DeadlineStatus {
  PENDING = 'PENDENTE',
  COMPLETED = 'CONCLUÍDO',
  OVERDUE = 'ATRASADO'
}

export interface Deadline {
  id: string;
  peca: string;
  responsavel: string;
  empresa: string;
  instituicao: string;
  assunto: string;
  data: string;
  hora: string;
  status: DeadlineStatus;
  createdAt: string;
}

export interface NotificationSettings {
  greenAlertDays: number;
  yellowAlertDays: number; // Geralmente 1 (amanhã)
  enableBrowserNotifications: boolean;
  notificationFrequency: 'always' | 'daily' | 'hourly';
  quietMode: boolean;
  responsaveis: string[];
  pecas: string[];
  empresas: string[];
}

export interface ReportStats {
  total: number;
  concluidos: number;
  pendentes: number;
  atrasados: number;
}

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Deadline, 
  DeadlineStatus,
  NotificationSettings
} from './types';
import { 
  Icons, 
  COLORS, 
  PECA_OPTIONS, 
  RESPONSAVEL_OPTIONS 
} from './constants';
import { 
  ResponsiveContainer, 
  PieChart, 
  Pie, 
  Cell,
  Tooltip,
  Legend
} from 'recharts';

// --- Utilitários de Data ---
const getDaysDiff = (dateStr: string) => {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const deadlineDate = new Date(dateStr);
  deadlineDate.setHours(0, 0, 0, 0);
  const diffTime = deadlineDate.getTime() - today.getTime();
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const getAlertLevel = (dateStr: string, status: DeadlineStatus, greenDays: number) => {
  if (status === DeadlineStatus.COMPLETED) return 'safe';
  const diff = getDaysDiff(dateStr);
  if (diff < 0) return 'overdue';
  if (diff === 0) return 'critical'; // Vermelho
  if (diff === 1) return 'urgent';   // Amarelo
  if (diff <= greenDays) return 'warning'; // Verde
  return 'safe';
};

// --- Subcomponentes ---

const Sidebar = ({ currentView, setView }: { currentView: string, setView: (v: string) => void }) => {
  return (
    <aside className="w-64 bg-slate-900 text-white min-h-screen flex flex-col fixed left-0 top-0 z-40 shadow-xl">
      <div className="p-8 text-center">
        <h1 className="text-2xl font-black flex items-center justify-center gap-2 tracking-tighter">
          <span className="bg-blue-600 px-2 py-0.5 rounded text-white shadow-lg shadow-blue-500/20 text-lg">JC</span> JurisControl
        </h1>
      </div>
      <nav className="flex-1 px-4 mt-2 space-y-1">
        <button 
          onClick={() => setView('dashboard')}
          className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-xl transition-all duration-200 ${currentView === 'dashboard' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
        >
          <Icons.Dashboard /> <span className="font-semibold text-sm">Dashboard</span>
        </button>
        <button 
          onClick={() => setView('deadlines')}
          className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-xl transition-all duration-200 ${currentView === 'deadlines' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
        >
          <Icons.List /> <span className="font-semibold text-sm">Controle Geral</span>
        </button>
        <button 
          onClick={() => setView('settings')}
          className={`w-full flex items-center gap-3 px-4 py-3.5 rounded-xl transition-all duration-200 ${currentView === 'settings' ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white'}`}
        >
          <Icons.Settings /> <span className="font-semibold text-sm">Gestão</span>
        </button>
      </nav>
      <div className="p-6 border-t border-slate-800/50">
        <div className="text-[9px] font-bold text-slate-600 uppercase tracking-widest">
          v1.2.0 - Alert System
        </div>
      </div>
    </aside>
  );
};

const Modal = ({ isOpen, onClose, title, children }: { isOpen: boolean, onClose: () => void, title: string, children?: React.ReactNode }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-3xl w-full max-w-2xl shadow-2xl animate-in zoom-in-95 duration-300 overflow-hidden">
        <div className="p-8 border-b flex justify-between items-center bg-slate-50/50">
          <h2 className="text-2xl font-bold text-slate-800">{title}</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-200 rounded-full transition-colors text-slate-400">&times;</button>
        </div>
        <div className="p-8 max-h-[80vh] overflow-y-auto">
          {children}
        </div>
      </div>
    </div>
  );
};

export default function App() {
  const [view, setView] = useState('dashboard');
  const [deadlines, setDeadlines] = useState<Deadline[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);

  const [settings, setSettings] = useState<NotificationSettings>({
    greenAlertDays: 5,
    yellowAlertDays: 1,
    enableBrowserNotifications: true,
    notificationFrequency: 'always',
    quietMode: false,
    responsaveis: RESPONSAVEL_OPTIONS,
    pecas: PECA_OPTIONS,
    empresas: []
  });

  const [newDeadline, setNewDeadline] = useState<Partial<Deadline>>({
    peca: '',
    responsavel: '',
    empresa: '',
    assunto: '',
    data: new Date().toISOString().split('T')[0],
    status: DeadlineStatus.PENDING
  });

  useEffect(() => {
    const savedD = localStorage.getItem('juris_deadlines');
    const savedS = localStorage.getItem('juris_settings');
    if (savedD) setDeadlines(JSON.parse(savedD));
    if (savedS) setSettings(JSON.parse(savedS));

    // Pedir permissão de notificações
    if ("Notification" in window && Notification.permission === "default") {
      Notification.requestPermission();
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('juris_deadlines', JSON.stringify(deadlines));
  }, [deadlines]);

  useEffect(() => {
    localStorage.setItem('juris_settings', JSON.stringify(settings));
  }, [settings]);

  // Lógica de Notificações Externas
  useEffect(() => {
    if (settings.enableBrowserNotifications && Notification.permission === "granted") {
      const urgentDeadlines = deadlines.filter(d => 
        d.status === DeadlineStatus.PENDING && 
        (getDaysDiff(d.data) === 0 || getDaysDiff(d.data) === 1)
      );

      if (urgentDeadlines.length > 0) {
        new Notification("JurisControl: Prazos Críticos", {
          body: `Você possui ${urgentDeadlines.length} prazos vencendo hoje ou amanhã.`,
          icon: "https://cdn-icons-png.flaticon.com/512/564/564619.png"
        });
      }
    }
  }, [deadlines.length]);

  const handleAddDeadline = (e: React.FormEvent) => {
    e.preventDefault();
    const deadline: Deadline = {
      ...(newDeadline as Deadline),
      id: Math.random().toString(36).substring(2, 11),
      createdAt: new Date().toISOString()
    };
    setDeadlines(prev => [...prev, deadline]);
    setIsModalOpen(false);
    setNewDeadline(prev => ({ ...prev, assunto: '' }));
  };

  const stats = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return {
      total: deadlines.length,
      concluidos: deadlines.filter(d => d.status === DeadlineStatus.COMPLETED).length,
      pendentes: deadlines.filter(d => d.status === DeadlineStatus.PENDING && d.data >= today).length,
      atrasados: deadlines.filter(d => d.status === DeadlineStatus.PENDING && d.data < today).length,
    };
  }, [deadlines]);

  const urgentList = useMemo(() => {
    return deadlines
      .filter(d => d.status === DeadlineStatus.PENDING)
      .sort((a, b) => new Date(a.data).getTime() - new Date(b.data).getTime())
      .slice(0, 5);
  }, [deadlines]);

  const chartData = [
    { name: 'Concluídos', value: stats.concluidos, color: COLORS.success },
    { name: 'Pendentes', value: stats.pendentes, color: COLORS.warning },
    { name: 'Atrasados', value: stats.atrasados, color: COLORS.danger },
  ].filter(d => d.value > 0);

  const addItem = (key: 'responsaveis' | 'empresas', value: string) => {
    const val = value.trim().toUpperCase();
    if (!val || settings[key].includes(val)) return;
    setSettings(prev => ({ ...prev, [key]: [...prev[key], val] }));
  };

  return (
    <div className="flex bg-slate-50 min-h-screen text-slate-800 antialiased">
      <Sidebar currentView={view} setView={setView} />

      <main className="ml-64 flex-1 p-10 relative">
        {/* Header Superior com Alertas */}
        <div className="flex justify-between items-center mb-10">
          <div>
            <h2 className="text-4xl font-black text-slate-900 tracking-tighter">
              {view === 'dashboard' && 'Escritório'}
              {view === 'deadlines' && 'Prazos Ativos'}
              {view === 'settings' && 'Configurações'}
            </h2>
            <p className="text-slate-500 font-medium mt-1">Gestão de Prazos e Alertas</p>
          </div>

          <div className="flex items-center gap-6">
            {/* Botão de Notificações */}
            <div className="relative">
              <button 
                onClick={() => setShowNotifications(!showNotifications)}
                className={`p-3 rounded-2xl bg-white border border-slate-200 shadow-sm transition-all hover:bg-slate-50 relative ${stats.atrasados + deadlines.filter(d => d.status === DeadlineStatus.PENDING && getDaysDiff(d.data) <= 1).length > 0 ? 'animate-bounce' : ''}`}
              >
                <Icons.Bell />
                {(stats.atrasados > 0 || urgentList.length > 0) && (
                  <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-600 text-white text-[10px] font-black rounded-full flex items-center justify-center shadow-lg">
                    {deadlines.filter(d => d.status === DeadlineStatus.PENDING && getDaysDiff(d.data) <= settings.greenAlertDays).length}
                  </span>
                )}
              </button>

              {showNotifications && (
                <div className="absolute right-0 mt-4 w-80 bg-white rounded-3xl shadow-2xl border border-slate-100 z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                  <div className="p-5 border-b bg-slate-50 flex justify-between items-center">
                    <h4 className="font-black text-xs uppercase tracking-widest text-slate-500">Alertas Próximos</h4>
                    <button onClick={() => setShowNotifications(false)} className="text-slate-400 hover:text-slate-600">&times;</button>
                  </div>
                  <div className="max-h-96 overflow-y-auto">
                    {urgentList.length > 0 ? urgentList.map(u => {
                      const level = getAlertLevel(u.data, u.status, settings.greenAlertDays);
                      return (
                        <div key={u.id} className="p-4 border-b hover:bg-slate-50 transition-colors">
                          <div className="flex items-center gap-2 mb-1">
                            <div className={`w-2 h-2 rounded-full ${level === 'critical' ? 'bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.5)]' : level === 'urgent' ? 'bg-amber-500' : 'bg-emerald-500'}`} />
                            <span className="text-[10px] font-black text-slate-400 uppercase">{u.empresa || 'Sem Cliente'}</span>
                          </div>
                          <p className="text-sm font-bold text-slate-800 line-clamp-1">{u.peca}</p>
                          <p className="text-[11px] font-medium text-slate-500 mt-1 flex items-center gap-1">
                            <Icons.Clock /> Vence {getDaysDiff(u.data) === 0 ? 'hoje' : getDaysDiff(u.data) === 1 ? 'amanhã' : `em ${getDaysDiff(u.data)} dias`}
                          </p>
                        </div>
                      );
                    }) : (
                      <div className="p-8 text-center text-slate-400 italic text-sm">Nenhum prazo urgente</div>
                    )}
                  </div>
                </div>
              )}
            </div>

            <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black flex items-center gap-3 shadow-xl shadow-blue-500/20 hover:bg-blue-700 transition-all hover:-translate-y-1">
              <Icons.Plus /> Registrar Prazo
            </button>
          </div>
        </div>

        {view === 'dashboard' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            {/* Cards de Métricas */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
              {[
                { label: 'Carga Total', val: stats.total, color: 'text-slate-900', icon: <Icons.Dashboard /> },
                { label: 'Cumpridos', val: stats.concluidos, color: 'text-emerald-600', icon: <Icons.Check /> },
                { label: 'Em Aberto', val: stats.pendentes, color: 'text-amber-600', icon: <Icons.Clock /> },
                { label: 'Hoje / Vencidos', val: stats.atrasados + deadlines.filter(d => d.status === DeadlineStatus.PENDING && getDaysDiff(d.data) === 0).length, color: 'text-red-600', icon: <Icons.AlertCircle /> },
              ].map((card, idx) => (
                <div key={idx} className="bg-white p-8 rounded-3xl shadow-sm border border-slate-200/60 relative overflow-hidden group">
                  <div className="absolute -right-4 -bottom-4 opacity-5 transform group-hover:scale-110 transition-transform">
                    {card.icon}
                  </div>
                  <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">{card.label}</p>
                  <p className={`text-4xl font-black tracking-tighter ${card.color}`}>{card.val}</p>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
               {/* Lista de Urgência no Dashboard */}
               <div className="lg:col-span-2 bg-white p-10 rounded-3xl border border-slate-200 shadow-sm">
                  <h3 className="text-xl font-black mb-8 text-slate-900 tracking-tight flex items-center gap-2">
                    <Icons.Clock /> Prioridade Máxima
                  </h3>
                  <div className="space-y-4">
                    {urgentList.map(d => {
                      const level = getAlertLevel(d.data, d.status, settings.greenAlertDays);
                      return (
                        <div key={d.id} className={`p-6 rounded-2xl border flex justify-between items-center transition-all hover:translate-x-1 ${level === 'critical' ? 'bg-red-50 border-red-100' : level === 'urgent' ? 'bg-amber-50 border-amber-100' : 'bg-slate-50 border-slate-100'}`}>
                          <div>
                            <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{d.empresa}</span>
                            <h4 className="font-bold text-slate-800 text-lg">{d.peca}</h4>
                            <p className="text-xs text-slate-500 font-medium">Resp: {d.responsavel}</p>
                          </div>
                          <div className="text-right">
                            <span className={`text-[10px] font-black px-4 py-1.5 rounded-full uppercase tracking-widest ${level === 'critical' ? 'bg-red-600 text-white shadow-lg shadow-red-200 animate-pulse' : level === 'urgent' ? 'bg-amber-500 text-white' : 'bg-emerald-500 text-white'}`}>
                              {getDaysDiff(d.data) === 0 ? 'HOJE' : getDaysDiff(d.data) === 1 ? 'AMANHÃ' : `EM ${getDaysDiff(d.data)} DIAS`}
                            </span>
                            <p className="text-xs font-bold text-slate-800 mt-2">{new Date(d.data).toLocaleDateString('pt-BR')}</p>
                          </div>
                        </div>
                      )
                    })}
                    {urgentList.length === 0 && <div className="p-10 text-center text-slate-400 italic font-medium">Nenhuma prioridade registrada</div>}
                  </div>
               </div>

               {/* Gráfico de Operação */}
               <div className="bg-white p-10 rounded-3xl border border-slate-200 shadow-sm">
                  <h3 className="text-xl font-black mb-8 text-slate-900 tracking-tight">Status da Operação</h3>
                  <div className="h-64">
                    {chartData.length > 0 ? (
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={chartData} cx="50%" cy="50%" innerRadius={60} outerRadius={85} paddingAngle={8} dataKey="value" stroke="none">
                            {chartData.map((e, i) => <Cell key={i} fill={e.color} />)}
                          </Pie>
                          <Tooltip contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                        </PieChart>
                      </ResponsiveContainer>
                    ) : (
                      <div className="h-full flex items-center justify-center text-slate-400 italic font-medium">Sem dados</div>
                    )}
                  </div>
                  <div className="mt-4 space-y-2">
                    {chartData.map(c => (
                      <div key={c.name} className="flex justify-between items-center text-xs">
                        <span className="flex items-center gap-2 font-bold text-slate-600"><div className="w-2 h-2 rounded-full" style={{backgroundColor: c.color}}/> {c.name}</span>
                        <span className="font-black">{c.value}</span>
                      </div>
                    ))}
                  </div>
               </div>
            </div>
          </div>
        )}

        {view === 'deadlines' && (
          <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-500">
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-900 text-white text-[10px] uppercase font-black tracking-[0.2em]">
                  <tr>
                    <th className="px-8 py-6">Peça / Empresa</th>
                    <th className="px-8 py-6">Responsável</th>
                    <th className="px-8 py-6">Data de Vencimento</th>
                    <th className="px-8 py-6">Status / Alerta</th>
                    <th className="px-8 py-6 text-center">Gestão</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {deadlines.length > 0 ? deadlines.sort((a,b) => new Date(a.data).getTime() - new Date(b.data).getTime()).map(d => {
                    const level = getAlertLevel(d.data, d.status, settings.greenAlertDays);
                    return (
                      <tr key={d.id} className="hover:bg-slate-50 transition-colors group">
                        <td className="px-8 py-6">
                          <div className="font-bold text-slate-900 leading-tight">{d.peca}</div>
                          <div className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-0.5">{d.empresa}</div>
                        </td>
                        <td className="px-8 py-6">
                          <span className="px-3 py-1 bg-slate-100 rounded-lg text-[10px] font-black text-slate-600 uppercase">{d.responsavel}</span>
                        </td>
                        <td className="px-8 py-6">
                          <div className="flex flex-col">
                            <span className="font-black text-slate-900">{new Date(d.data).toLocaleDateString('pt-BR')}</span>
                            <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">em {getDaysDiff(d.data)} dias</span>
                          </div>
                        </td>
                        <td className="px-8 py-6">
                          <div className="flex items-center gap-2">
                            <span className={`px-4 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${d.status === DeadlineStatus.COMPLETED ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>
                              {d.status}
                            </span>
                            {d.status === DeadlineStatus.PENDING && (
                              <div className={`w-3 h-3 rounded-full ${level === 'critical' ? 'bg-red-500 animate-pulse' : level === 'urgent' ? 'bg-amber-500' : level === 'warning' ? 'bg-emerald-500' : 'bg-slate-200'}`} />
                            )}
                          </div>
                        </td>
                        <td className="px-8 py-6 flex justify-center gap-3">
                           <button onClick={() => {
                             setDeadlines(prev => prev.map(item => item.id === d.id ? { ...item, status: item.status === DeadlineStatus.COMPLETED ? DeadlineStatus.PENDING : DeadlineStatus.COMPLETED } : item));
                           }} title="Concluir" className="p-2 bg-emerald-50 text-emerald-600 rounded-lg hover:bg-emerald-100 transition-all"><Icons.Check /></button>
                           <button onClick={() => {
                             if (confirm("Remover este prazo?")) setDeadlines(prev => prev.filter(item => item.id !== d.id));
                           }} title="Excluir" className="p-2 bg-red-50 text-red-600 rounded-lg hover:bg-red-100 transition-all"><Icons.Trash /></button>
                        </td>
                      </tr>
                    );
                  }) : (
                    <tr><td colSpan={5} className="p-20 text-center text-slate-400 font-bold uppercase tracking-widest italic">Nenhum prazo encontrado</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {view === 'settings' && (
          <div className="max-w-3xl space-y-10 animate-in fade-in duration-500">
            {/* Alertas e Notificações */}
            <div className="bg-white p-10 rounded-3xl border border-slate-200 shadow-sm">
               <h3 className="text-xl font-black mb-8 flex items-center gap-3 tracking-tight text-blue-600"><Icons.Bell /> Alertas & Antecedência</h3>

               <div className="space-y-6">
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase mb-3">Antecedência Alerta Verde (Dias)</label>
                    <div className="flex items-center gap-4">
                      <input 
                        type="range" min="2" max="15" 
                        value={settings.greenAlertDays} 
                        onChange={e => setSettings(p => ({ ...p, greenAlertDays: parseInt(e.target.value) }))}
                        className="flex-1 h-2 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-blue-600"
                      />
                      <span className="font-black text-blue-600 bg-blue-50 px-4 py-2 rounded-xl border border-blue-100">{settings.greenAlertDays} dias</span>
                    </div>
                  </div>

                  <div className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <div>
                      <h4 className="font-bold text-slate-800 text-sm">Notificações no Navegador</h4>
                      <p className="text-[10px] font-medium text-slate-500 uppercase tracking-widest">Alertas externos no sistema operacional</p>
                    </div>
                    <button 
                      onClick={() => setSettings(p => ({ ...p, enableBrowserNotifications: !p.enableBrowserNotifications }))}
                      className={`w-14 h-8 rounded-full transition-all flex items-center p-1 ${settings.enableBrowserNotifications ? 'bg-blue-600 justify-end' : 'bg-slate-300 justify-start'}`}
                    >
                      <div className="w-6 h-6 bg-white rounded-full shadow-md" />
                    </button>
                  </div>
               </div>
            </div>

            <div className="bg-white p-10 rounded-3xl border border-slate-200 shadow-sm">
               <h3 className="text-xl font-black mb-8 flex items-center gap-3 tracking-tight"><Icons.List /> Gestão de Equipe</h3>
               <div className="flex gap-4 mb-6">
                 <input className="flex-1 bg-slate-50 border border-slate-200 p-4 rounded-2xl uppercase font-bold text-xs" id="newResp" placeholder="NOME DO ADVOGADO..." />
                 <button onClick={() => {
                   const el = document.getElementById('newResp') as HTMLInputElement;
                   addItem('responsaveis', el.value);
                   el.value = '';
                 }} className="bg-slate-900 text-white px-8 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-800 transition-all">ADICIONAR</button>
               </div>
               <div className="flex flex-wrap gap-2">
                 {settings.responsaveis.map(r => (
                   <span key={r} className="bg-slate-100 px-4 py-2 rounded-xl text-[10px] font-black text-slate-600 border border-slate-200 uppercase">{r}</span>
                 ))}
               </div>
            </div>

            <div className="bg-red-50 p-10 rounded-3xl border border-red-100">
                <h3 className="text-xl font-black mb-4 flex items-center gap-3 tracking-tight text-red-900"><Icons.Trash /> Reset de Sistema</h3>
                <p className="text-red-700 text-sm mb-6 font-medium">Todos os dados locais serão apagados. A exportação para planilhas não será afetada.</p>
                <button onClick={() => {
                  if(confirm("Deseja realmente apagar TUDO?")) { localStorage.clear(); window.location.reload(); }
                }} className="bg-red-600 text-white px-10 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-red-700 transition-all">
                    Apagar Tudo
                </button>
            </div>
          </div>
        )}

        {/* Modal de Cadastro */}
        <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Novo Prazo Processual">
          <form onSubmit={handleAddDeadline} className="grid grid-cols-2 gap-6">
            <div className="col-span-1">
              <label className="block text-[10px] font-black text-slate-400 uppercase mb-2">Tipo de Peça</label>
              <select className="w-full bg-slate-50 border border-slate-200 p-4 rounded-2xl font-bold text-sm" value={newDeadline.peca} onChange={e => setNewDeadline(p => ({ ...p, peca: e.target.value }))} required>
