          <div>
            <h2 className="text-5xl font-black text-slate-950 tracking-tighter mb-2">
              {view === 'dashboard' && 'Visão Geral'}
              {view === 'deadlines' && 'Prazos Ativos'}
              {view === 'settings' && 'Gerenciamento'}
            </h2>
            <div className="flex items-center gap-2 text-slate-400 font-bold uppercase text-[10px] tracking-[0.2em]">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" /> Escritório Online
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={() => setIsSyncModalOpen(true)}
              className="flex items-center gap-2 px-6 py-4 bg-white border border-slate-200 rounded-2xl shadow-sm text-slate-600 font-bold text-xs hover:bg-slate-50 transition-all"
            >
              <Icons.Sync /> Importar Planilha
            </button>
            <button 
              onClick={() => setIsModalOpen(true)} 
              className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black flex items-center gap-3 shadow-2xl shadow-blue-500/30 hover:bg-blue-700 transition-all hover:-translate-y-1"
            >
              <Icons.Plus /> Registrar Prazo
            </button>
          </div>
        </div>

        {view === 'dashboard' && (
          <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">

            {/* RADAR DE PRAZOS (Alertas Dashboard) */}
            <section>
              <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em] mb-6 flex items-center gap-3">
                <Icons.AlertCircle /> Radar de Prioridades
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                {/* Crítico */}
                <button 
                  onClick={() => setActiveFilter(activeFilter === 'today' ? 'all' : 'today')}
                  className={`relative p-8 rounded-[2.5rem] border-2 transition-all text-left overflow-hidden group ${activeFilter === 'today' ? 'bg-red-600 border-red-500 shadow-2xl shadow-red-200 text-white scale-105' : 'bg-white border-slate-100 hover:border-red-200 shadow-sm text-slate-900'}`}
                >
                  <div className={`absolute top-0 left-0 w-2 h-full ${activeFilter === 'today' ? 'bg-white/20' : 'bg-red-500'}`} />
                  <p className={`text-[10px] font-black uppercase tracking-widest mb-2 ${activeFilter === 'today' ? 'text-white/70' : 'text-slate-400'}`}>Prazos Fatais (Hoje)</p>
                  <div className="flex items-end justify-between">
                    <span className="text-6xl font-black tracking-tighter">{stats.hoje + stats.atrasados}</span>
                    <div className={`p-4 rounded-2xl ${activeFilter === 'today' ? 'bg-white/20' : 'bg-red-50 text-red-500 group-hover:scale-110 transition-transform'}`}>
                      <Icons.Clock />
                    </div>
                  </div>
                  {stats.atrasados > 0 && (
                    <div className={`mt-4 text-[10px] font-black py-1 px-3 rounded-full inline-block ${activeFilter === 'today' ? 'bg-white text-red-600' : 'bg-red-600 text-white'}`}>
                      {stats.atrasados} VENCIDOS
                    </div>
                  )}
                </button>

                {/* Urgente */}
                <button 
                  onClick={() => setActiveFilter(activeFilter === 'tomorrow' ? 'all' : 'tomorrow')}
                  className={`relative p-8 rounded-[2.5rem] border-2 transition-all text-left overflow-hidden group ${activeFilter === 'tomorrow' ? 'bg-amber-500 border-amber-400 shadow-2xl shadow-amber-200 text-white scale-105' : 'bg-white border-slate-100 hover:border-amber-200 shadow-sm text-slate-900'}`}
                >
                  <div className={`absolute top-0 left-0 w-2 h-full ${activeFilter === 'tomorrow' ? 'bg-white/20' : 'bg-amber-500'}`} />
                  <p className={`text-[10px] font-black uppercase tracking-widest mb-2 ${activeFilter === 'tomorrow' ? 'text-white/70' : 'text-slate-400'}`}>Urgência (Amanhã)</p>
                  <div className="flex items-end justify-between">
                    <span className="text-6xl font-black tracking-tighter">{stats.amanha}</span>
