                  <div className="flex items-end justify-between">
                    <span className="text-6xl font-black tracking-tighter">{stats.semana}</span>
                    <div className={`p-4 rounded-2xl ${activeFilter === 'week' ? 'bg-white/20' : 'bg-emerald-50 text-emerald-500 group-hover:scale-110 transition-transform'}`}>
                      <Icons.Check />
