                            <Tooltip contentStyle={{ backgroundColor: '#020617', border: 'none', borderRadius: '20px', color: '#fff', fontSize: '12px', fontWeight: 'bold' }} />
                          </PieChart>
                        </ResponsiveContainer>
                      ) : (
                        <div className="h-full flex items-center justify-center text-slate-700 font-bold uppercase text-xs">Sem Dados</div>
                      )}
                    </div>
                    <div className="mt-8 grid grid-cols-1 gap-3">
                      {chartData.map(c => (
                        <div key={c.name} className="flex justify-between items-center bg-white/5 p-4 rounded-2xl border border-white/5">
