            </button>
            <button 
              onClick={() => setIsModalOpen(true)} 
              className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black flex items-center gap-3 shadow-2xl shadow-blue-500/30 hover:bg-blue-700 transition-all hover:-translate-y-1"
