// --- Utilitários de Data Corrigidos para Local Time ---

/**
 * Converte string YYYY-MM-DD para objeto Date local evitando shift de fuso horário
 */
const parseLocalDate = (dateStr: string) => {
  if (!dateStr) return new Date();
  const [year, month, day] = dateStr.split('-').map(Number);
  return new Date(year, month - 1, day, 12, 0, 0); // Meio-dia para evitar problemas de borda
};

const formatLocalDate = (dateStr: string) => {
  if (!dateStr) return '-';
  const [year, month, day] = dateStr.split('-').map(Number);
  const date = new Date(year, month - 1, day);
  return date.toLocaleDateString('pt-BR');
};

const getDaysDiff = (dateStr: string) => {
  if (!dateStr) return 999;

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const [year, month, day] = dateStr.split('-').map(Number);
  const deadlineDate = new Date(year, month - 1, day);
  deadlineDate.setHours(0, 0, 0, 0);

  const diffTime = deadlineDate.getTime() - today.getTime();
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
};

const getAlertLevel = (dateStr: string, status: DeadlineStatus, greenDays: number) => {
  if (status === DeadlineStatus.COMPLETED) return 'safe';
  const diff = getDaysDiff(dateStr);
  if (diff < 0) return 'overdue';
  if (diff === 0) return 'critical';
  if (diff === 1) return 'urgent';
  if (diff <= greenDays) return 'warning';
  return 'safe';
};

const exportToCSV = (data: Deadline[]) => {
  const headers = ['Peca', 'Empresa', 'Responsavel', 'Data', 'Status', 'Assunto'];
  const csvRows = data.map(d => [
    `"${d.peca}"`,
    `"${d.empresa}"`,
    `"${d.responsavel}"`,
    d.data,
    d.status,
    `"${d.assunto.replace(/"/g, '""')}"`
  ].join(','));

  const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...csvRows].join('\n');
  const encodedUri = encodeURI(csvContent);
  const link = document.createElement("a");
  link.setAttribute("href", encodedUri);
  link.setAttribute("download", `relatorio_prazos_${new Date().toISOString().split('T')[0]}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

