                          <div className="text-right flex items-center gap-4">
                            {d.documentUrl && (
                              <a href={d.documentUrl} target="_blank" rel="noopener noreferrer" className="p-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition-colors">
                                <Icons.ExternalLink />
