                            <div>
                              <span className={`text-[10px] font-black px-5 py-2 rounded-full uppercase tracking-[0.1em] bg-slate-900 text-white`}>
                                {getDaysDiff(d.data) === 0 ? 'HOJE' : getDaysDiff(d.data) < 0 ? 'ATRASADO' : `EM ${getDaysDiff(d.data)} D`}
