export default function App() {
  const [view, setView] = useState('dashboard');
  const [deadlines, setDeadlines] = useState<Deadline[]>([]);
  const [user, setUser] = useState<AuthUser | null>(null);
  const [authLoading, setAuthLoading] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeFilter, setActiveFilter] = useState<'all' | 'overdue' | 'today' | 'tomorrow' | 'week'>('all');

  const [settings, setSettings] = useState<NotificationSettings>({
    greenAlertDays: 5,
    yellowAlertDays: 1,
    enableBrowserNotifications: true,
    notificationFrequency: 'always',
    quietMode: false,
    responsaveis: RESPONSAVEL_OPTIONS,
    pecas: PECA_OPTIONS,
    empresas: EMPRESA_OPTIONS 
  });

  const [newDeadline, setNewDeadline] = useState<Partial<Deadline>>({
    peca: '', responsavel: '', empresa: '', instituicao: '', assunto: '',
    data: new Date().toISOString().split('T')[0], hora: '', status: DeadlineStatus.PENDING, documentUrl: ''
  });

  // --- Lógica de Sincronização Simulada (Firebase Hooks Mock) ---
  // Nota: Em uma implementação final, usaríamos firebase/app e firebase/firestore reais

  useEffect(() => {
    const savedD = localStorage.getItem('juris_deadlines');
    const savedS = localStorage.getItem('juris_settings');
    const savedU = localStorage.getItem('juris_user');

    if (savedD) setDeadlines(JSON.parse(savedD));
    if (savedS) setSettings(JSON.parse(savedS));
    if (savedU) setUser(JSON.parse(savedU));
  }, []);

  useEffect(() => {
    localStorage.setItem('juris_deadlines', JSON.stringify(deadlines));
  }, [deadlines]);

  useEffect(() => {
    localStorage.setItem('juris_settings', JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
    if (user) localStorage.setItem('juris_user', JSON.stringify(user));
    else localStorage.removeItem('juris_user');
  }, [user]);

  const handleLogin = async (email: string, pass: string, isSignUp: boolean) => {
    setAuthLoading(true);
    // Simulação de delay de rede
    setTimeout(() => {
      setUser({
        uid: Math.random().toString(36),
        email: email,
        displayName: email.split('@')[0].toUpperCase()
      });
      setAuthLoading(false);
    }, 1500);
  };

  const handleLogout = () => {
    if (confirm("Deseja realmente sair? Os dados locais serão mantidos, mas a sincronização pausada.")) {
      setUser(null);
      setView('dashboard');
    }
  };

  const handleAddDeadline = (e: React.FormEvent) => {
    e.preventDefault();
    const deadline: Deadline = {
      ...(newDeadline as Deadline),
      id: Math.random().toString(36).substring(2, 11),
      createdAt: new Date().toISOString(),
      userId: user?.uid
    };
    setDeadlines(prev => [deadline, ...prev]);
    setIsModalOpen(false);
    setNewDeadline({
      peca: '', responsavel: '', empresa: '', instituicao: '', assunto: '',
      data: new Date().toISOString().split('T')[0], hora: '', status: DeadlineStatus.PENDING, documentUrl: ''
    });
  };

  // --- Mão na Massa: Cálculos e Filtros ---

  const stats = useMemo(() => {
    const list = deadlines;
    return {
      total: list.length,
      concluidos: list.filter(d => d.status === DeadlineStatus.COMPLETED).length,
      hoje: list.filter(d => d.status === DeadlineStatus.PENDING && getDaysDiff(d.data) === 0).length,
      amanha: list.filter(d => d.status === DeadlineStatus.PENDING && getDaysDiff(d.data) === 1).length,
      semana: list.filter(d => d.status === DeadlineStatus.PENDING && getDaysDiff(d.data) > 1 && getDaysDiff(d.data) <= settings.greenAlertDays).length,
