              onChange={e => setEmail(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-4">Senha</label>
            <input 
              type="password" 
              required
              className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl text-white font-bold outline-none focus:ring-4 focus:ring-blue-500/20 transition-all"
              placeholder="••••••••"
              value={password}
              onChange={e => setPassword(e.target.value)}
            />
          </div>

          <button 
            type="submit" 
            disabled={loading}
            className="w-full bg-blue-600 hover:bg-blue-700 text-white p-5 rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl shadow-blue-500/20 transition-all disabled:opacity-50"
          >
            {loading ? 'Processando...' : isSignUp ? 'Criar Minha Conta' : 'Entrar no Sistema'}
          </button>
        </form>

        <div className="mt-8 text-center">
          <button 
            onClick={() => setIsSignUp(!isSignUp)}
            className="text-[10px] font-black text-slate-400 uppercase tracking-widest hover:text-white transition-colors"
          >
            {isSignUp ? 'Já tenho acesso? Fazer Login' : 'Novo por aqui? Solicitar Acesso'}
          </button>
        </div>
      </div>
    </div>
  );
};

