                  placeholder='{ "apiKey": "...", "authDomain": "...", ... }'
                  onChange={(e) => {
                    try {
                      const cfg = JSON.parse(e.target.value);
                      setSettings(p => ({ ...p, firebaseConfig: cfg }));
