          <Icons.Dashboard /> <span className="font-bold text-sm">Dashboard</span>
        </button>
        <button onClick={() => setView('deadlines')} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all ${currentView === 'deadlines' ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/20' : 'text-slate-500 hover:bg-slate-900 hover:text-white'}`}>
          <Icons.List /> <span className="font-bold text-sm">Controle Geral</span>
        </button>
        <button onClick={() => setView('reports')} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all ${currentView === 'reports' ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/20' : 'text-slate-500 hover:bg-slate-900 hover:text-white'}`}>
          <Icons.Report /> <span className="font-bold text-sm">Relatórios</span>
        </button>
        <button onClick={() => setView('settings')} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl transition-all ${currentView === 'settings' ? 'bg-blue-600 text-white shadow-xl shadow-blue-500/20' : 'text-slate-500 hover:bg-slate-900 hover:text-white'}`}>
          <Icons.Settings /> <span className="font-bold text-sm">Gestão</span>
        </button>
      </nav>
      {user && (
        <div className="p-6 border-t border-slate-900 mx-4 mb-4 bg-white/5 rounded-3xl">
          <div className="flex items-center gap-3 mb-4 overflow-hidden">
            <div className="w-10 h-10 rounded-xl bg-blue-600 flex items-center justify-center font-black text-xs shrink-0">{user.email?.substring(0,2).toUpperCase()}</div>
            <div className="overflow-hidden">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest truncate">{user.email}</p>
