};

export default function App() {
  const [view, setView] = useState('dashboard');
  const [deadlines, setDeadlines] = useState<Deadline[]>([]);
  const [user, setUser] = useState<AuthUser | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeFilter, setActiveFilter] = useState<'all' | 'overdue' | 'today' | 'tomorrow' | 'week'>('all');
  const [aiLoading, setAiLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  const [settings, setSettings] = useState<NotificationSettings>({
    greenAlertDays: 5,
    yellowAlertDays: 1,
    enableBrowserNotifications: true,
    notificationFrequency: 'always',
    quietMode: false,
    responsaveis: RESPONSAVEL_OPTIONS,
    pecas: PECA_OPTIONS,
    empresas: EMPRESA_OPTIONS 
  });

  const [newDeadline, setNewDeadline] = useState<Partial<Deadline>>({
    peca: '', responsavel: '', empresa: '', instituicao: '', assunto: '',
    data: new Date().toISOString().split('T')[0], hora: '', status: DeadlineStatus.PENDING, documentUrl: ''
  });

  // --- Efeito de Autenticação Real ---
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (firebaseUser) => {
      if (firebaseUser) {
        setUser({
          uid: firebaseUser.uid,
          email: firebaseUser.email,
          displayName: firebaseUser.displayName
        });
      } else {
        setUser(null);
      }
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // --- Efeito de Sincronização em Tempo Real com Firestore ---
  useEffect(() => {
    if (!user) return;
    setIsSyncing(true);

    // Consulta os prazos do usuário logado ordenados por data
    const q = query(
      collection(db, "deadlines"), 
      where("userId", "==", user.uid),
      orderBy("data", "asc")
    );

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const docs = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      })) as Deadline[];
      setDeadlines(docs);
      setIsSyncing(false);
    }, (error) => {
      console.error("Firestore error:", error);
      setIsSyncing(false);
    });

    return () => unsubscribe();
  }, [user]);

  const handleLogin = async (email: string, pass: string, isSignUp: boolean) => {
    setAuthLoading(true);
    try {
      if (isSignUp) {
        await createUserWithEmailAndPassword(auth, email, pass);
      } else {
        await signInWithEmailAndPassword(auth, email, pass);
      }
    } catch (err: any) {
      alert("Erro na autenticação: " + err.message);
    } finally {
      setAuthLoading(false);
    }
  };

  const handleLogout = async () => {
    if (confirm("Deseja encerrar a sessão?")) {
      await signOut(auth);
      setView('dashboard');
    }
  };

  const handleAddDeadline = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    try {
      const deadlineData = {
        peca: newDeadline.peca,
        responsavel: newDeadline.responsavel,
        empresa: newDeadline.empresa,
        instituicao: newDeadline.instituicao || '',
        assunto: newDeadline.assunto || '',
        data: newDeadline.data,
        hora: newDeadline.hora || '',
        status: DeadlineStatus.PENDING,
        createdAt: new Date().toISOString(),
        userId: user.uid,
        documentUrl: newDeadline.documentUrl || ''
      };

      await addDoc(collection(db, "deadlines"), deadlineData);
      setIsModalOpen(false);
      setNewDeadline({
        peca: '', responsavel: '', empresa: '', instituicao: '', assunto: '',
        data: new Date().toISOString().split('T')[0], hora: '', status: DeadlineStatus.PENDING, documentUrl: ''
      });
    } catch (err: any) {
      alert("Erro ao salvar no Firebase: " + err.message);
    }
  };

  const toggleStatus = async (d: Deadline) => {
    const newStatus = d.status === DeadlineStatus.COMPLETED ? DeadlineStatus.PENDING : DeadlineStatus.COMPLETED;
    try {
      await updateDoc(doc(db, "deadlines", d.id), { status: newStatus });
    } catch (err) {
      alert("Erro ao atualizar status.");
    }
  };

  const removeDeadline = async (id: string) => {
    if (confirm("Remover este registro permanentemente da nuvem?")) {
      try {
        await deleteDoc(doc(db, "deadlines", id));
      } catch (err) {
        alert("Erro ao excluir registro.");
      }
    }
  };

  const handleAiSuggest = async () => {
    if (!newDeadline.peca || !newDeadline.empresa) {
      alert("Selecione primeiro a Peça e a Empresa.");
      return;
    }
    setAiLoading(true);
    try {
      const suggestion = await suggestActionObject(newDeadline.peca, newDeadline.empresa);
      if (suggestion) setNewDeadline(prev => ({ ...prev, assunto: suggestion }));
    } catch (err) {
      console.error(err);
    } finally {
      setAiLoading(false);
    }
  };

  const stats = useMemo(() => {
    return {
      total: deadlines.length,
      concluidos: deadlines.filter(d => d.status === DeadlineStatus.COMPLETED).length,
      hoje: deadlines.filter(d => d.status === DeadlineStatus.PENDING && getDaysDiff(d.data) === 0).length,
      amanha: deadlines.filter(d => d.status === DeadlineStatus.PENDING && getDaysDiff(d.data) === 1).length,
      semana: deadlines.filter(d => d.status === DeadlineStatus.PENDING && getDaysDiff(d.data) > 1 && getDaysDiff(d.data) <= settings.greenAlertDays).length,
      atrasados: deadlines.filter(d => d.status === DeadlineStatus.PENDING && getDaysDiff(d.data) < 0).length,
    };
  }, [deadlines, settings.greenAlertDays]);

  const filteredDeadlines = useMemo(() => {
    return deadlines.filter(d => {
      if (activeFilter === 'all') return true;
      const diff = getDaysDiff(d.data);
      if (activeFilter === 'overdue') return diff < 0 && d.status === DeadlineStatus.PENDING;
      if (activeFilter === 'today') return diff === 0 && d.status === DeadlineStatus.PENDING;
      if (activeFilter === 'tomorrow') return diff === 1 && d.status === DeadlineStatus.PENDING;
      if (activeFilter === 'week') return diff > 1 && diff <= settings.greenAlertDays && d.status === DeadlineStatus.PENDING;
      return true;
    });
  }, [deadlines, activeFilter, settings.greenAlertDays]);

  const chartData = [
    { name: 'Cumpridos', value: stats.concluidos, color: COLORS.success },
    { name: 'Atrasados', value: stats.atrasados, color: '#991b1b' }, 
    { name: 'Urgentes', value: stats.hoje, color: COLORS.danger },
    { name: 'Próximos', value: stats.amanha + stats.semana, color: COLORS.warning },
  ].filter(d => d.value > 0);

  if (authLoading) return (
    <div className="fixed inset-0 bg-slate-950 flex flex-col items-center justify-center gap-6">
      <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
      <p className="text-slate-500 font-black uppercase text-xs tracking-widest">Iniciando Conexão Segura...</p>
    </div>
  );

  if (!user) return <AuthScreen onLogin={handleLogin} loading={authLoading} />;

  return (
    <div className="flex bg-slate-50 min-h-screen text-slate-900 antialiased font-medium">
      <Sidebar currentView={view} setView={setView} user={user} onLogout={handleLogout} />
      <main className="ml-64 flex-1 p-12 relative overflow-x-hidden">
        <div className="flex justify-between items-start mb-14">
          <div>
            <h2 className="text-5xl font-black text-slate-950 tracking-tighter mb-2">
              {view === 'dashboard' && 'Dashboard'}
              {view === 'deadlines' && 'Prazos Ativos'}
              {view === 'reports' && 'Relatórios'}
              {view === 'settings' && 'Gestão'}
            </h2>
            <div className="flex items-center gap-2 text-slate-400 font-bold uppercase text-[10px] tracking-[0.2em]">
              <span className={`w-2 h-2 rounded-full ${isSyncing ? 'bg-amber-500 animate-pulse' : 'bg-emerald-500'}`} />
              {isSyncing ? 'Sincronizando Nuvem...' : 'Dados Sincronizados'}
            </div>
          </div>
          <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black flex items-center gap-3 shadow-2xl shadow-blue-500/30 hover:bg-blue-700 transition-all hover:-translate-y-1">
            <Icons.Plus /> Novo Prazo
          </button>
        </div>

        {view === 'dashboard' && (
          <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <section className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                <button onClick={() => setActiveFilter(activeFilter === 'overdue' ? 'all' : 'overdue')} className={`relative p-8 rounded-[2.5rem] border-2 transition-all text-left group ${activeFilter === 'overdue' ? 'bg-red-800 border-red-700 text-white scale-105 shadow-2xl' : 'bg-white border-slate-100 text-slate-900 shadow-sm'}`}>
                  <div className={`absolute top-0 left-0 w-2 h-full ${activeFilter === 'overdue' ? 'bg-white/20' : 'bg-red-800'}`} />
                  <p className="text-[10px] font-black uppercase tracking-widest mb-2 opacity-70">Atrasados</p>
                  <div className="flex items-end justify-between"><span className="text-6xl font-black tracking-tighter">{stats.atrasados}</span><Icons.AlertCircle /></div>
                </button>
                <button onClick={() => setActiveFilter(activeFilter === 'today' ? 'all' : 'today')} className={`relative p-8 rounded-[2.5rem] border-2 transition-all text-left group ${activeFilter === 'today' ? 'bg-red-600 border-red-500 text-white scale-105 shadow-2xl' : 'bg-white border-slate-100 text-slate-900 shadow-sm'}`}>
                  <div className={`absolute top-0 left-0 w-2 h-full ${activeFilter === 'today' ? 'bg-white/20' : 'bg-red-500'}`} />
                  <p className="text-[10px] font-black uppercase tracking-widest mb-2 opacity-70">Fatais</p>
                  <div className="flex items-end justify-between"><span className="text-6xl font-black tracking-tighter">{stats.hoje}</span><Icons.Clock /></div>
                </button>
                <button onClick={() => setActiveFilter(activeFilter === 'tomorrow' ? 'all' : 'tomorrow')} className={`relative p-8 rounded-[2.5rem] border-2 transition-all text-left group ${activeFilter === 'tomorrow' ? 'bg-amber-500 border-amber-400 text-white scale-105 shadow-2xl' : 'bg-white border-slate-100 text-slate-900 shadow-sm'}`}>
                   <div className={`absolute top-0 left-0 w-2 h-full ${activeFilter === 'tomorrow' ? 'bg-white/20' : 'bg-amber-500'}`} />
                   <p className="text-[10px] font-black uppercase tracking-widest mb-2 opacity-70">Amanhã</p>
                   <div className="flex items-end justify-between"><span className="text-6xl font-black tracking-tighter">{stats.amanha}</span><Icons.AlertCircle /></div>
                </button>
                <button onClick={() => setActiveFilter(activeFilter === 'week' ? 'all' : 'week')} className={`relative p-8 rounded-[2.5rem] border-2 transition-all text-left group ${activeFilter === 'week' ? 'bg-emerald-600 border-emerald-500 text-white scale-105 shadow-2xl' : 'bg-white border-slate-100 text-slate-900 shadow-sm'}`}>
                   <div className={`absolute top-0 left-0 w-2 h-full ${activeFilter === 'week' ? 'bg-white/20' : 'bg-emerald-500'}`} />
                   <p className="text-[10px] font-black uppercase tracking-widest mb-2 opacity-70">Próximos</p>
                   <div className="flex items-end justify-between"><span className="text-6xl font-black tracking-tighter">{stats.semana}</span><Icons.Check /></div>
                </button>
            </section>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
               <div className="lg:col-span-2 bg-white p-12 rounded-[3rem] border border-slate-100 shadow-sm">
                  <h3 className="text-2xl font-black text-slate-950 mb-10 tracking-tight flex items-center gap-3"><Icons.Table /> Próximas Entregas</h3>
                  <div className="space-y-6">
                    {filteredDeadlines.slice(0, 8).map(d => (
                        <div key={d.id} className="rounded-3xl border border-slate-100 p-8 flex justify-between items-center bg-slate-50/50">
                          <div className="flex items-center gap-6">
                             <div className={`w-3 h-12 rounded-full ${getAlertLevel(d.data, d.status, settings.greenAlertDays) === 'overdue' ? 'bg-red-800' : getAlertLevel(d.data, d.status, settings.greenAlertDays) === 'critical' ? 'bg-red-500 animate-pulse' : 'bg-emerald-500'}`} />
                             <div>
                                <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-1 block">{d.empresa}</span>
                                <h4 className="font-black text-slate-900 text-lg leading-none">{d.peca}</h4>
                             </div>
                          </div>
                          <div className="text-right">
                            <span className="text-[10px] font-black px-5 py-2 rounded-full uppercase bg-slate-900 text-white">{formatLocalDate(d.data)}</span>
                          </div>
                        </div>
                    ))}
                    {filteredDeadlines.length === 0 && <p className="text-center py-10 text-slate-300 uppercase font-black tracking-widest">Nenhum prazo encontrado</p>}
                  </div>
               </div>
               <div className="bg-slate-950 p-10 rounded-[3rem] text-white shadow-2xl flex flex-col justify-between h-fit">
                  <h3 className="text-lg font-black mb-8 tracking-tight">Status Cloud</h3>
                  <div className="h-64"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={chartData} cx="50%" cy="50%" innerRadius={70} outerRadius={95} paddingAngle={10} dataKey="value" stroke="none">{chartData.map((e, i) => <Cell key={i} fill={e.color} />)}</Pie><Tooltip /></PieChart></ResponsiveContainer></div>
