             </div>
             <div className="divide-y divide-slate-100">
                {deadlines.map(d => (
                    <div key={d.id} className="hover:bg-slate-50/80 transition-all flex flex-col">
                      <div className="px-10 py-8 grid grid-cols-1 md:grid-cols-12 gap-6 items-center">
