                        </div>
                        <div className="md:col-span-2 text-center"><span className="px-4 py-1.5 bg-slate-100 rounded-xl text-[10px] font-black text-slate-600 uppercase">{d.responsavel}</span></div>
                        <div className="md:col-span-2 text-center flex flex-col">
                          <span className="font-black text-slate-950 text-sm">{formatLocalDate(d.data)}</span>
                          <span className="text-[9px] font-black text-blue-600 uppercase">{d.hora}</span>
                        </div>
                        <div className="md:col-span-3 flex justify-center items-center gap-4">
                          <button onClick={() => toggleStatus(d)} className={`px-5 py-2 rounded-full text-[10px] font-black uppercase border transition-all ${d.status === DeadlineStatus.COMPLETED ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-amber-50 text-amber-700 border-amber-100'}`}>{d.status}</button>
                          <button onClick={() => removeDeadline(d.id)} className="p-3 bg-red-50 text-red-600 rounded-2xl hover:bg-red-100 transition-colors"><Icons.Trash /></button>
                        </div>
                      </div>
                      <div className="bg-slate-50/50 px-10 py-5 border-t border-slate-100">
                         <p className="text-[11px] text-slate-500 italic"><span className="text-[9px] font-black uppercase text-slate-400 mr-2">Objeto:</span>{d.assunto}</p>
                      </div>
                    </div>
                ))}
                {deadlines.length === 0 && <div className="p-32 text-center text-slate-300 font-black italic">Nenhum registro ativo na nuvem</div>}
             </div>
          </div>
        )}

        <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Novo Prazo Processual">
          <form onSubmit={handleAddDeadline} className="grid grid-cols-2 gap-8">
            <div className="col-span-1">
              <label className="block text-[10px] font-black text-slate-400 uppercase mb-4">Peça</label>
              <select className="w-full bg-slate-50 border border-slate-100 p-6 rounded-3xl font-black text-sm outline-none" value={newDeadline.peca} onChange={e => setNewDeadline(p => ({ ...p, peca: e.target.value }))} required>
                <option value="">SELECIONE...</option>
                {settings.pecas.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
            <div className="col-span-1">
              <label className="block text-[10px] font-black text-slate-400 uppercase mb-4">Empresa</label>
              <select className="w-full bg-slate-50 border border-slate-100 p-6 rounded-3xl font-black text-sm outline-none" value={newDeadline.empresa} onChange={e => setNewDeadline(p => ({ ...p, empresa: e.target.value }))} required>
                <option value="">SELECIONE...</option>
                {settings.empresas.map(e => <option key={e} value={e}>{e}</option>)}
              </select>
            </div>
            <div className="col-span-1">
              <label className="block text-[10px] font-black text-slate-400 uppercase mb-4">Vencimento</label>
              <input type="date" className="w-full bg-slate-50 border border-slate-100 p-6 rounded-3xl font-black text-sm outline-none" value={newDeadline.data} onChange={e => setNewDeadline(p => ({ ...p, data: e.target.value }))} required />
            </div>
            <div className="col-span-1">
              <label className="block text-[10px] font-black text-slate-400 uppercase mb-4">Advogado</label>
              <select className="w-full bg-slate-50 border border-slate-100 p-6 rounded-3xl font-black text-sm outline-none" value={newDeadline.responsavel} onChange={e => setNewDeadline(p => ({ ...p, responsavel: e.target.value }))} required>
                {settings.responsaveis.map(r => <option key={r} value={r}>{r}</option>)}
              </select>
            </div>
            <div className="col-span-2">
              <div className="flex justify-between items-center mb-4">
                <label className="text-[10px] font-black text-slate-400 uppercase">Objeto / Providência</label>
                <button type="button" onClick={handleAiSuggest} disabled={aiLoading} className="text-[10px] font-black text-blue-600 uppercase flex items-center gap-2 disabled:opacity-50"><Icons.Sparkles /> {aiLoading ? 'Processando...' : 'Sugerir com IA'}</button>
              </div>
              <textarea className="w-full bg-slate-50 border border-slate-100 p-6 rounded-3xl font-black min-h-[120px] text-sm outline-none" value={newDeadline.assunto} onChange={e => setNewDeadline(p => ({ ...p, assunto: e.target.value }))} required />
            </div>
            <div className="col-span-2 pt-8 border-t flex justify-end gap-6">
              <button type="submit" className="bg-slate-950 text-white px-12 py-5 rounded-[2rem] font-black uppercase text-[10px] shadow-2xl hover:bg-slate-900 transition-all">Salvar na Nuvem</button>
            </div>
          </form>
        </Modal>
      </main>
    </div>
  );
}

