          <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.2em] mt-2">Nuvem Conectada</p>
        </div>
        <form onSubmit={(e) => { e.preventDefault(); onLogin(email, password, isSignUp); }} className="space-y-6">
