export default function App() {
  const [view, setView] = useState('dashboard');
  const [deadlines, setDeadlines] = useState<Deadline[]>([]);
  const [user, setUser] = useState<AuthUser | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  const [dynamicSettings, setDynamicSettings] = useState<NotificationSettings>({
    greenAlertDays: 5,
    yellowAlertDays: 1,
    enableBrowserNotifications: true,
    notificationFrequency: 'always',
    quietMode: false,
    responsaveis: INITIAL_RESPONSAVEIS,
    pecas: INITIAL_PECAS,
    empresas: INITIAL_EMPRESAS 
  });

  const [newDeadline, setNewDeadline] = useState<Partial<Deadline>>({
    peca: '', responsavel: '', empresa: '', assunto: '',
    data: new Date().toISOString().split('T')[0], status: DeadlineStatus.PENDING
  });

  // Listener de Autenticação
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (firebaseUser) => {
      if (firebaseUser) {
        setUser({ uid: firebaseUser.uid, email: firebaseUser.email, displayName: firebaseUser.displayName });
      } else {
        setUser(null);
      }
      setAuthLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // Listener de Configurações Dinâmicas
  useEffect(() => {
    if (!user) return;
    const settingsRef = doc(db, "settings", user.uid);
    const unsubscribe = onSnapshot(settingsRef, (docSnap) => {
      if (docSnap.exists()) {
        setDynamicSettings(prev => ({ ...prev, ...docSnap.data() }));
      } else {
        // Inicializa com padrões se for a primeira vez
        setDoc(settingsRef, {
          responsaveis: INITIAL_RESPONSAVEIS,
          pecas: INITIAL_PECAS,
          empresas: INITIAL_EMPRESAS
        });
      }
    });
    return () => unsubscribe();
  }, [user]);

  // Listener de Prazos
  useEffect(() => {
    if (!user) return;
    setIsSyncing(true);
    const q = query(collection(db, "deadlines"), where("userId", "==", user.uid), orderBy("data", "asc"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      setDeadlines(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })) as Deadline[]);
      setIsSyncing(false);
    }, () => setIsSyncing(false));
    return () => unsubscribe();
  }, [user]);

  const handleLogin = async (email: string, pass: string, isSignUp: boolean) => {
    setAuthLoading(true);
    try {
      if (isSignUp) await createUserWithEmailAndPassword(auth, email, pass);
      else await signInWithEmailAndPassword(auth, email, pass);
    } catch (err: any) { alert("Erro: " + err.message); }
    finally { setAuthLoading(false); }
  };

  const handleAddDeadline = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;
    try {
      await addDoc(collection(db, "deadlines"), {
        ...newDeadline,
        userId: user.uid,
        createdAt: new Date().toISOString()
      });
      setIsModalOpen(false);
      setNewDeadline(prev => ({ ...prev, assunto: '' }));
    } catch (err: any) { alert("Erro ao salvar: " + err.message); }
  };

  const updateSettings = async (field: keyof NotificationSettings, newValue: any) => {
    if (!user) return;
    const settingsRef = doc(db, "settings", user.uid);
    await updateDoc(settingsRef, { [field]: newValue });
  };

  const toggleStatus = async (d: Deadline) => {
    const newS = d.status === DeadlineStatus.COMPLETED ? DeadlineStatus.PENDING : DeadlineStatus.COMPLETED;
    await updateDoc(doc(db, "deadlines", d.id), { status: newS });
  };

  const deleteDeadline = async (id: string) => {
    if (confirm("Remover este prazo permanentemente?")) await deleteDoc(doc(db, "deadlines", id));
  };

  const stats = useMemo(() => ({
    concluidos: deadlines.filter(d => d.status === DeadlineStatus.COMPLETED).length,
    hoje: deadlines.filter(d => d.status === DeadlineStatus.PENDING && getDaysDiff(d.data) === 0).length,
    atrasados: deadlines.filter(d => d.status === DeadlineStatus.PENDING && getDaysDiff(d.data) < 0).length,
  }), [deadlines]);

  if (authLoading) return <div className="fixed inset-0 bg-slate-950 flex items-center justify-center text-white font-black uppercase text-xs tracking-widest">Iniciando JurisControl...</div>;
  if (!user) return <AuthScreen onLogin={handleLogin} loading={authLoading} />;

  return (
    <div className="flex bg-slate-50 min-h-screen antialiased">
      <Sidebar currentView={view} setView={setView} user={user} onLogout={() => signOut(auth)} />

      <main className="ml-64 flex-1 p-12">
        <header className="flex justify-between items-start mb-12">
          <div>
            <h2 className="text-4xl font-black text-slate-950 tracking-tighter mb-2">
              {view === 'dashboard' ? 'Painel de Controle' : view === 'deadlines' ? 'Lista de Prazos' : 'Gestão do Escritório'}
            </h2>
            <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <span className={`w-2 h-2 rounded-full ${isSyncing ? 'bg-amber-500 animate-pulse' : 'bg-emerald-500'}`} />
              Nuvem Ativa: {user.email?.split('@')[0].toUpperCase()}
            </div>
          </div>
          <button onClick={() => setIsModalOpen(true)} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black shadow-xl shadow-blue-500/20 hover:bg-blue-700 transition-all active:scale-95">+ Novo Registro</button>
        </header>

        {view === 'dashboard' && (
          <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-500">
             <section className="grid grid-cols-3 gap-8">
                <div className="bg-red-900/90 p-10 rounded-[2.5rem] text-white shadow-2xl dashboard-card">
                   <p className="text-[10px] font-black uppercase tracking-widest mb-4 opacity-70">Atrasados</p>
                   <span className="text-7xl font-black tracking-tighter block leading-none">{stats.atrasados}</span>
                </div>
                <div className="bg-red-600 p-10 rounded-[2.5rem] text-white shadow-2xl dashboard-card">
                   <p className="text-[10px] font-black uppercase tracking-widest mb-4 opacity-70">Prazos de Hoje</p>
                   <span className="text-7xl font-black tracking-tighter block leading-none">{stats.hoje}</span>
                </div>
                <div className="bg-emerald-600 p-10 rounded-[2.5rem] text-white shadow-2xl dashboard-card">
                   <p className="text-[10px] font-black uppercase tracking-widest mb-4 opacity-70">Concluídos</p>
                   <span className="text-7xl font-black tracking-tighter block leading-none">{stats.concluidos}</span>
                </div>
             </section>

             <div className="bg-white p-12 rounded-[3.5rem] border border-slate-100 shadow-sm">
                <h3 className="text-2xl font-black mb-10 tracking-tight">Prazos Próximos</h3>
                <div className="space-y-4">
                  {deadlines.filter(d => d.status === DeadlineStatus.PENDING).slice(0, 6).map(d => (
                    <div key={d.id} className="flex justify-between items-center p-8 bg-slate-50/50 rounded-3xl border border-slate-50 hover:border-blue-100 transition-all group">
                      <div>
                        <p className="text-[10px] font-black text-slate-400 uppercase mb-1 tracking-wider">{d.empresa}</p>
                        <h4 className="font-black text-slate-900 text-lg group-hover:text-blue-600 transition-colors">{d.peca}</h4>
                        <p className="text-xs text-slate-500 mt-1 italic opacity-60">"{d.assunto.substring(0, 60)}..."</p>
                      </div>
                      <div className="flex items-center gap-6">
                        <span className="bg-slate-900 text-white px-6 py-3 rounded-2xl text-[11px] font-black shadow-lg shadow-slate-200">{formatLocalDate(d.data)}</span>
                        <button onClick={() => toggleStatus(d)} className="p-4 bg-white border border-slate-100 text-emerald-600 rounded-2xl hover:bg-emerald-600 hover:text-white transition-all shadow-sm"><Icons.Check /></button>
                      </div>
                    </div>
                  ))}
                  {deadlines.filter(d => d.status === DeadlineStatus.PENDING).length === 0 && (
                    <div className="p-20 text-center bg-slate-50 rounded-3xl border-2 border-dashed border-slate-100">
                      <p className="font-black text-slate-300 uppercase italic">Nenhum prazo pendente. Bom trabalho!</p>
                    </div>
                  )}
                </div>
             </div>
          </div>
        )}

        {view === 'deadlines' && (
          <div className="bg-white rounded-[3.5rem] border border-slate-100 shadow-2xl overflow-hidden animate-in fade-in duration-500">
             <div className="divide-y divide-slate-50">
                {deadlines.map(d => (
                  <div key={d.id} className="p-10 hover:bg-slate-50/50 transition-all flex justify-between items-center group">
                    <div className="flex-1 pr-8">
                      <div className="flex items-center gap-3">
                        <span className="font-black text-slate-900 text-xl leading-none">{d.peca}</span>
